def _path_from_file_ref(file_ref):
    """Путь на диске: file:// URL (LibreOffice) или обычный путь."""
    s = unicode(file_ref or u'').strip()
    if s == u'':
        return u''
    if s.lower().startswith(u'file://'):
        try:
            return os.path.normpath(uno.fileUrlToSystemPath(s))
        except Exception:
            return u''
    try:
        return os.path.normpath(os.path.abspath(s))
    except Exception:
        return u''

def _macro_dir_from_module_file(module_file):
    """Каталог .py модуля (param_wizard / collect в LO)."""
    path = _path_from_file_ref(module_file)
    if path == u'':
        return None
    try:
        d = os.path.dirname(path)
        if d and os.path.isdir(d):
            return d
    except Exception:
        pass
    return None
try:
    _here = _macro_dir_from_module_file(__file__)
    if not _here:
        _here = os.path.dirname(os.path.abspath(__file__))
    _pp = os.path.join(_here, u'pythonpath')
    for _p in (_pp, _here):
        if _p not in sys.path:
            sys.path.insert(0, _p)
except Exception:
    pass
