def _merge_pp_rest_hints(base, extra):
    """Объединить словари подсказок (ключи — unicode)."""
    out = {}
    for k, v in (base or {}).items():
        out[unicode(k)] = v
    if extra:
        for k, v in extra.items():
            out[unicode(k)] = v
    return out

def _rest_hint_lookup(rest_hints, key):
    """Найти подсказку по имени функции (точное, без регистра, через normalize_fn_key)."""
    if not rest_hints or key is None:
        return None
    k = unicode(key).strip()
    if k == u'':
        return None
    if k in rest_hints:
        return rest_hints[k]
    kl = k.lower()
    for name, item in rest_hints.items():
        if unicode(name).strip().lower() == kl:
            return item
    try:
        from libre_macros_param_codec import normalize_fn_key
        norm = unicode(normalize_fn_key(k) or u'').strip()
    except Exception:
        norm = u''
    if norm != u'' and norm != k:
        item = _rest_hint_lookup(rest_hints, norm)
        if item is not None:
            return item
    if norm != u'':
        for name, item in rest_hints.items():
            if not isinstance(item, (tuple, list)) or len(item) < 1:
                continue
            desc = unicode(item[0] or u'')
            if u'алиас' in desc.lower() and norm in desc:
                canon = _rest_hint_lookup(rest_hints, unicode(name).strip())
                if canon is not None:
                    return canon
    return None

def _try_import_lm():
    """libre_macros_lib — разбор Да/Нет без collect_workbooks."""
    if _pw_cfg._LM_LIB is False:
        return None
    if _pw_cfg._LM_LIB is None:
        try:
            import sys
            here = _macro_dir_from_module_file(__file__)
            if not here:
                here = os.path.dirname(os.path.abspath(__file__))
            pp = os.path.join(here, u'pythonpath')
            for p in (pp, here):
                if p not in sys.path:
                    sys.path.insert(0, p)
            import libre_macros_lib as lm
            _pw_cfg._LM_LIB = lm
        except Exception as err:
            print(u'param_wizard: не удалось загрузить libre_macros_lib: %s' % err)
            _pw_cfg._LM_LIB = False
    return _pw_cfg._LM_LIB if _pw_cfg._LM_LIB is not False else None

