def _plugin_macro_script_dirs():
    """Каталоги поиска functions_*.py: сначала param_wizard, затем collect_workbooks."""
    dirs = []
    seen = set()

    def _add(path):
        if not path:
            return
        try:
            norm = os.path.normpath(os.path.abspath(path))
        except Exception:
            return
        if os.path.isdir(norm) and norm not in seen:
            seen.add(norm)
            dirs.append(norm)
    try:
        _add(_macro_dir_from_module_file(__file__))
    except Exception:
        pass
    cw = _try_import_collect()
    if cw is not None and hasattr(cw, '_merge_macro_script_dir'):
        try:
            _add(cw._merge_macro_script_dir())
        except Exception:
            pass
    return dirs

def _plugin_macro_script_dir():
    """Первый каталог из _plugin_macro_script_dirs (для совместимости)."""
    dirs = _plugin_macro_script_dirs()
    if dirs:
        return dirs[0]
    d = _macro_dir_from_module_file(__file__)
    if d:
        return d
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except Exception:
        return os.getcwd()

def _glob_functions_plugin_files():
    """Все functions_*.py рядом с param_wizard и/или collect_workbooks."""
    out = []
    seen = set()
    for script_dir in _plugin_macro_script_dirs():
        pattern = os.path.join(script_dir, 'functions_*.py')
        if _pw_cfg.PARAM_WIZARD_DEBUG:
            _pw_dbg(u'plugin glob pattern: %s' % pattern)
        for path in sorted(glob.glob(pattern)):
            norm = os.path.normpath(path)
            if os.path.isfile(norm) and norm not in seen:
                seen.add(norm)
                out.append(norm)
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        _pw_dbg_kv(u'plugin functions_*.py found', out)
    return out

def _parse_py_file_ast(abs_path):
    try:
        f = open(abs_path, 'rb')
        try:
            raw = f.read()
        finally:
            f.close()
        if raw.startswith(b'\xef\xbb\xbf'):
            text = raw[3:].decode('utf-8')
        else:
            text = raw.decode('utf-8')
        return ast.parse(text)
    except Exception as err:
        if _pw_cfg.PARAM_WIZARD_DEBUG:
            _pw_dbg(u'plugin AST parse fail %s: %s' % (abs_path, err))
        return None

def _fn_def_matches_signature(func_def, sig_prefix):
    if not isinstance(func_def, ast.FunctionDef):
        return False
    names = [a.arg for a in func_def.args.args]
    if len(names) < len(sig_prefix):
        return False
    i = 0
    while i < len(sig_prefix):
        if names[i] != sig_prefix[i]:
            return False
        i = i + 1
    return True

def _fn_def_plugin_kind(func_def):
    """range | row | final | None — по сигнатуре пользовательского плагина."""
    if _fn_def_matches_signature(func_def, _pw_cfg._PP_PLUGIN_SIG_FINAL):
        return 'final'
    if _fn_def_matches_signature(func_def, _pw_cfg._PP_PLUGIN_SIG_ROW):
        return 'row'
    if _fn_def_matches_signature(func_def, _pw_cfg._PP_PLUGIN_SIG_RANGE):
        return 'range'
    return None

def _pw_dbg_plugin_signature_hint(kind):
    want = unicode(kind or u'').strip().lower()
    if want == 'final':
        sig = _pw_cfg._PP_PLUGIN_SIG_FINAL
    elif want == 'row':
        sig = _pw_cfg._PP_PLUGIN_SIG_ROW
    else:
        sig = _pw_cfg._PP_PLUGIN_SIG_RANGE
    _pw_dbg(u'plugin expected signature (%s): (%s, *extra_args)' % (want, u', '.join(sig)))

def _scan_functions_plugin_choices(kind):
    """
    functions_*.py#func рядом с макросом; kind = range | row | final.
    """
    want = unicode(kind or u'').strip().lower()
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        _pw_dbg(u'--- plugin scan start kind=%s ---' % want)
        _pw_dbg_kv(u'plugin __file__', __file__)
        _pw_dbg_kv(u'plugin __file__ dir', _macro_dir_from_module_file(__file__))
        _pw_dbg_kv(u'plugin script dirs', _plugin_macro_script_dirs())
        _pw_dbg_plugin_signature_hint(want)
    out = []
    for abs_path in _glob_functions_plugin_files():
        rel = os.path.basename(abs_path)
        tree = _parse_py_file_ast(abs_path)
        if tree is None:
            continue
        defs_total = 0
        defs_matched = 0
        for node in tree.body:
            if not isinstance(node, ast.FunctionDef):
                continue
            defs_total = defs_total + 1
            names = [a.arg for a in node.args.args]
            pk = _fn_def_plugin_kind(node)
            if pk != want:
                if _pw_cfg.PARAM_WIZARD_DEBUG:
                    _pw_dbg(u'plugin skip %s#%s args=%s detected=%s want=%s' % (rel, node.name, names, pk, want))
                continue
            defs_matched = defs_matched + 1
            out.append(u'%s#%s' % (rel, node.name))
        if _pw_cfg.PARAM_WIZARD_DEBUG:
            _pw_dbg(u'plugin file %s: %d def(s), %d matched kind=%s' % (rel, defs_total, defs_matched, want))
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        _pw_dbg_kv(u'plugin choices (%s)' % want, out)
        _pw_dbg(u'--- plugin scan end kind=%s count=%d ---' % (want, len(out)))
    return sorted(out, key=lambda x: unicode(x).casefold())

