def _scan_functions_pp_choices():
    """
    Ссылки functions_pp.py#имя для выпадающих списков визарда.
    pp_row_* → постобработка строки; остальные pp_* → диапазон.
    """
    range_choices = []
    row_choices = []
    for abs_path in _functions_pp_file_paths():
        rel = os.path.basename(abs_path)
        try:
            f = open(abs_path, 'rb')
            try:
                raw = f.read()
            finally:
                f.close()
            if raw.startswith(b'\xef\xbb\xbf'):
                text = raw[3:].decode('utf-8')
            else:
                text = raw.decode('utf-8')
            tree = ast.parse(text)
        except Exception:
            continue
        for node in tree.body:
            if not isinstance(node, ast.FunctionDef):
                continue
            name = node.name
            if not name.startswith('pp_'):
                continue
            ref = u'%s#%s' % (rel, name)
            if name.startswith('pp_row_'):
                row_choices.append(ref)
            else:
                range_choices.append(ref)
    return (range_choices, row_choices)

