def _pp_allows_freeform_b(text):
    """Колонка B/C: ссылка на .py#func или inline lambda/def (не из выпадающего списка)."""
    t = unicode(text).strip()
    if t == u'':
        return False
    cw = _try_import_collect()
    if cw is not None:
        try:
            if cw._merge_pp_looks_like_file_function_ref(t):
                return True
            if cw._merge_pp_looks_like_python_code(t):
                return True
        except Exception:
            pass
    if u'.py#' in t and t.count(u'#') == 1:
        path_part, fn_name = t.split(u'#', 1)
        if path_part.strip() != u'' and fn_name.strip() != u'':
            return True
    if t.startswith(u'lambda') or t.startswith(u'def '):
        return True
    if u'\n' in t and (u'def ' in t or u'lambda ' in t):
        return True
    return False

def _pp_plugin_key():
    cw = _try_import_collect()
    if cw is not None:
        return unicode(getattr(cw, 'MERGE_PLUGIN_FUNCTION_KEY', _pw_cfg.PLUGIN_FUNCTION_KEY))
    return _pw_cfg.PLUGIN_FUNCTION_KEY

def _pp_is_plugin_primary(text):
    key = unicode(text or u'').strip().casefold()
    return key in (_pw_cfg.PLUGIN_FUNCTION_KEY.casefold(), u'plugin_function', u'plugin', _pp_plugin_key().casefold())

def _pp_allows_freeform_c(text):
    return _pp_allows_freeform_b(text)

def _pp_is_plugin_json_c(text):
    """Колонка C: JSON-массив с блоком функция_плагин (из диалога «Сохранять как JSON»)."""
    t = unicode(text or u'').strip()
    if not (t.startswith(u'[{') and t.endswith(u'}]')):
        return False
    try:
        parsed = json.loads(t)
    except Exception:
        return False
    if not isinstance(parsed, list) or len(parsed) == 0:
        return False
    block = parsed[0]
    if not isinstance(block, dict):
        return False
    fn = unicode(block.get('fn') or u'').strip().casefold()
    return fn in (_pw_cfg.PLUGIN_FUNCTION_KEY.casefold(), u'plugin_function', u'plugin', _pp_plugin_key().casefold())

def _pp_catalog_choices_with_plugin(choices):
    """Убрать file# из combo B; добавить «функция_плагин»."""
    out = []
    seen = set()
    pk = _pp_plugin_key()
    for c in choices or []:
        cs = unicode(c)
        if u'.py#' in cs:
            continue
        k = cs.casefold()
        if k in seen:
            continue
        seen.add(k)
        out.append(cs)
    if pk.casefold() not in seen:
        out.append(pk)
    return sorted(out, key=lambda x: unicode(x).casefold())

def _final_wizard_choices(cw):
    """
    Ключи для combo «Финальная_обработка»: карта + spec + fallback.
    Иначе новая fn из _FINAL_MAP_SPEC не видна в визарде, пока merge_* не подхватился.
    """
    keys = set(_pw_cfg._FALLBACK_FINAL_CHOICES or ())
    if cw is not None:
        try:
            keys.update(cw.MERGE_FINAL_PROCESSING_MAP.keys())
        except Exception:
            pass
        try:
            cfg = cw._cw_cfg
            for key, _merge_name in getattr(cfg, '_FINAL_MAP_SPEC', ()) or ():
                k = unicode(key or u'').strip()
                if k != u'':
                    keys.add(k)
        except Exception:
            pass
    return sorted(keys, key=lambda x: unicode(x).casefold())

def _plugin_scan_for_spec(spec):
    """Список functions_*.py#func для диалога плагина (по сигнатуре)."""
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        spec_name = spec.get('name') if spec is not None else None
        spec_mode = spec.get('mode') if spec is not None else None
        _pw_dbg(u'plugin_scan_for_spec name=%s mode=%s' % (spec_name, spec_mode))
    if spec is not None and _param_match(spec.get('name', u''), u'Финальная_обработка'):
        return _scan_functions_plugin_choices('final')
    mode = spec.get('mode') if spec is not None else u''
    if mode == u'postprocess_row':
        return _scan_functions_plugin_choices('row')
    return _scan_functions_plugin_choices('range')

def _plugin_block_list_label(block):
    """Подпись блока в списке: лист + ref/extra."""
    sheet = unicode(block.get('sheet') or u'').strip()
    if block.get('code'):
        tail = u'Python'
    else:
        ref = unicode(block.get('ref') or block.get('c') or u'').strip()
        if u'#' in ref:
            tail = ref.split(u'#', 1)[-1]
        else:
            tail = ref[:24] + (u'…' if len(ref) > 24 else u'')
    extra = unicode(block.get('extra') or block.get('d') or u'').strip()
    if extra:
        xs = extra[:16] + (u'…' if len(extra) > 16 else u'')
        tail = u'%s · %s' % (tail, xs)
    return _inner_block_list_label(sheet, tail)

def _plugin_blocks_from_initial(initial_ref, initial_extra):
    """Разбор C/D или legacy ref в список блоков плагина."""
    init_ref = unicode(initial_ref or u'').strip()
    init_extra = unicode(initial_extra or u'').strip()
    blocks = []
    if init_ref.startswith(u'[{') and init_ref.endswith(u'}]'):
        try:
            parsed = json.loads(init_ref)
            if isinstance(parsed, list):
                for item in parsed:
                    if not isinstance(item, dict):
                        continue
                    fn = unicode(item.get('fn') or u'').strip()
                    if fn != _pw_cfg.PLUGIN_FUNCTION_KEY:
                        continue
                    blocks.append(dict(item))
        except Exception:
            pass
    if len(blocks) == 0 and init_ref != u'':
        b = {'v': 1, 'fn': _pw_cfg.PLUGIN_FUNCTION_KEY}
        if _pp_allows_freeform_c(init_ref) and (u'def ' in init_ref or u'lambda' in init_ref.lower()):
            b['code'] = init_ref
        else:
            b['ref'] = init_ref
        if init_extra != u'':
            b['extra'] = init_extra
        blocks = [b]
    if len(blocks) == 0:
        blocks = [{'v': 1, 'fn': _pw_cfg.PLUGIN_FUNCTION_KEY}]
    for b in blocks:
        b['v'] = 1
        b['fn'] = _pw_cfg.PLUGIN_FUNCTION_KEY
    return blocks

def _show_plugin_function_dialog(parent_dialog, spec, initial_ref=u'', initial_extra=u'', doc=None):
    """
    Диалог пользовательской функции (блоки по листам, как у встроенных функций).
    C = JSON-массив [{ref|code, extra, sheet}, …]; D пусто.
    Возвращает (c_ref, d_extra) или None.
    """
    choices = _plugin_scan_for_spec(spec)
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        _pw_dbg_kv(u'plugin dialog RefCombo items', choices)
    norm_blocks = _plugin_blocks_from_initial(initial_ref, initial_extra)
    same_all_init = len(norm_blocks) <= 1 and all((not unicode(b.get('sheet') or u'').strip() for b in norm_blocks))
    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 560
    dh = _inner_dialog_height(_pw_cfg._INNER_GRID_DH)
    m = 10
    dm.PositionX = 120
    dm.PositionY = 80
    dm.Width = dw
    dm.Height = dh
    dm.Title = u'Пользовательская функция'
    _inner_dialog_set_sizeable(dm)
    y = m
    _wizard_dlg_add_fixed(dm, 'HintLbl', u'B = «функция_плагин». Слева — лист; справа — ссылка functions_*.py#имя или Python-код и доп. аргументы (extra).', m, y, dw - m * 2, 28, multiline=True)
    y += 34
    col_gap = 10
    left_w = 190
    right_w = dw - m * 2 - left_w - col_gap
    rx = m + left_w + col_gap
    _wizard_dlg_add_checkbox(dm, 'SameAllChk', u'Одинаково на всех листах', m, y, left_w + col_gap - 4, 16)
    _wizard_dlg_add_fixed(dm, 'ParamsLbl', u'Параметры:', rx, y, right_w, 14)
    fy = y + 16
    y += 22
    form_h = 16 + 18 + 20 + 14 + 72 + 24 + 14 + 18
    list_top = y + 16
    list_h = _inner_grid_list_height(dh, list_top, m, min_h=72)
    list_h = min(list_h, max(72, dh - list_top - _pw_cfg._INNER_FOOTER_RESERVE - form_h - _pw_cfg._INNER_GRID_CONTROLS_H - _pw_cfg._INNER_GRID_LIST_GAP))
    _wizard_dlg_add_fixed(dm, 'BlocksLbl', u'Блоки:', m, y, left_w, 14)
    y += 16
    _wizard_dlg_add_listbox(dm, 'BlocksLB', m, y, left_w, list_h, multiselect=False)
    _wizard_dlg_add_fixed(dm, 'RefLbl', u'Ссылка на функцию:', rx, fy, right_w, 12)
    fy += 14
    _wizard_dlg_add_combo(dm, 'RefCombo', rx, fy, right_w, 18)
    fy += 22
    _wizard_dlg_add_checkbox(dm, 'CodeChk', u'Свой Python-код вместо file#func', rx, fy, right_w, 16)
    fy += 20
    _wizard_dlg_add_fixed(dm, 'CodeLbl', u'Код (lambda или def …):', rx, fy, right_w, 12)
    fy += 14
    _wizard_dlg_add_edit(dm, 'CodeEd', rx, fy, right_w, 72, multiline=True)
    fy += 78
    _wizard_dlg_add_fixed(dm, 'ExtraLbl', u'Доп. аргументы (extra):', rx, fy, right_w, 12)
    fy += 14
    _wizard_dlg_add_edit(dm, 'ExtraEd', rx, fy, right_w, 18)
    y2 = y + list_h + 8
    _wizard_dlg_add_fixed(dm, 'SheetLbl', u'Лист (пусто = все листы):', m, y2, left_w, 14)
    _wizard_dlg_add_combo(dm, 'SheetEd', m, y2 + 16, left_w, 18)
    _wizard_dlg_add_button(dm, 'AddBlockBtn', u'+ Блок', m, y2 + 40, 80, 16)
    _wizard_dlg_add_button(dm, 'DelBlockBtn', u'Удалить', m + 90, y2 + 40, 80, 16)
    _inner_dialog_add_footer(dm, m, dh, help_btn=True, dw=dw)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    _wizard_wire_help_button(dlg, doc=doc)

    blocks_lb = dlg.getControl('BlocksLB')
    sheet_ed = dlg.getControl('SheetEd')
    ref_combo = dlg.getControl('RefCombo')
    code_chk = dlg.getControl('CodeChk')
    code_ed = dlg.getControl('CodeEd')
    extra_ed = dlg.getControl('ExtraEd')
    same_all_chk = dlg.getControl('SameAllChk')
    combo_items = [u''] + list(choices)
    _set_combo_items(ref_combo, combo_items, u'')
    doc_sheet_names = _pivot_list_doc_sheet_names(doc)
    if len(doc_sheet_names) > 0:
        try:
            _set_combo_items(sheet_ed, doc_sheet_names, select_text=u'')
        except Exception:
            pass
    try:
        same_all_chk.setState(1 if same_all_init else 0)
    except Exception:
        pass
    try:
        dlg.getControl('JsonChk').setState(1)
    except Exception:
        pass
    form_block_index = [-1]
    sheet_field_guard = [False]
    form_loading = [False]

    def _sync_code_mode():
        code_on = False
        try:
            code_on = bool(code_chk.getState())
        except Exception:
            pass
        for ctl_name in ('RefCombo', 'RefLbl'):
            try:
                dlg.getControl(ctl_name).Model.Enabled = not code_on
            except Exception:
                pass
        for ctl_name in ('CodeEd', 'CodeLbl'):
            try:
                dlg.getControl(ctl_name).Model.Enabled = code_on
            except Exception:
                pass

    def _refresh_blocks(selected_index=0):
        form_loading[0] = True
        items = [_plugin_block_list_label(b) for b in norm_blocks]
        try:
            blocks_lb.Model.StringItemList = tuple(items)
        except Exception:
            pass
        try:
            if len(items) > 0:
                blocks_lb.selectItemPos(max(0, min(selected_index, len(items) - 1)), True)
        except Exception:
            pass
        form_loading[0] = False

    def _block_index_selected():
        try:
            pos = blocks_lb.getSelectedItemPos()
            return int(pos) if pos is not None else -1
        except Exception:
            return -1

    def _load_block_to_form(block_index):
        form_loading[0] = True
        form_block_index[0] = block_index
        if block_index < 0 or block_index >= len(norm_blocks):
            _inner_dialog_set_sheet_field_text(sheet_ed, u'', sheet_field_guard)
            try:
                ref_combo.setText(u'')
            except Exception:
                pass
            try:
                code_chk.setState(0)
            except Exception:
                pass
            try:
                code_ed.setText(u'')
            except Exception:
                pass
            try:
                extra_ed.setText(u'')
            except Exception:
                pass
            form_loading[0] = False
            _sync_code_mode()
            return
        b = norm_blocks[block_index]
        _inner_dialog_set_sheet_field_text(sheet_ed, unicode(b.get('sheet') or u'').strip(), sheet_field_guard)
        use_code = bool(b.get('code'))
        ref_val = unicode(b.get('ref') or b.get('c') or u'').strip()
        code_val = unicode(b.get('code') or u'').strip()
        extra_val = unicode(b.get('extra') or b.get('d') or u'').strip()
        try:
            code_chk.setState(1 if use_code else 0)
        except Exception:
            pass
        try:
            _set_combo_items(ref_combo, combo_items, ref_val if not use_code else u'')
        except Exception:
            pass
        try:
            code_ed.setText(code_val if use_code else u'')
        except Exception:
            pass
        try:
            extra_ed.setText(extra_val)
        except Exception:
            pass
        form_loading[0] = False
        _sync_code_mode()

    def _apply_form_to_block(block_index):
        if block_index < 0 or block_index >= len(norm_blocks):
            return False
        b = norm_blocks[block_index]
        _inner_dialog_set_block_sheet(b, _inner_dialog_sheet_text(sheet_ed))
        code_on = False
        try:
            code_on = bool(code_chk.getState())
        except Exception:
            pass
        if code_on:
            try:
                c_val = unicode(code_ed.getText() or u'').strip()
            except Exception:
                c_val = u''
            if c_val == u'':
                return False
            b['code'] = c_val
            b.pop('ref', None)
            b.pop('c', None)
        else:
            try:
                c_val = unicode(ref_combo.getText() or u'').strip()
            except Exception:
                c_val = u''
            if c_val == u'':
                return False
            b['ref'] = c_val
            b.pop('code', None)
        try:
            ex = unicode(extra_ed.getText() or u'').strip()
        except Exception:
            ex = u''
        if ex != u'':
            b['extra'] = ex
        else:
            b.pop('extra', None)
            b.pop('d', None)
        b['v'] = 1
        b['fn'] = _pw_cfg.PLUGIN_FUNCTION_KEY
        return True

    def _sync_sheet_field_to_block():
        if sheet_field_guard[0] or form_loading[0]:
            return
        bi = form_block_index[0]
        if bi < 0 or bi >= len(norm_blocks):
            return
        _inner_dialog_set_block_sheet(norm_blocks[bi], _inner_dialog_sheet_text(sheet_ed))
        _inner_dialog_update_blocks_list_label(blocks_lb, bi, _plugin_block_list_label(norm_blocks[bi]))

    def _switch_block_form(block_index):
        prev = form_block_index[0]
        if prev >= 0 and prev != block_index:
            if _apply_form_to_block(prev):
                _inner_dialog_update_blocks_list_label(blocks_lb, prev, _plugin_block_list_label(norm_blocks[prev]))
        _load_block_to_form(block_index)

    def _add_block_empty():
        prev = form_block_index[0]
        if prev >= 0:
            if _apply_form_to_block(prev):
                _inner_dialog_update_blocks_list_label(blocks_lb, prev, _plugin_block_list_label(norm_blocks[prev]))
        norm_blocks.append({'v': 1, 'fn': _pw_cfg.PLUGIN_FUNCTION_KEY})
        new_idx = len(norm_blocks) - 1
        _refresh_blocks(selected_index=new_idx)
        _load_block_to_form(new_idx)

    def _sync_same_all_ui():
        same_on = False
        try:
            same_on = bool(same_all_chk.getState())
        except Exception:
            pass
        for ctl_name in ('BlocksLB', 'BlocksLbl', 'SheetLbl', 'SheetEd', 'AddBlockBtn', 'DelBlockBtn'):
            try:
                dlg.getControl(ctl_name).Model.Enabled = not same_on
            except Exception:
                pass
        if same_on and len(norm_blocks) > 1:
            while len(norm_blocks) > 1:
                norm_blocks.pop()
            _refresh_blocks(0)
            _load_block_to_form(0)

    class _PluginDlgHandler(unohelper.Base, XActionListener, XItemListener, XTextListener):

        def disposing(self, ev):
            pass

        def _sync_params_to_block(self):
            if form_loading[0]:
                return
            bi = form_block_index[0]
            if bi < 0:
                return
            if _apply_form_to_block(bi):
                _inner_dialog_update_blocks_list_label(blocks_lb, bi, _plugin_block_list_label(norm_blocks[bi]))

        def textChanged(self, ev):
            try:
                src = ev.Source
            except Exception:
                return
            if _wizard_dlg_is_named_control(src, sheet_ed, u'SheetEd'):
                _sync_sheet_field_to_block()
            elif src in (ref_combo, code_ed, extra_ed):
                self._sync_params_to_block()

        def itemStateChanged(self, ev):
            try:
                src = ev.Source
            except Exception:
                return
            if src == blocks_lb:
                if form_loading[0]:
                    return
                _switch_block_form(_block_index_selected())
            elif src == same_all_chk:
                if form_loading[0]:
                    return
                _sync_same_all_ui()
            elif src == code_chk:
                _sync_code_mode()
                self._sync_params_to_block()

        def actionPerformed(self, ev):
            cmd = u''
            try:
                cmd = unicode(ev.ActionCommand)
            except Exception:
                pass
            if cmd == u'AddBlockBtn':
                _add_block_empty()
                return
            if cmd == u'DelBlockBtn':
                bi = _block_index_selected()
                if 0 <= bi < len(norm_blocks):
                    del norm_blocks[bi]
                    form_block_index[0] = -1
                    _refresh_blocks(selected_index=max(0, bi - 1))
                    _switch_block_form(_block_index_selected())
                return
    h = _PluginDlgHandler()
    try:
        blocks_lb.addItemListener(h)
        sheet_ed.addTextListener(h)
        ref_combo.addTextListener(h)
        code_ed.addTextListener(h)
        extra_ed.addTextListener(h)
        code_chk.addItemListener(h)
        same_all_chk.addItemListener(h)
    except Exception:
        pass
    for btn in ('AddBlockBtn', 'DelBlockBtn'):
        try:
            ctl = dlg.getControl(btn)
            ctl.addActionListener(h)
            ctl.setActionCommand(btn)
        except Exception:
            pass
    _refresh_blocks(0)
    _load_block_to_form(0 if len(norm_blocks) > 0 else -1)
    _sync_same_all_ui()
    if dlg.execute() != 1:
        return None
    bi = form_block_index[0]
    if bi < 0:
        bi = _block_index_selected()
    if bi < 0 and len(norm_blocks) > 0:
        bi = 0
    if bi >= 0:
        if not _apply_form_to_block(bi):
            _show_message(u'Укажите ссылку functions_*.py#имя или Python-код.', dialog=dlg, doc=doc)
            return None
    same_on = False
    try:
        same_on = bool(same_all_chk.getState())
    except Exception:
        pass
    out_blocks = []
    if same_on:
        if len(norm_blocks) > 0:
            b = dict(norm_blocks[0])
            b.pop('sheet', None)
            out_blocks.append(b)
        else:
            out_blocks = [{'v': 1, 'fn': _pw_cfg.PLUGIN_FUNCTION_KEY}]
    else:
        out_blocks = [dict(b) for b in norm_blocks]
    for b in out_blocks:
        ref_or_code = b.get('code') or b.get('ref') or b.get('c') or u''
        if unicode(ref_or_code).strip() == u'':
            _show_message(u'В каждом блоке нужна ссылка или Python-код.', dialog=dlg, doc=doc)
            return None
        val = unicode(ref_or_code).strip()
        if not _pp_allows_freeform_c(val):
            _show_message(u'Некорректная ссылка или код в блоке.', dialog=dlg, doc=doc)
            return None
    use_json = True
    try:
        use_json = bool(dlg.getControl('JsonChk').getState())
    except Exception:
        pass
    if use_json:
        try:
            c_out = json.dumps(out_blocks, ensure_ascii=False, separators=(',', ':'))
        except Exception:
            c_out = u''
        return (c_out, u'')
    b0 = out_blocks[0] if len(out_blocks) > 0 else {}
    if b0.get('code'):
        return (unicode(b0.get('code') or u''), unicode(b0.get('extra') or u''))
    return (unicode(b0.get('ref') or u''), unicode(b0.get('extra') or u''))

def _build_wizard_catalog():
    """Каталог параметров визарда: имя, режим ввода, повторяемость."""
    cw = _try_import_collect()
    p_dt_legacy = u'Дата_источника_во_второй__колонке'
    if cw is not None:
        _ensure_collect_pp_maps(cw)
        p_files = cw.P_MERGE_FILES
        p_source_extra = getattr(cw, 'P_MERGE_SOURCE_EXTRA', u'Доп_Параметры_Источника')
        p_pre_shell = getattr(cw, 'P_MERGE_PRE_SHELL', u'Предварительный_скрипт')
        p_mode = cw.P_MERGE_MODE
        p_sheets = cw.P_MERGE_SHEETS
        p_columns = cw.P_MERGE_COLUMNS
        p_start_row = cw.P_MERGE_START_ROW
        p_start_col = cw.P_MERGE_START_COL
        p_row_count = cw.P_MERGE_ROW_COUNT
        p_col_count = cw.P_MERGE_COL_COUNT
        p_header = cw.P_MERGE_HEADER_ROW
        p_path = cw.P_MERGE_PATH_DISPLAY
        p_dt = cw.P_MERGE_DATETIME_DISPLAY
        p_dt_legacy = getattr(cw, 'P_MERGE_DATETIME_DISPLAY_LEGACY', u'Дата_источника_во_второй__колонке')
        p_transfer = getattr(cw, 'P_MERGE_DATA_TRANSFER', u'Способ_переноса')
        p_xml_convert = getattr(cw, 'P_MERGE_XML_CONVERT_TO_NUMBERS', u'MERGE_XML_CONVERT_TO_NUMBERS')
        p_xml_dt_formats = getattr(cw, 'P_MERGE_XML_DATETIME_FORMATS', u'MERGE_XML_DATETIME_FORMATS')
        p_src_subfolders = getattr(cw, 'P_MERGE_SOURCE_VIEW_SUBFOLDERS', u'MERGE_SOURCE_VIEW_SUBFOLDERS')
        p_src_exclude = getattr(cw, 'P_MERGE_SOURCE_EXCLUDE_MASK', u'MERGE_SOURCE_EXCLUDE_MASK')
        p_debug = getattr(cw, 'P_MERGE_DEBUG', u'MERGE_DEBUG')
        p_debug_console = getattr(cw, 'P_MERGE_DEBUG_CONSOLE_LOG', u'MERGE_DEBUG_CONSOLE_LOG_TO_WORKSHEET')
        p_create_log = getattr(cw, 'P_MERGE_CREATE_LOG_SHEET', u'MERGE_CREATE_LOG_SHEET')
        p_do_empty = getattr(cw, 'P_MERGE_DO_EMPTY_SHEETS', u'MERGE_DO_EMPTY_SHEETS')
        p_undelete = cw.P_MERGE_SHEETS_UNDELETE
        p_force_delete = getattr(cw, 'P_MERGE_SHEETS_FORCE_DELETE', u'Листы_удалить')
        p_skip_rows = cw.P_MERGE_SKIP_SOURCE_ROWS
        p_autofilter = getattr(cw, 'P_MERGE_RESULT_AUTOFILTER', u'Автофильтр_результата')
        p_freeze = getattr(cw, 'P_MERGE_FREEZE_HEADER', u'Закрепить_заголовок')
        p_progress = getattr(cw, 'P_MERGE_PROGRESS_UI', u'Отображение_прогресса')
        p_pp_range = cw.P_MERGE_POSTPROCESS_RANGE
        p_pp_row = cw.P_MERGE_POSTPROCESS_ROW
        p_pp_xml = getattr(cw, 'P_MERGE_POSTPROCESS_XML', u'Постобработка_xml')
        p_final = getattr(cw, 'P_MERGE_FINAL_PROCESSING', u'Финальная_обработка')
        p_vlookup = getattr(cw, 'P_MERGE_VLOOKUP', u'ВПР')
        p_merge_sheets = getattr(cw, 'P_MERGE_SHEETS_INTO_ONE', u'объединить_листы_в_один')
        p_split_sheets = getattr(cw, 'P_SPLIT_SHEETS', u'разделить_листы')
        p_cell = cw.P_MERGE_CELL_TO_COLUMN
        p_var_map = getattr(cw, 'P_MERGE_ADD_TO_VARIABLES_MAP', u'Добавить_в_карту_переменных')
        p_manual_var = getattr(cw, 'P_MERGE_MANUAL_VARIABLE_INPUT', u'Ручной_ввод_в_карту_переменных')
        p_delete_top = getattr(cw, 'P_MERGE_DELETE_TOP_ROWS', u'удаление_верхних_строк')
        p_copy_auto_trim = getattr(cw, 'P_MERGE_COPY_AUTO_TRIM', u'Автообрезка_листов')
        p_paste_formats = getattr(cw, 'P_MERGE_PASTE_FORMATS', u'MERGE_PASTE_FORMATS')
        try:
            pp_range_choices = sorted(list(cw.MERGE_RESULT_POSTPROCESS_RANGE_MAP.keys()))
        except Exception:
            pp_range_choices = sorted(_pw_cfg._FALLBACK_PP_RANGE_CHOICES)
        if len(pp_range_choices) == 0:
            pp_range_choices = sorted(_pw_cfg._FALLBACK_PP_RANGE_CHOICES)
        try:
            pp_row_choices = sorted(list(cw.MERGE_RESULT_POSTPROCESS_ROW_MAP.keys()))
        except Exception:
            pp_row_choices = sorted(_pw_cfg._FALLBACK_PP_ROW_CHOICES)
        if len(pp_row_choices) == 0:
            pp_row_choices = sorted(_pw_cfg._FALLBACK_PP_ROW_CHOICES)
        try:
            pp_xml_choices = sorted(list(cw.MERGE_RESULT_POSTPROCESS_XML_MAP.keys()))
        except Exception:
            pp_xml_choices = []
        if len(pp_xml_choices) == 0:
            pp_xml_choices = sorted(_pw_cfg._FALLBACK_PP_XML_CHOICES)
        try:
            final_choices = _final_wizard_choices(cw)
        except Exception:
            final_choices = sorted(_pw_cfg._FALLBACK_FINAL_CHOICES)
        if len(final_choices) == 0:
            final_choices = sorted(_pw_cfg._FALLBACK_FINAL_CHOICES)
        file_range, file_row = _scan_functions_pp_choices()
        file_final = _scan_functions_final_choices()
        pp_range_choices = _pp_catalog_choices_with_plugin(pp_range_choices)
        pp_row_choices = _pp_catalog_choices_with_plugin(pp_row_choices)
        final_choices = _pp_catalog_choices_with_plugin(final_choices)
        pp_range_rest = _merge_pp_rest_hints(_pw_cfg._FALLBACK_PP_RANGE_REST_HINTS, getattr(cw, 'MERGE_POSTPROCESS_RANGE_REST_HINTS', None))
        pp_row_rest = _merge_pp_rest_hints(_pw_cfg._FALLBACK_PP_ROW_REST_HINTS, getattr(cw, 'MERGE_POSTPROCESS_ROW_REST_HINTS', None))
        pp_xml_rest = _merge_pp_rest_hints(_pw_cfg._FALLBACK_PP_XML_REST_HINTS, getattr(cw, 'MERGE_POSTPROCESS_XML_REST_HINTS', None))
        final_rest = _merge_pp_rest_hints(_pw_cfg._FALLBACK_FINAL_REST_HINTS, getattr(cw, 'MERGE_FINAL_PROCESSING_REST_HINTS', None))
        advanced = list(cw.MERGE_ADVANCED_PARAM_NAMES)
        advanced_defaults = cw.MERGE_ADVANCED_DEFAULTS
    else:
        p_files = u'Файлы-Источники'
        p_source_extra = u'Доп_Параметры_Источника'
