def _cell_string(cell):
    if cell is None:
        return u''
    s = cell.String
    if s is None:
        return u''
    return unicode(s).strip()

def _param_match(name, key):
    return unicode(name).strip().lower() == unicode(key).strip().lower()

def _param_sheet_name_is_disabled(name):
    cw = _try_import_collect()
    if cw is not None and hasattr(cw, 'param_sheet_name_is_disabled'):
        return cw.param_sheet_name_is_disabled(name)
    return unicode(name or u'').strip().startswith(u'__')

def _param_canonical_sheet_name(name):
    cw = _try_import_collect()
    if cw is not None and hasattr(cw, 'param_canonical_sheet_name'):
        return unicode(cw.param_canonical_sheet_name(name))
    s = unicode(name or u'').strip()
    if _param_sheet_name_is_disabled(s):
        return s[2:]
    return s

def _param_sheet_name_for_save(canonical_name, disabled=False):
    cw = _try_import_collect()
    nm = unicode(canonical_name or u'').strip()
    force_delete_top_case = nm.casefold() == u'удаление_верхних_строк'.casefold()
    if force_delete_top_case:
        nm = u'Удаление_верхних_строк'
    if cw is not None and hasattr(cw, 'param_sheet_name_for_save'):
        out = unicode(cw.param_sheet_name_for_save(canonical_name, disabled))
    else:
        out = nm
        if nm.casefold() != u'удаление_верхних_строк'.casefold():
            if disabled:
                if _param_sheet_name_is_disabled(nm):
                    out = nm
                else:
                    out = u'__' + nm
            elif _param_sheet_name_is_disabled(nm):
                out = nm[2:]
    if force_delete_top_case:
        if disabled:
            out_u = unicode(out or u'').strip()
            if out_u.startswith(u'__'):
                return out_u[:2] + u'Удаление_верхних_строк'
            return u'__' + u'Удаление_верхних_строк'
        return u'Удаление_верхних_строк'
    return out

def _sheet_name_matches_param(sheet_name, param_name):
    if unicode(sheet_name or u'').strip() == u'':
        return False
    if _param_match(sheet_name, param_name):
        return True
    return _param_match(_param_canonical_sheet_name(sheet_name), param_name)

def _param_row_matches_name(rname, canonical_name):
    if unicode(rname or u'').strip() == u'':
        return True
    return _sheet_name_matches_param(rname, canonical_name)

def _write_param_row_sheet_name(sheet, row, canonical_name, disabled, catalog=None):
    if sheet is None or row is None or int(row) < 0:
        return
    row = int(row)
    _param_sheet_begin_write(sheet)
    try:
        with _pw_timed(u'write_row_sheet_name A=%r disabled=%s' % (canonical_name, disabled)):
            with _pw_timed(u'cell A String'):
                sheet.getCellByPosition(0, row).String = _param_sheet_name_for_save(canonical_name, disabled)
            with _pw_timed(u'apply_row_disabled_style'):
                _param_apply_row_disabled_style(sheet, row, disabled, catalog=catalog)
    finally:
        _param_sheet_end_write(sheet)

def _param_is_value_column_header(text):
    return unicode(text or u'').strip().lower().startswith(u'значение')

def _param_sheet_header_value_max_col(sheet, max_scan=40, fallback=1):
    """Правый индекс столбца (B=1) по подряд идущим «Значение N» в строке 0."""
    if sheet is None:
        return int(fallback)
    last = 0
    col = 1
    while col < max_scan:
        hdr = _cell_string(sheet.getCellByPosition(col, 0))
        if _param_is_value_column_header(hdr):
            last = col
        elif last > 0:
            break
        col = col + 1
    if last <= 0:
        return int(fallback)
    return last

def _vlookup_row_is_json_only(sheet, row):
    """True, если ВПР записан JSON в C (B/D–F пусты) — не раздувать шапку до 5 колонок."""
    try:
        b = _cell_string(sheet.getCellByPosition(1, int(row)))
        c = _cell_string(sheet.getCellByPosition(2, int(row)))
        d = _cell_string(sheet.getCellByPosition(3, int(row)))
    except Exception:
        return False
    if c == u'':
        return False
    cs = c.lstrip()
    if not (cs.startswith(u'[') or cs.startswith(u'{')):
        return False
    return b == u'' and d == u''

def _param_row_max_col(sheet, row, catalog=None):
    row = int(row)
    name = _cell_string(sheet.getCellByPosition(0, row))
    max_col = _param_sheet_header_value_max_col(sheet)
    if catalog is not None:
        spec = _find_catalog_spec(catalog, name)
        if spec is not None and spec.get('mode') == 'vlookup':
            if _vlookup_row_is_json_only(sheet, row):
                max_col = max(max_col, 2)
            else:
                max_col = max(max_col, 5)
        if spec is not None and spec.get('mode') == 'files':
            row_last = _param_sheet_row_last_col(sheet, row, max_cols=40)
            if row_last > max_col:
                max_col = row_last
    return max_col

def _param_row_disabled_style_max_col(sheet, row, catalog=None):
    """Столбцы A + «Значение N» для заливки отключённой строки (без лишних пустых)."""
    row = int(row)
    name = _cell_string(sheet.getCellByPosition(0, row))
    max_col = _param_sheet_header_value_max_col(sheet)
    if catalog is not None:
        spec = _find_catalog_spec(catalog, name)
        if spec is not None and spec.get('mode') == 'vlookup':
            if _vlookup_row_is_json_only(sheet, row):
                max_col = max(max_col, 2)
            else:
                max_col = max(max_col, 5)
    return max_col

def _param_reset_cell_text_color(cell):
    if cell is None:
        return
    try:
        cell.CharAutoColor = True
    except Exception:
        pass
    try:
        cell.CharColor2 = 0
    except Exception:
        pass
    try:
        cell.CharColor = 0
    except Exception:
        pass

def _param_set_cell_disabled_fill(cell):
    if cell is None:
        return
    cell.CellBackColor = _pw_cfg._PARAM_FILL_DISABLED
    cell.IsCellBackgroundTransparent = False
    _param_reset_cell_text_color(cell)

def _param_clear_cell_background(cell):
    if cell is None:
        return
    try:
        cell.IsCellBackgroundTransparent = True
    except Exception:
        pass

def _param_apply_row_disabled_style(sheet, row, disabled, catalog=None, bulk=False):
    """Тёмно-серая заливка всей строки параметра при отключении (__ в колонке A)."""
    if sheet is None or row is None or int(row) < 0:
        return
    row = int(row)
    detail = not bulk
    with _pw_timed_if(u'apply_row_disabled_style row=%d disabled=%s' % (row, disabled), detail):
        with _pw_timed_if(u'read name col A', detail):
            name = _cell_string(sheet.getCellByPosition(0, row))
        with _pw_timed_if(u'row_disabled_style_max_col', detail):
            max_col = _param_row_disabled_style_max_col(sheet, row, catalog)
        comment_row = -1
        if not disabled:
            with _pw_timed_if(u'scan comment_row 0..last_row', detail):
                try:
                    last_row = _sheet_last_used_row(sheet, row)
                    row_idx = 0
                    while row_idx <= last_row:
                        if _param_match(_cell_string(sheet.getCellByPosition(0, row_idx)), _pw_cfg.P_MERGE_COMMENT):
                            comment_row = row_idx
                        row_idx = row_idx + 1
                except Exception:
                    pass
        with _pw_timed_if(u'style cells 0..%d' % max_col, detail):
            col = 0
            while col <= max_col:
                cell = sheet.getCellByPosition(col, row)
                if disabled:
                    _param_set_cell_disabled_fill(cell)
                else:
                    if row == 0 and _param_match(name, u'Параметр'):
                        _param_style_header_cell(cell)
                    elif col == 0 and name != u'':
                        _param_style_name_cell(cell)
                        _param_write_hint_annotation(cell, _param_sheet_hint(name))
                    elif comment_row >= 0 and row == comment_row and (col >= 1):
                        _param_style_value_cell(cell, wrap_top=True)
                        _param_clear_cell_background(cell)
                    else:
                        _param_style_value_cell(cell, wrap_top=False)
                        if col >= 1:
                            _param_clear_cell_background(cell)
                    _param_reset_cell_text_color(cell)
                col = col + 1

def _param_apply_disabled_rows_styles(sheet, catalog=None):
    """Подсветить все отключённые строки параметров на листе."""
    if sheet is None:
        return
    with _pw_timed(u'apply_disabled_rows_styles (весь лист)'):
        with _pw_timed(u'last_used_row'):
            last_row = _sheet_last_used_row(sheet, _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS - 1)
        row_idx = 1
        styled = 0
        while row_idx <= last_row:
            name = _cell_string(sheet.getCellByPosition(0, row_idx))
            if name != u'' and (not _param_match(name, u'Параметр')):
                _param_apply_row_disabled_style(sheet, row_idx, _param_sheet_name_is_disabled(name), catalog, bulk=True)
                styled += 1
            row_idx = row_idx + 1
        if _pw_cfg.PARAM_WIZARD_TIMING:
            _pw_time_log(u'  styled rows: %d / %d' % (styled, last_row))

def _find_param_sheet(doc):
    """Лист параметров: активный, единственный или ошибка при нескольких."""
    sheet, _err = _resolve_param_sheet_for_ui(doc, allow_create=False)
    return sheet

def _list_param_sheet_names_for_wizard(doc):
    """Имена листов параметров в книге (отсортированы)."""
    if doc is None:
        return []
    cw = _try_import_collect()
    if cw is not None:
        try:
            names = cw.list_param_sheet_names(doc)
            if len(names) > 0:
                return [unicode(n) for n in names]
        except Exception:
            pass
    out = []
    try:
        sheets = doc.Sheets
        i = 0
        while i < sheets.Count:
            sh = sheets.getByIndex(i)
            if _wp_is_param_sheet_name(sh.Name):
                out.append(unicode(sh.Name))
            i = i + 1
    except Exception:
        pass
    out.sort()
    return out

def _get_sheet_by_name(doc, name):
    if doc is None or name is None or unicode(name).strip() == u'':
        return None
    cw = _try_import_collect()
    if cw is not None:
        try:
            return cw.get_sheet(doc, unicode(name))
        except Exception:
            pass
    try:
        return doc.Sheets.getByName(unicode(name))
    except Exception:
        return None

def _resolve_wizard_param_sheet(doc):
    """
    Лист параметров для визарда: активный лист параметров или первый по счёту.
    Возвращает (sheet, names, default_name).
    """
    names = _list_param_sheet_names_for_wizard(doc)
    if len(names) == 0:
        return (None, [], u'')
    active = u''
    cw = _try_import_collect()
    if cw is not None:
        try:
            active = unicode(cw.get_active_param_sheet_name(doc) or u'')
        except Exception:
            pass
    pick = active if active in names else names[0]
    return (_get_sheet_by_name(doc, pick), names, pick)

def _resolve_param_sheet_for_ui(doc, allow_create=False):
    """
    Выбор листа параметров для визарда.

    Один лист — без выбора; несколько — активный лист параметров или первый.
    Возвращает (sheet, error_text).
    """
    if doc is None:
        return (None, u'Не открыта книга Calc.')
    cw = _try_import_collect()
    if cw is not None:
        try:
            names = cw.list_param_sheet_names(doc)
            if len(names) == 0:
                if not allow_create:
                    return (None, None)
            elif len(names) == 1:
                return (cw.get_sheet(doc, names[0]), None)
            else:
                _sh, _names, pick = _resolve_wizard_param_sheet(doc)
                if _sh is not None:
                    return (_sh, None)
        except Exception:
            pass
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            active = ctrl.getActiveSheet()
            if active is not None and _wp_is_param_sheet_name(active.Name):
                return (active, None)
    except Exception:
        pass
    try:
        sheets = doc.Sheets
        found = []
        i = 0
        while i < sheets.Count:
            sh = sheets.getByIndex(i)
            if _wp_is_param_sheet_name(sh.Name):
                found.append(sh)
            i = i + 1
        if len(found) == 1:
            return (found[0], None)
        if len(found) > 1:
            found.sort(key=lambda sh: unicode(sh.Name))
            return (found[0], None)
    except Exception:
        pass
    if allow_create:
        return (None, None)
    return (None, u'Лист «%s» не найден.' % _pw_cfg.MERGE_PARAM_SHEET_NAME)

def _default_wizard_vlookup_source_path():
    """Путь к демо-источнику для шаблона первого создания листа параметров."""
    here = os.path.dirname(os.path.abspath(__file__))
    root = os.path.dirname(here)
    return os.path.join(root, u'test', u'collect_workbooks', u'sources', u'vlookup', u'vlookup_data_low_old.xlsx')

def _default_wizard_json(*blocks):
    """Компактный JSON-массив блоков для колонки C шаблона."""
    import json
    return json.dumps(list(blocks), ensure_ascii=False, separators=(',', ':'))

