def _wp_config_base():
    if sys.platform == 'win32':
        base = os.environ.get('APPDATA', os.path.expanduser('~'))
    else:
        base = os.environ.get('XDG_CONFIG_HOME', os.path.join(os.path.expanduser('~'), '.config'))
    return os.path.join(base, 'libre-macros')

def _wp_presets_dir():
    path = os.path.join(_wp_config_base(), _pw_cfg._WP_PRESETS_SUBDIR)
    try:
        os.makedirs(path, exist_ok=True)
    except TypeError:
        if not os.path.isdir(path):
            try:
                os.makedirs(path)
            except OSError:
                pass
    except OSError:
        pass
    return path

def _wp_presets_path():
    return os.path.join(_wp_presets_dir(), _pw_cfg._WP_PRESETS_FILE)

def _wp_legacy_presets_path():
    return os.path.join(_wp_config_base(), _pw_cfg._WP_PRESETS_FILE)

def _wp_resolve_read_path():
    new_path = _wp_presets_path()
    legacy = _wp_legacy_presets_path()
    if os.path.isfile(new_path) and os.path.isfile(legacy):
        try:
            if os.path.getmtime(legacy) > os.path.getmtime(new_path):
                with open(legacy, 'rb') as f:
                    data = f.read()
                with open(new_path, 'wb') as f:
                    f.write(data)
            try:
                os.remove(legacy)
            except OSError:
                pass
        except Exception:
            pass
        return new_path
    if os.path.isfile(new_path):
        return new_path
    if os.path.isfile(legacy):
        try:
            _wp_presets_dir()
            with open(legacy, 'rb') as f:
                data = f.read()
            with open(new_path, 'wb') as f:
                f.write(data)
            try:
                os.remove(legacy)
            except OSError:
                pass
        except Exception:
            pass
    return new_path

def _wp_resolve_write_path():
    new_path = _wp_presets_path()
    legacy = _wp_legacy_presets_path()
    if os.path.isfile(legacy):
        try:
            os.remove(legacy)
        except OSError:
            pass
    return new_path

def _wp_is_param_sheet_name(name):
    """Лист параметров: текущий префикс + legacy Параметры_Объединения / collect_params."""
    try:
        from libre_macros_global_settings_lib import is_param_sheet_name as _gs_is_param

        return bool(_gs_is_param(name, _pw_cfg.MERGE_PARAM_SHEET_NAME))
    except Exception:
        pass
    s = unicode(name or u'').strip()
    if s == u'':
        return False
    for pref in (unicode(_pw_cfg.MERGE_PARAM_SHEET_NAME or u''), u'collect_params', u'Параметры_Объединения'):
        if pref and (s == pref or s.startswith(pref + u'_') or s.startswith(pref)):
            return True
    return False

def _wp_param_sheet_prefix():
    """Актуальный префикс листа параметров (глобальная настройка / cfg)."""
    try:
        p = unicode(_pw_cfg.MERGE_PARAM_SHEET_NAME or u'').strip()
        if p != u'':
            return p
    except Exception:
        pass
    try:
        gs_lib = _wp_import_global_settings_lib()
        if gs_lib is not None:
            return unicode(
                gs_lib.get('DEFAULT_PARAM_SHEET_PREFIX') or u'collect_params'
            )
    except Exception:
        pass
    return u'collect_params'

def _wp_new_param_sheet_label():
    try:
        return unicode(getattr(_pw_cfg, '_WP_NEW_PARAM_SHEET_LABEL', None) or u'＋ Новый лист…')
    except Exception:
        return u'＋ Новый лист…'

def _wp_is_new_param_sheet_label(name):
    t = unicode(name or u'').strip()
    if t == u'':
        return False
    lab = _wp_new_param_sheet_label()
    if t == lab:
        return True
    low = t.casefold()
    return low in (
        lab.casefold(),
        u'новый лист',
        u'новый лист…',
        u'＋ новый лист…',
        u'+ новый лист…',
        u'new sheet',
    )

def _wp_param_sheet_combo_items(sheet_names):
    """Пункт «Новый лист» сверху + существующие листы параметров."""
    names = []
    seen = set()
    for n in sheet_names or []:
        s = unicode(n or u'').strip()
        if s == u'' or _wp_is_new_param_sheet_label(s):
            continue
        k = s.casefold()
        if k in seen:
            continue
        seen.add(k)
        names.append(s)
    return [_wp_new_param_sheet_label()] + names

def _wp_ensure_param_sheet_name_has_prefix(name):
    """Если имя без префикса параметров — добавить префикс_."""
    raw = unicode(name or u'').strip()
    if raw == u'':
        return u''
    if _wp_is_param_sheet_name(raw):
        return raw
    pref = _wp_param_sheet_prefix()
    if pref == u'':
        return raw
    return u'%s_%s' % (pref, raw)

def _wp_suggest_new_param_sheet_name(doc):
    pref = _wp_param_sheet_prefix()
    if pref == u'':
        pref = u'collect_params'
    if doc is None:
        return pref
    if _get_sheet_by_name(doc, pref) is None:
        return pref
    i = 2
    while i < 1000:
        cand = u'%s_%d' % (pref, i)
        if _get_sheet_by_name(doc, cand) is None:
            return cand
        i = i + 1
    return u'%s_new' % pref

def _wp_ask_new_param_sheet_name(parent_dialog, doc, default_name=None):
    """
    Запрос имени нового листа параметров.
    OK → имя (с префиксом при необходимости); Отмена → None.
    """
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    except Exception as err:
        _wp_notify(
            u'Не удалось открыть ввод имени листа: %s' % err,
            doc=doc,
            dialog=parent_dialog,
        )
        return None
    dw, dh, m = (420, 140, 10)
    dm.PositionX = 120
    dm.PositionY = 100
    dm.Width = dw
    dm.Height = dh
    try:
        dm.Title = unicode(
            getattr(_pw_cfg, '_WP_NEW_PARAM_SHEET_TITLE', None) or u'Новый лист параметров'
        )
    except Exception:
        dm.Title = u'Новый лист параметров'
    try:
        dm.Sizeable = True
    except Exception:
        pass
    y = m
    prompt = unicode(
        getattr(_pw_cfg, '_WP_NEW_PARAM_SHEET_PROMPT', None)
        or u'Имя нового листа параметров:'
    )
    _wizard_dlg_add_fixed(dm, u'PromptLbl', prompt, m, y, dw - m * 2, 28, multiline=True)
    y += 32
    _wizard_dlg_add_edit(dm, u'NameEd', m, y, dw - m * 2, 18)
    y += 28
    btn_w = 100
    ok_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    ok_btn.Name = u'OkBtn'
    ok_btn.Label = u'OK'
    try:
        ok_btn.PushButtonType = 1
    except Exception:
        pass
    ok_btn.PositionX = dw - m - btn_w * 2 - 8
    ok_btn.PositionY = y
    ok_btn.Width = btn_w
    ok_btn.Height = 22
    ok_btn.DefaultButton = True
    dm.insertByName(u'OkBtn', ok_btn)
    cancel_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    cancel_btn.Name = u'CancelBtn'
    cancel_btn.Label = u'Отмена'
    try:
        cancel_btn.PushButtonType = 2
    except Exception:
        pass
    cancel_btn.PositionX = dw - m - btn_w
    cancel_btn.PositionY = y
    cancel_btn.Width = btn_w
    cancel_btn.Height = 22
    dm.insertByName(u'CancelBtn', cancel_btn)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    if not _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    ):
        return None
    name_ed = dlg.getControl(u'NameEd')
    init = unicode(default_name or u'').strip() or _wp_suggest_new_param_sheet_name(doc)
    try:
        name_ed.setText(init)
    except Exception:
        pass
    try:
        result = dlg.execute()
    except Exception:
        result = 0
    raw = u''
    if int(result) == 1:
        try:
            raw = unicode(name_ed.getText() or u'').strip()
        except Exception:
            raw = u''
    try:
        dlg.dispose()
    except Exception:
        pass
    if int(result) != 1:
        return None
    if raw == u'' or _wp_is_new_param_sheet_label(raw):
        _wp_notify(u'Укажите имя листа.', doc=doc, dialog=parent_dialog)
        return None
    return _wp_ensure_param_sheet_name_has_prefix(raw)

def _wp_create_param_sheet_interactive(parent_dialog, doc, default_name=None):
    """Запросить имя → создать лист. (sheet, error_or_None). Отмена → (None, None)."""
    name = _wp_ask_new_param_sheet_name(parent_dialog, doc, default_name=default_name)
    if name is None:
        return (None, None)
    return _wp_ensure_param_sheet(doc, name)

def _wp_preset_prefix_token():
    try:
        return unicode(_pw_cfg._WP_PRESET_SHEET_PREFIX_TOKEN or u'[prefix]')
    except Exception:
        return u'[prefix]'

def _wp_encode_param_sheet_name(sheet_name, prefix=None):
    """Абсолютное имя листа → шаблон с [prefix]."""
    name = unicode(sheet_name or u'')
    pref = unicode(prefix if prefix is not None else _wp_param_sheet_prefix())
    token = _wp_preset_prefix_token()
    if pref != u'' and pref in name:
        return name.replace(pref, token)
    return name

def _wp_decode_param_sheet_name(sheet_tmpl, prefix=None):
    """Шаблон с [prefix] → абсолютное имя для текущей книги."""
    tmpl = unicode(sheet_tmpl or u'')
    pref = unicode(prefix if prefix is not None else _wp_param_sheet_prefix())
    token = _wp_preset_prefix_token()
    if token in tmpl:
        return tmpl.replace(token, pref)
    return tmpl

def _wp_normalize_preset_rows(rows):
    out_rows = []
    i = 0
    while i < len(rows or []):
        r = rows[i]
        if isinstance(r, dict):
            out_rows.append(
                {
                    'name': unicode(r.get('name', u'')),
                    'values': [unicode(v) for v in r.get('values') or []],
                }
            )
        i = i + 1
    return out_rows

def _wp_preset_entry_protected(obj):
    """True/False из пресета или None, если флаг не задан (не менять защиту)."""
    if obj is None or not isinstance(obj, dict):
        return None
    if 'protected' in obj:
        return bool(obj.get('protected'))
    if 'protect' in obj:
        return bool(obj.get('protect'))
    return None

def _wp_normalize_preset_sheet_entry(obj, default_sheet=None):
    if obj is None or not isinstance(obj, dict):
        return None
    rows = obj.get('rows')
    if rows is None:
        rows = obj.get('parameters')
    out_rows = _wp_normalize_preset_rows(rows)
    if len(out_rows) == 0:
        return None
    sheet = unicode(obj.get('sheet') or obj.get('sheet_name') or u'').strip()
    if sheet == u'':
        sheet = unicode(default_sheet or _wp_preset_prefix_token())
    out = {'sheet': sheet, 'rows': out_rows}
    prot = _wp_preset_entry_protected(obj)
    if prot is not None:
        out['protected'] = prot
    return out

def _wp_normalize_preset(obj):
    """
    Пресет: legacy {name, rows} или multi {name, comment?, sheets:[{sheet, rows},…]}.
    Внутри всегда есть rows (первый лист) для совместимости UI.
    """
    if obj is None or not isinstance(obj, dict):
        return None
    name = unicode(obj.get('name', u'')).strip()
    sheets_raw = obj.get('sheets')
    out_sheets = []
    if isinstance(sheets_raw, list) and len(sheets_raw) > 0:
        i = 0
        while i < len(sheets_raw):
            entry = _wp_normalize_preset_sheet_entry(sheets_raw[i])
            if entry is not None:
                out_sheets.append(entry)
            i = i + 1
    if len(out_sheets) == 0:
        rows = obj.get('rows')
        if rows is None:
            rows = obj.get('parameters')
        out_rows = _wp_normalize_preset_rows(rows)
        if name == u'' or len(out_rows) == 0:
            return None
        comment = unicode(obj.get('comment') or u'').strip()
        if comment == u'':
            comment = _wp_extract_comment_from_rows(out_rows)
        out = {'name': name, 'rows': out_rows}
        if comment != u'':
            out['comment'] = comment
        prot = _wp_preset_entry_protected(obj)
        if prot is not None:
            out['protected'] = prot
        return out
    if name == u'':
        return None
    comment = unicode(obj.get('comment') or u'').strip()
    if comment == u'':
        comment = _wp_extract_comment_from_rows(out_sheets[0].get('rows') or [])
    out = {
        'name': name,
        'rows': out_sheets[0]['rows'],
        'sheets': out_sheets,
    }
    if comment != u'':
        out['comment'] = comment
    return out

def _wp_preset_sheet_entries(preset):
    """Список {sheet, rows[, protected]}; для legacy без sheets — один элемент с sheet=None (текущий лист)."""
    if preset is None:
        return []
    sheets = preset.get('sheets')
    if isinstance(sheets, list) and len(sheets) > 0:
        return list(sheets)
    rows = preset.get('rows') or []
    if len(rows) == 0:
        return []
    entry = {'sheet': None, 'rows': rows}
    prot = _wp_preset_entry_protected(preset)
    if prot is not None:
        entry['protected'] = prot
    return [entry]

def _wp_preset_is_multi(preset):
    sheets = (preset or {}).get('sheets')
    return isinstance(sheets, list) and len(sheets) > 1

def _wp_load_presets_list():
    path = _wp_resolve_read_path()
    if not os.path.isfile(path):
        return []
    try:
        with open(path, 'rb') as f:
            raw = f.read()
        text = raw.decode('utf-8')
        data = json.loads(text)
    except Exception as err:
        print(u'param_wizard presets: read %s: %s' % (path, err))
        return []
    presets = []
    if isinstance(data, list):
        i = 0
        while i < len(data):
            p = _wp_normalize_preset(data[i])
            if p is not None:
                presets.append(p)
            i = i + 1
    elif isinstance(data, dict):
        items = data.get('presets')
        if isinstance(items, list):
            i = 0
            while i < len(items):
                p = _wp_normalize_preset(items[i])
                if p is not None:
                    presets.append(p)
                i = i + 1
        else:
            p = _wp_normalize_preset(data)
            if p is not None:
                presets.append(p)
    return presets

def _wp_save_presets_list(presets):
    path = _wp_resolve_write_path()
    payload = {'version': _pw_cfg._WP_PRESETS_JSON_VER, 'presets': presets or []}
    text = json.dumps(payload, ensure_ascii=False, indent=2)
    try:
        _wp_presets_dir()
        with open(path, 'wb') as f:
            f.write(text.encode('utf-8'))
        legacy = _wp_legacy_presets_path()
        if legacy != path and os.path.isfile(legacy):
            try:
                os.remove(legacy)
            except OSError:
                pass
        if not os.path.isfile(path):
            return u'файл не создан: %s' % path
        try:
            from libre_macros_global_settings_lib import notify_config_changed

            notify_config_changed()
        except Exception:
            pass
        return None
    except Exception as err:
        return unicode(err)

def _wp_preset_names(presets):
    names = []
    i = 0
    while i < len(presets):
        names.append(presets[i]['name'])
        i = i + 1
    return names

def _wp_find_preset_by_name(presets, name):
    key = unicode(name).strip().lower()
    if key == u'':
        return None
    i = 0
    while i < len(presets):
        if unicode(presets[i]['name']).strip().lower() == key:
            return presets[i]
        i = i + 1
    return None

def _wp_upsert_preset(presets, name, rows=None, sheets=None, comment=None, protected=None):
    name = unicode(name).strip()
    if name == u'':
        return (presets, u'Укажите имя пресета.')
    preset = {'name': name}
    if isinstance(sheets, list) and len(sheets) > 0:
        preset['sheets'] = sheets
        preset['rows'] = sheets[0].get('rows') or []
    elif rows is not None:
        preset['rows'] = rows
        if protected is not None:
            preset['protected'] = bool(protected)
    else:
        return (presets, u'Нет данных для пресета.')
    cmt = unicode(comment or u'').strip()
    if cmt == u'':
        cmt = _wp_extract_comment_from_rows(preset.get('rows') or [])
    if cmt != u'':
        preset['comment'] = cmt
    out = []
    replaced = False
    i = 0
    while i < len(presets):
        if unicode(presets[i]['name']).strip().lower() == name.lower():
            if not replaced:
                out.append(preset)
                replaced = True
        else:
            out.append(presets[i])
        i = i + 1
    if not replaced:
        out.append(preset)
    return (out, None)

def _wp_delete_preset(presets, name):
    key = unicode(name).strip().lower()
    if key == u'':
        return (presets, u'Выберите пресет для удаления.')
    out = []
    removed = False
    i = 0
    while i < len(presets):
        if unicode(presets[i]['name']).strip().lower() == key:
            removed = True
        else:
            out.append(presets[i])
        i = i + 1
    if not removed:
        return (presets, u'Пресет не найден.')
    return (out, None)

def _wp_delete_preset_and_save(presets, name):
    new_list, err = _wp_delete_preset(presets, name)
    if err:
        return (None, err)
    presets[:] = new_list
    path = _wp_resolve_write_path()
    err = _wp_save_presets_list(presets)
    if err:
        return (None, err)
    return (path, None)

def _wp_read_row_values(sheet, row, max_col=30):
    vals = []
    col = 1
    last_nonempty = -1
    while col < max_col:
        v = _cell_string(sheet.getCellByPosition(col, row))
        vals.append(v)
        if v != u'':
            last_nonempty = len(vals) - 1
        col = col + 1
    if last_nonempty < 0:
        return []
    return vals[:last_nonempty + 1]

def _is_vlookup_param_col_header(text):
    s = unicode(text or u'').strip().casefold().replace(u' ', u'_')
    i = 0
    while i < len(_pw_cfg._VLOOKUP_COL_HEADERS):
        h = _pw_cfg._VLOOKUP_COL_HEADERS[i]
        if s == unicode(h).strip().casefold().replace(u' ', u'_'):
            return True
        i = i + 1
    return False

def _generic_param_header_values(max_col):
    """Список «Значение 1..N» без принудительного раздувания до 5 колонок."""
    max_col = max(int(max_col or 0), 1)
    vals = []
    c = 1
    while c <= max_col:
        vals.append(u'Значение %d' % c)
        c = c + 1
    return vals

def _sanitize_param_header_values(vals):
    """В строке «Параметр» всегда «Значение N», не метки B–F от ВПР."""
    if not vals:
        return vals
    i = 0
    while i < len(vals):
        if _is_vlookup_param_col_header(vals[i]):
            return _generic_param_header_values(len(vals))
        i = i + 1
    return vals

def _clear_param_header_cell_style(cell):
    """Снять заливку шапки с ячейки (после ложного раздувания JSON-ВПР до D–F)."""
    if cell is None:
        return
    try:
        cell.IsCellBackgroundTransparent = True
    except Exception:
        pass
    try:
        cell.CellBackColor = -1
    except Exception:
        pass

def _restore_param_sheet_header_row(sheet, max_col=None):
    """
    Восстановить строку 0: A=Параметр, B…=Значение 1, 2, …

    Если max_col передан явно — не раздувать до _PARAM_VALUE_COLUMNS (JSON-ВПР: 2).
    Если max_col is None — взять used шапки и не меньше _PARAM_VALUE_COLUMNS.
    """
    if sheet is None:
        return
    explicit = max_col is not None
    if max_col is None:
        max_col = _param_sheet_max_value_col(sheet)
        max_col = max(int(max_col or 0), _pw_cfg._PARAM_VALUE_COLUMNS)
    else:
        max_col = max(int(max_col or 0), 0)
    try:
        cell_a = sheet.getCellByPosition(0, 0)
        if not _param_match(_cell_string(cell_a), u'Параметр'):
            cell_a.String = u'Параметр'
        _param_style_header_cell(cell_a)
    except Exception:
        pass
    col = 1
    while col <= max_col:
        try:
            cell = sheet.getCellByPosition(col, 0)
            cell.String = u'Значение %d' % col
            _param_style_header_cell(cell)
        except Exception:
            pass
        col = col + 1
    # JSON-путь: убрать наследие «Значение 3..5» и заливку справа от max_col.
    if explicit and max_col < _pw_cfg._PARAM_VALUE_COLUMNS:
        col = max_col + 1
        while col <= _pw_cfg._PARAM_VALUE_COLUMNS:
            try:
                cell = sheet.getCellByPosition(col, 0)
                s = _cell_string(cell)
                if s == u'' or s.casefold().startswith(u'значение'):
                    cell.String = u''
                    _clear_param_header_cell_style(cell)
            except Exception:
                pass
            col = col + 1

def _wp_read_param_sheet_rows(sheet):
    """
    Прочитать строки листа параметров до конца used-range.
    Строки с пустым именем в A пропускаются (не обрывают чтение).
    """
    if sheet is None:
        return []
    rows = []
    row = 0
    h0 = _cell_string(sheet.getCellByPosition(0, 0))
    h1 = _cell_string(sheet.getCellByPosition(0, 1))
    if _param_match(h0, u'Параметр'):
        rows.append({'name': u'Параметр', 'values': _sanitize_param_header_values(_wp_read_row_values(sheet, 0))})
        row = 1
    elif _param_match(h1, u'Параметр'):
        rows.append({'name': u'Параметр', 'values': _sanitize_param_header_values(_wp_read_row_values(sheet, 1))})
        row = 2
    end_row = _param_sheet_scan_end_row(sheet)
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if unicode(name or u'').strip() == u'':
            row = row + 1
            continue
        rows.append({'name': name, 'values': _wp_read_row_values(sheet, row)})
        row = row + 1
    return rows

def _param_sheet_scan_end_row(sheet):
    """Нижняя граница сканирования имён параметров (used-range, с потолком MAX_ROWS)."""
    last = _sheet_last_used_row(sheet, 0)
    try:
        last = int(last)
    except (TypeError, ValueError):
        last = 0
    if last < 0:
        last = 0
    cap = int(_pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS) - 1
    if last > cap:
        last = cap
    return last

def _wp_meaningful_rows_count(rows):
    count = 0
    i = 0
    while i < len(rows or []):
        name = unicode(rows[i].get('name', u'')).strip()
        if name != u'' and (not _param_match(name, u'Параметр')):
            count = count + 1
        i = i + 1
    return count

def _wp_clear_param_sheet(sheet, max_row=None, max_col=40):
    if sheet is None:
        return
    if max_row is None:
        max_row = _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS
    try:
        rng = sheet.getCellRangeByPosition(0, 0, int(max_col) - 1, int(max_row) - 1)
        rng.clearContents(7)
    except Exception:
        row = 0
        while row < max_row:
            col = 0
            while col < max_col:
                try:
                    sheet.getCellByPosition(col, row).setString(u'')
                except Exception:
                    pass
                col = col + 1
            row = row + 1

def _wp_write_param_sheet_rows(sheet, rows):
    if sheet is None:
        return False
    _param_sheet_begin_write(sheet)
    try:
        return _wp_write_param_sheet_rows_unlocked(sheet, rows)
    finally:
        _param_sheet_end_write(sheet)

def _wp_write_param_sheet_rows_unlocked(sheet, rows):
    _wp_clear_param_sheet(sheet)
    if rows is None or len(rows) == 0:
        return True
    max_vals = 3
    i = 0
    while i < len(rows):
        vals = rows[i].get('values') or []
        if len(vals) > max_vals:
            max_vals = len(vals)
        i = i + 1
    out_rows = list(rows)
    if len(out_rows) > 0 and _param_match(out_rows[0].get('name', u''), u'Параметр'):
        out_rows[0] = {'name': u'Параметр', 'values': _generic_param_header_values(max_vals)}
    elif len(out_rows) > 0:
        out_rows.insert(0, {'name': u'Параметр', 'values': _generic_param_header_values(max_vals)})
    row_idx = 0
    i = 0
    while i < len(out_rows):
        item = out_rows[i]
        name = item.get('name', u'')
        vals = item.get('values') or []
        sheet.getCellByPosition(0, row_idx).String = unicode(name)
        col = 1
        vi = 0
        while vi < max_vals:
            cell = sheet.getCellByPosition(col, row_idx)
            if vi < len(vals):
                cell.String = unicode(vals[vi])
            else:
                cell.String = u''
            vi = vi + 1
            col = col + 1
        row_idx = row_idx + 1
        i = i + 1
    _restore_param_sheet_header_row(sheet, max_vals)
    return True

def _wp_stamp_rows_macro_version(rows):
    """
    В строках пресета заменить «Версия» на текущую MACRO_VERSION
    (не оставлять устаревшее значение с листа).
    """
    ver = unicode(_wp_macro_version_for_presets() or u'').strip()
    if ver == u'':
        return list(rows or [])
    out = []
    found = False
    i = 0
    while i < len(rows or []):
        r = rows[i]
        name = unicode((r or {}).get('name') or u'')
        if _param_match(name, _pw_cfg.P_MERGE_VERSION):
            out.append({'name': _pw_cfg.P_MERGE_VERSION, 'values': [ver]})
            found = True
        else:
            out.append(r)
        i = i + 1
    if not found and len(out) > 0:
        # После «Параметр» / комментария, иначе в начало данных.
        insert_at = 0
        j = 0
        while j < len(out):
            nm = unicode((out[j] or {}).get('name') or u'')
            if _param_match(nm, u'Параметр') or _param_match(nm, _pw_cfg.P_MERGE_COMMENT):
                insert_at = j + 1
            j = j + 1
        out.insert(insert_at, {'name': _pw_cfg.P_MERGE_VERSION, 'values': [ver]})
    return out

def _wp_build_sheet_entries_from_doc(doc, sheet_names):
    """Прочитать выбранные листы параметров → [{sheet: [prefix]-шаблон, rows}, …]."""
    prefix = _wp_param_sheet_prefix()
    entries = []
    i = 0
    while i < len(sheet_names or []):
        sn = unicode(sheet_names[i] or u'').strip()
        if sn == u'':
            i = i + 1
            continue
        sh = _get_sheet_by_name(doc, sn)
        if sh is None:
            return (None, u'Лист «%s» не найден.' % sn)
        try:
            rows = _wp_stamp_rows_macro_version(_wp_read_param_sheet_rows(sh))
        except Exception as err:
            return (None, u'Не удалось прочитать «%s»: %s' % (sn, err))
        if _wp_meaningful_rows_count(rows) < 1:
            return (
                None,
                u'На листе «%s» нет данных для пресета.\nПрочитано строк: %d.'
                % (sn, len(rows)),
            )
        entry = {
            'sheet': _wp_encode_param_sheet_name(sn, prefix),
            'rows': rows,
            'protected': _param_sheet_is_protected(sh),
        }
        entries.append(entry)
        i = i + 1
    if len(entries) == 0:
        return (None, u'Не выбраны листы параметров.')
    return (entries, None)

def _wp_pick_param_sheets_dialog( parent_dialog, doc, title, labels, hint=None, default_all=True ):
    """
    Субдиалог выбора листов (мультивыбор).
    labels — подписи в списке; возвращает список индексов или None (отмена).
    """
    labels = [unicode(x) for x in (labels or [])]
    if len(labels) == 0:
        return []
    if len(labels) == 1:
        return [0]
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    except Exception as err:
        _wp_notify(u'Не удалось открыть выбор листов: %s' % err, doc=doc, dialog=parent_dialog)
        return None
    dw, dh, m = (420, 320, 10)
    dm.PositionX = 110
    dm.PositionY = 90
    dm.Width = dw
    dm.Height = dh
    dm.Title = unicode(title or u'Листы параметров')
    try:
        dm.Sizeable = True
    except Exception:
        pass
    y = m
    hint_text = unicode(
        hint
        or u'Отметьте листы для включения. По умолчанию выбраны все.'
    )
    _wizard_dlg_add_fixed(dm, u'HintLbl', hint_text, m, y, dw - m * 2, 36, multiline=True)
    y += 40
    list_h = dh - y - m - 36
    if list_h < 80:
        list_h = 80
    _wizard_dlg_add_listbox(dm, u'SheetsLB', m, y, dw - m * 2, list_h, multiselect=True)
    y = dh - m - 24
    btn_w = 100
    ok_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    ok_btn.Name = u'OkBtn'
    ok_btn.Label = u'OK'
    try:
        ok_btn.PushButtonType = 1
    except Exception:
        pass
    ok_btn.PositionX = dw - m - btn_w * 2 - 8
    ok_btn.PositionY = y
    ok_btn.Width = btn_w
    ok_btn.Height = 22
    ok_btn.DefaultButton = True
    dm.insertByName(u'OkBtn', ok_btn)
    cancel_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    cancel_btn.Name = u'CancelBtn'
    cancel_btn.Label = u'Отмена'
    try:
        cancel_btn.PushButtonType = 2
    except Exception:
        pass
    cancel_btn.PositionX = dw - m - btn_w
    cancel_btn.PositionY = y
    cancel_btn.Width = btn_w
    cancel_btn.Height = 22
    dm.insertByName(u'CancelBtn', cancel_btn)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    if not _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    ):
        return None
    lb = dlg.getControl(u'SheetsLB')
    try:
        lb.Model.StringItemList = tuple(labels)
        if default_all:
            i = 0
            while i < len(labels):
                try:
                    lb.selectItemPos(i, True)
                except Exception:
                    pass
                i = i + 1
        else:
            try:
                lb.selectItemPos(0, True)
            except Exception:
                pass
    except Exception:
        pass
    try:
        result = dlg.execute()
    except Exception:
        result = 0
    selected = []
    if int(result) == 1:
        try:
            positions = lb.getSelectedItemsPos()
            if positions is not None:
                for pos in positions:
                    selected.append(int(pos))
        except Exception:
            selected = []
        selected.sort()
    try:
        dlg.dispose()
    except Exception:
        pass
    if int(result) != 1:
        return None
    if len(selected) == 0:
        return None
    return selected

def _wp_save_preset_from_doc(doc, presets, name, sheet, sheet_names=None, parent_dialog=None):
    """
    Сохранить пресет из листа(ов) параметров.
    sheet_names — явный список; иначе субдиалог при нескольких листах / текущий лист.
    """
    name = unicode(name).strip()
    if name == u'':
        return (None, u'Укажите имя пресета (поле «Имя для сохранения»).')
    names = list(sheet_names) if sheet_names is not None else None
    if names is None:
        all_names = _list_param_sheet_names_for_wizard(doc)
        if len(all_names) == 0:
            if sheet is None:
                sheet = _find_param_sheet(doc)
            if sheet is None:
                return (None, u'Лист «%s» не найден.' % _pw_cfg.MERGE_PARAM_SHEET_NAME)
            names = [unicode(sheet.Name)]
        elif len(all_names) == 1:
            names = [all_names[0]]
        else:
            idxs = _wp_pick_param_sheets_dialog(
                parent_dialog,
                doc,
                u'Сохранение пресета — листы',
                all_names,
                hint=u'Выберите листы параметров для мультилистового пресета.\nПо умолчанию — все.',
                default_all=True,
            )
            if idxs is None:
                return (None, None)
            names = [all_names[i] for i in idxs]
    entries, err = _wp_build_sheet_entries_from_doc(doc, names)
    if err:
        return (None, err)
    comment = _wp_extract_comment_from_rows(entries[0].get('rows') or [])
    if len(entries) == 1:
        new_list, uerr = _wp_upsert_preset(
            presets, name, rows=entries[0]['rows'], sheets=entries, comment=comment
        )
    else:
        new_list, uerr = _wp_upsert_preset(
            presets, name, sheets=entries, comment=comment
        )
    if uerr:
        return (None, uerr)
    presets[:] = new_list
    path = _wp_resolve_write_path()
    err = _wp_save_presets_list(presets)
    if err:
        return (None, u'Не удалось сохранить:\n%s' % err)
    if not os.path.isfile(path):
        return (None, u'Файл не создан: %s' % path)
    return (path, None)

def _wp_apply_preset_rows(doc, sheet, rows, catalog, protected=None):
    if sheet is None:
        sheet = _find_param_sheet(doc)
    if sheet is None:
        return u'Лист «%s» не найден.' % _pw_cfg.MERGE_PARAM_SHEET_NAME
    _param_sheet_begin_write(sheet)
    try:
        _wp_write_param_sheet_rows(sheet, rows)
        _restore_param_sheet_header_row(sheet)
        reformat_param_sheet_table(doc, sheet, catalog)
    finally:
        _param_sheet_end_write(sheet)
    if protected is not None:
        if not _param_sheet_set_protected(sheet, bool(protected)):
            return u'Не удалось установить защиту листа «%s».' % unicode(sheet.Name)
    return None

def _wp_ensure_param_sheet(doc, sheet_name):
    """Найти или создать лист параметров по абсолютному имени."""
    name = unicode(sheet_name or u'').strip()
    if name == u'':
        return (None, u'Пустое имя листа')
    sh = _get_sheet_by_name(doc, name)
    if sh is not None:
        return (sh, None)
    return _insert_param_sheet(doc, name)

def _wp_apply_preset_to_doc( doc, preset, catalog, current_sheet=None, selected_indices=None, parent_dialog=None, force_target_sheet=None ):
    """
    Применить пресет к книге.
    Legacy (без sheets) — на current_sheet / force_target_sheet.
    Multi — субдиалог выбора листов (по умолчанию все), создание недостающих.
    force_target_sheet — явный лист (в т.ч. только что созданный «Новый лист»):
      при одном выбранном блоке пресета пишет на него (имя из пресета игнорируется);
      при нескольких блоках — обычные имена из пресета.
    Возвращает (applied_sheet_or_None, error_or_None, applied_names).
    """
    if preset is None:
        return (None, u'Пресет не выбран.', [])
    entries = _wp_preset_sheet_entries(preset)
    if len(entries) == 0:
        return (None, u'В пресете нет данных.', [])
    # Legacy: один блок без явного sheet → текущий / forced лист визарда
    if len(entries) == 1 and entries[0].get('sheet') is None:
        target = force_target_sheet if force_target_sheet is not None else current_sheet
        err = _wp_apply_preset_rows(
            doc,
            target,
            entries[0].get('rows') or [],
            catalog,
            protected=_wp_preset_entry_protected(entries[0]),
        )
        if err:
            return (None, err, [])
        sh = target if target is not None else _find_param_sheet(doc)
        nm = unicode(sh.Name) if sh is not None else u''
        return (sh, None, [nm] if nm else [])
    labels = []
    i = 0
    while i < len(entries):
        tmpl = entries[i].get('sheet')
        if tmpl is None:
            labels.append(unicode(current_sheet.Name) if current_sheet is not None else _wp_param_sheet_prefix())
        else:
            labels.append(_wp_decode_param_sheet_name(tmpl))
        i = i + 1
    idxs = selected_indices
    if idxs is None:
        if len(entries) > 1:
            idxs = _wp_pick_param_sheets_dialog(
                parent_dialog,
                doc,
                u'Применить пресет — листы',
                labels,
                hint=(
                    u'Выберите листы набора для загрузки в книгу.\n'
                    u'По умолчанию — все. «Новый лист» в шапке визарда '
                    u'переназначает цель, если выбран один лист набора.'
                ),
                default_all=True,
            )
            if idxs is None:
                return (None, None, [])
        else:
            idxs = [0]
    if force_target_sheet is not None and len(idxs) > 1:
        return (
            None,
            u'При цели «Новый лист» в шапке визарда отметьте один лист набора пресета.',
            [],
        )
    # Один блок + явная цель (новый / выбранный в combo) → писать туда
    if force_target_sheet is not None and len(idxs) == 1:
        pos = idxs[0]
        if 0 <= pos < len(entries):
            entry = entries[pos]
            err = _wp_apply_preset_rows(
                doc,
                force_target_sheet,
                entry.get('rows') or [],
                catalog,
                protected=_wp_preset_entry_protected(entry),
            )
            if err:
                return (None, err, [])
            nm = unicode(force_target_sheet.Name)
            return (force_target_sheet, None, [nm])
    applied_names = []
    first_sheet = None
    for pos in idxs:
        if pos < 0 or pos >= len(entries):
            continue
        entry = entries[pos]
        tmpl = entry.get('sheet')
        if tmpl is None:
            target_name = (
                unicode(current_sheet.Name)
                if current_sheet is not None
                else _wp_param_sheet_prefix()
            )
        else:
            target_name = _wp_decode_param_sheet_name(tmpl)
        sh, ierr = _wp_ensure_param_sheet(doc, target_name)
        if ierr or sh is None:
            return (first_sheet, ierr or u'Не удалось создать «%s»' % target_name, applied_names)
        err = _wp_apply_preset_rows(
            doc,
            sh,
            entry.get('rows') or [],
            catalog,
            protected=_wp_preset_entry_protected(entry),
        )
        if err:
            return (first_sheet, err, applied_names)
        applied_names.append(target_name)
        if first_sheet is None:
            first_sheet = sh
    if first_sheet is None:
        return (None, u'Не выбраны листы для применения.', [])
    return (first_sheet, None, applied_names)

def _wp_export_sheets_to_file(entries, path, preset_name=None, comment=None):
    """Экспорт: JSON-массив объектов {sheet, rows} (+ name/comment у первого)."""
    payload = []
    i = 0
    while i < len(entries or []):
        e = entries[i]
        item = {
            'sheet': unicode(e.get('sheet') or _wp_preset_prefix_token()),
            'rows': e.get('rows') or [],
        }
        prot = _wp_preset_entry_protected(e)
        if prot is not None:
            item['protected'] = prot
        if i == 0:
            nm = unicode(preset_name or u'').strip()
            if nm != u'':
                item['name'] = nm
            cmt = unicode(comment or u'').strip()
            if cmt == u'':
                cmt = _wp_extract_comment_from_rows(item['rows'])
            if cmt != u'':
                item['comment'] = cmt
        payload.append(item)
        i = i + 1
    text = json.dumps(payload, ensure_ascii=False, indent=2)
    try:
        with open(path, 'wb') as f:
            f.write(text.encode('utf-8'))
        return None
    except Exception as err:
        return unicode(err)

def _wp_export_preset_to_file(preset, path):
    """Старый путь: один пресет → файл (массив листов или одиночный объект)."""
    if preset is None:
        return u'Пресет не выбран.'
    entries = _wp_preset_sheet_entries(preset)
    if len(entries) == 0:
        return u'В пресете нет данных.'
    # Явные sheets / multi → массив; legacy без sheet → одиночный объект
    if _wp_preset_is_multi(preset) or (
        isinstance(preset.get('sheets'), list) and len(preset.get('sheets') or []) > 0
    ):
        fixed = []
        i = 0
        while i < len(entries):
            e = dict(entries[i])
            if e.get('sheet') is None:
                e['sheet'] = _wp_preset_prefix_token()
            fixed.append(e)
            i = i + 1
        return _wp_export_sheets_to_file(
            fixed,
            path,
            preset_name=preset.get('name'),
            comment=preset.get('comment'),
        )
    payload = {'name': preset['name'], 'rows': preset['rows']}
    cmt = unicode(preset.get('comment') or u'').strip()
    if cmt != u'':
        payload['comment'] = cmt
    prot = _wp_preset_entry_protected(preset)
    if prot is None and len(entries) == 1:
        prot = _wp_preset_entry_protected(entries[0])
    if prot is not None:
        payload['protected'] = prot
    text = json.dumps(payload, ensure_ascii=False, indent=2)
    try:
        with open(path, 'wb') as f:
            f.write(text.encode('utf-8'))
        return None
    except Exception as err:
        return unicode(err)

def _wp_import_preset_from_file(path, default_name=None):
    """
    Импорт: массив листов / одиночный объект / {presets:[…]}.
    Имена sheet с [prefix] сохраняются как шаблоны (подстановка — при применении).
    """
    try:
        with open(path, 'rb') as f:
            raw = f.read()
        data = json.loads(raw.decode('utf-8'))
    except Exception as err:
        return (None, unicode(err))
    fallback_name = unicode(default_name or u'').strip()
    if fallback_name == u'':
        try:
            fallback_name = unicode(os.path.splitext(os.path.basename(path))[0] or u'').strip()
        except Exception:
            fallback_name = u'Импорт'
    if isinstance(data, list):
        if len(data) == 0:
            return (None, u'В файле пустой массив.')
        # Массив объектов-листов или массив пресетов
        if isinstance(data[0], dict) and (
            'rows' in data[0] or 'parameters' in data[0] or 'sheets' in data[0]
        ):
            if 'sheets' in data[0] and 'name' in data[0]:
                p = _wp_normalize_preset(data[0])
                if p is None:
                    return (None, u'Некорректный формат файла пресета.')
                return (p, None)
            entries = []
            name = fallback_name
            comment = u''
            i = 0
            while i < len(data):
                item = data[i]
                if not isinstance(item, dict):
                    i = i + 1
                    continue
                if i == 0:
                    nm = unicode(item.get('name') or u'').strip()
                    if nm != u'':
                        name = nm
                    comment = unicode(item.get('comment') or u'').strip()
                entry = _wp_normalize_preset_sheet_entry(item)
                if entry is not None:
                    # Оставить шаблон [prefix]; абсолютные имена — как есть
                    entries.append(entry)
                i = i + 1
            if len(entries) == 0:
                return (None, u'В файле нет листов параметров.')
            if comment == u'':
                comment = _wp_extract_comment_from_rows(entries[0].get('rows') or [])
            payload = {'name': name, 'sheets': entries, 'rows': entries[0]['rows']}
            if comment != u'':
                payload['comment'] = comment
            p = _wp_normalize_preset(payload)
            if p is None:
                return (None, u'Некорректный формат файла пресета.')
            return (p, None)
        return (None, u'Некорректный формат файла пресета.')
    if isinstance(data, dict) and 'presets' in data:
        items = data.get('presets') or []
        if len(items) == 0:
            return (None, u'В файле нет пресетов.')
        p = _wp_normalize_preset(items[0])
    else:
        p = _wp_normalize_preset(data)
    if p is None:
        return (None, u'Некорректный формат файла пресета.')
    return (p, None)

def _wp_dialog_parent():
    try:
        frame = XSCRIPTCONTEXT.getDesktop().getCurrentFrame()
        if frame is not None:
            return frame.getContainerWindow()
    except Exception:
        pass
    return None

def _wp_dialog_picker_parent(dialog=None):
    if dialog is not None:
        try:
            peer = dialog.getPeer()
            if peer is not None:
                return peer
        except Exception:
            pass
    return _wp_dialog_parent()

def _wp_pick_json_file(ctx, save_as=False, suggested_name=u'preset.json', parent=None):
    try:
        sm = ctx.getServiceManager()
        picker = sm.createInstanceWithContext('com.sun.star.ui.dialogs.FilePicker', ctx)
        if save_as:
            try:
                from com.sun.star.ui.dialogs.TemplateDescription import FILESAVE_SIMPLE
                picker.initialize((FILESAVE_SIMPLE,))
            except Exception:
                pass
            picker.setTitle(u'Сохранить пресет')
        else:
            try:
                from com.sun.star.ui.dialogs.TemplateDescription import FILEOPEN_SIMPLE
                picker.initialize((FILEOPEN_SIMPLE,))
            except Exception:
                pass
            picker.setTitle(u'Выбрать файл пресета')
        try:
            picker.appendFilter('JSON', '*.json')
            picker.setCurrentFilter('JSON')
        except Exception:
            pass
        start_dir = _wp_presets_dir()
        if os.path.isdir(start_dir):
            try:
                picker.setDisplayDirectory(uno.systemPathToFileUrl(start_dir))
            except Exception:
                pass
        if save_as and suggested_name:
            try:
                picker.setDefaultName(unicode(suggested_name))
            except Exception:
                pass
        if parent is None:
            parent = _wp_dialog_parent()
        try:
            if parent is not None and hasattr(picker, 'setParent'):
                picker.setParent(parent)
        except Exception:
            pass
        if picker.execute() != 1:
            return None
        urls = picker.getFiles()
        if urls is None or len(urls) == 0:
            return None
        path = os.path.abspath(uno.fileUrlToSystemPath(urls[0]))
        if save_as and (not path.lower().endswith('.json')):
            path = path + '.json'
        return path
    except Exception as err:
        print(u'param_wizard pick_json: %s' % err)
        return None

def _wp_doc_parent_window(doc=None):
    if doc is None:
        try:
            doc = XSCRIPTCONTEXT.getDocument()
        except Exception:
            doc = None
    if doc is not None:
        try:
            return doc.getCurrentController().getFrame().getContainerWindow()
        except Exception:
            pass
    return _wp_dialog_parent()

def _wp_message_box_execute(doc, dialog, box_type, buttons, title, text):
    """MessageBox с перебором родителей (окно документа — первым: работает поверх модального визарда)."""
    toolkit = None
    try:
        toolkit = XSCRIPTCONTEXT.getDesktop().getToolkit()
    except Exception:
        pass
    if toolkit is None:
        try:
            ctx = XSCRIPTCONTEXT.getComponentContext()
            toolkit = ctx.ServiceManager.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        except Exception:
            toolkit = None
    if toolkit is None:
        return None
    parents = []
    parent_doc = _wp_doc_parent_window(doc)
    if parent_doc is not None:
        parents.append(parent_doc)
    parent_desk = _wp_dialog_parent()
    if parent_desk is not None and parent_desk not in parents:
        parents.append(parent_desk)
    if dialog is not None:
        try:
            peer = dialog.getPeer()
            if peer is not None and peer not in parents:
                parents.append(peer)
        except Exception:
            pass
    title_u = unicode(title)
    text_u = unicode(text)
    i = 0
    while i < len(parents):
        try:
            box = toolkit.createMessageBox(parents[i], box_type, buttons, title_u, text_u)
            return box.execute()
        except Exception:
            pass
        i = i + 1
    try:
        box = toolkit.createMessageBox(None, box_type, buttons, title_u, text_u)
        return box.execute()
    except Exception:
        return None

def _wp_suppress_param_action_messages():
    """Глобальный флаг: не показывать короткий тост после сохранения/удаления параметра."""
    gs_lib = _wp_import_global_settings_lib()
    if gs_lib is None:
        return False
    try:
        settings = gs_lib['load_global_settings']()
        return bool(settings.get('suppress_param_action_messages'))
    except Exception:
        return False

def _wp_soft_gray_info_box(message, title=u'Параметры', parent_dialog=None, doc=None):
    """Короткое контрастное сообщение в стиле soft-gray (как «применить_формулу»)."""
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
        text = unicode(message or u'')
        caption = unicode(title or u'Параметры')
        w = 300
        m = 12
        btn_h = 22
        btn_w = 80
        lines = max(1, text.count(u'\n') + 1)
        wrap_extra = max(0, (len(text.replace(u'\n', u'')) // 44) - lines + 1)
        msg_h = max(40, min(180, (lines + wrap_extra) * 15 + 10))
        dm.PositionX = 120
        dm.PositionY = 100
        dm.Width = w
        dm.Height = m + msg_h + 10 + btn_h + m
        dm.Title = caption
        msg = dm.createInstance('com.sun.star.awt.UnoControlFixedTextModel')
        msg.Name = 'SoftGrayMsgLabel'
        msg.Label = text
        msg.PositionX = m
        msg.PositionY = m
        msg.Width = w - 2 * m
        msg.Height = msg_h
        try:
            msg.MultiLine = True
        except Exception:
            pass
        try:
            msg.Align = 0
        except Exception:
            pass
        try:
            msg.Border = 0
        except Exception:
            pass
        dm.insertByName('SoftGrayMsgLabel', msg)
        ok = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
        ok.Name = 'SoftGrayOkBtn'
        ok.Label = u'OK'
        ok.PositionX = (w - btn_w) // 2
        ok.PositionY = m + msg_h + 10
        ok.Width = btn_w
        ok.Height = btn_h
        try:
            ok.DefaultButton = True
        except Exception:
            pass
        try:
            ok.PushButtonType = 1  # OK — закрывает диалог
        except Exception:
            pass
        dm.insertByName('SoftGrayOkBtn', ok)
        _wizard_apply_soft_gray_theme(dm, title_text=caption)
        dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
        dlg.setModel(dm)
        if not _nested_subdialog_create_peer(dlg, toolkit, doc=doc, parent_dialog=parent_dialog):
            dlg.createPeer(toolkit, None)
        _wizard_try_paint_titlebar(dlg)

        class _SoftGrayOkHandler(unohelper.Base, XActionListener):

            def disposing(self, ev):
                pass

            def actionPerformed(self, ev):
                try:
                    dlg.endExecute()
                except Exception:
                    pass
        handler = _SoftGrayOkHandler()
        try:
            ctl = dlg.getControl('SoftGrayOkBtn')
            if ctl is not None:
                ctl.addActionListener(handler)
        except Exception:
            pass
        dlg.execute()
        try:
            dlg.dispose()
        except Exception:
            pass
        return True
    except Exception as err:
        print(u'param_wizard: soft_gray_info_box: %s' % err)
        return False

def _wp_notify(message, doc=None, dialog=None, title=u'Пресеты'):
    text = unicode(message)
    if _wp_soft_gray_info_box(text, title=title, parent_dialog=dialog, doc=doc):
        return
    if _wp_message_box_execute(doc, dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, text) is not None:
        return
    try:
        cw = _try_import_collect()
        if cw is not None:
            if cw.show_message_uno_infobox(doc, text):
                return
            cw.show_message(text, doc)
            return
    except Exception:
        pass
    print(text)

def _wp_notify_param_action(message, doc=None, dialog=None, title=u'Параметры'):
    """Короткий тост после действия с параметром; уважает глобальный флаг отключения."""
    if _wp_suppress_param_action_messages():
        return
    _wp_notify(message, doc=doc, dialog=dialog, title=title)

