def _wp_msg_applied(name, sheet_names=None):
    names = [unicode(x) for x in (sheet_names or []) if unicode(x).strip() != u'']
    if len(names) <= 1:
        target = names[0] if names else _pw_cfg.MERGE_PARAM_SHEET_NAME
        return u'Пресет «%s» применён к листу «%s».' % (unicode(name), target)
    return u'Пресет «%s» применён к листам:\n%s' % (
        unicode(name),
        u'\n'.join(u'  • %s' % n for n in names),
    )

def _wp_rows_first_value(rows, param_name, default=u''):
    i = 0
    while i < len(rows or []):
        name = unicode(rows[i].get('name', u'')).strip()
        if _param_match(name, param_name):
            vals = rows[i].get('values') or []
            if len(vals) > 0:
                v = unicode(vals[0]).strip()
                if v != u'':
                    return v
        i = i + 1
    return default

def _wp_rows_values_nonempty(rows, param_name):
    out = []
    i = 0
    while i < len(rows or []):
        name = unicode(rows[i].get('name', u'')).strip()
        if _param_match(name, param_name):
            vals = rows[i].get('values') or []
            j = 0
            while j < len(vals):
                v = unicode(vals[j]).strip()
                if v != u'':
                    out.append(v)
                j = j + 1
        i = i + 1
    return out

def _wp_count_param_rows(rows, param_name):
    count = 0
    i = 0
    while i < len(rows or []):
        name = unicode(rows[i].get('name', u'')).strip()
        if _param_match(name, param_name):
            vals = rows[i].get('values') or []
            if len(vals) > 0 and unicode(vals[0]).strip() != u'':
                count = count + 1
        i = i + 1
    return count

def _wp_extract_comment_from_rows(rows):
    i = 0
    while i < len(rows or []):
        name = unicode(rows[i].get('name', u'')).strip()
        if _param_match(name, _pw_cfg.P_MERGE_COMMENT):
            parts = []
            vals = rows[i].get('values') or []
            j = 0
            while j < len(vals):
                t = unicode(vals[j]).strip()
                if t != u'':
                    parts.append(t)
                j = j + 1
            return u'\n'.join(parts)
        i = i + 1
    return u''

def _wp_mode_label(mode):
    m = unicode(mode or u'').strip()
    if m == u'':
        return u'—'
    cw = _try_import_collect()
    if cw is not None:
        try:
            return cw._merge_mode_label(m)
        except Exception:
            pass
    return m

def _wp_build_preset_summary(rows):
    mode = _wp_rows_first_value(rows, u'Режим', u'—')
    files = _wp_rows_values_nonempty(rows, u'Файлы-Источники')
    sheets = _wp_rows_first_value(rows, u'Листы', u'')
    cols = _wp_rows_first_value(rows, u'Столбцы', u'')
    start_row = _wp_rows_first_value(rows, u'Начало_Строка', u'')
    header_row = _wp_rows_first_value(rows, u'Строка_Заголовков', u'')
    path_disp = _wp_rows_first_value(rows, u'Источник_в_первой_колонке', u'')
    dt_disp = _wp_rows_first_value(rows, u'Дата_источника_во_второй_колонке', u'')
    if dt_disp == u'':
        dt_disp = _wp_rows_first_value(rows, u'Дата_источника_во_второй__колонке', u'')
    pp_range = _wp_count_param_rows(rows, _pw_cfg.P_MERGE_POSTPROCESS_RANGE)
    pp_row = _wp_count_param_rows(rows, _pw_cfg.P_MERGE_POSTPROCESS_ROW)
    pp_xml = _wp_count_param_rows(rows, _pw_cfg.P_MERGE_POSTPROCESS_XML)
    ctc = _wp_count_param_rows(rows, _pw_cfg.P_MERGE_CELL_TO_COLUMN)
    dtr = _wp_rows_first_value(rows, u'удаление_верхних_строк', u'')
    lines = [u'Режим сбора: %s' % _wp_mode_label(mode)]
    if len(files) == 0:
        lines.append(u'Источники: не заданы (заполните «Файлы-Источники» на листе)')
    else:
        lines.append(u'Файлов/масок в параметрах: %d' % len(files))
        max_show = 5
        fi = 0
        while fi < len(files) and fi < max_show:
            lines.append(u'  • %s' % files[fi])
            fi = fi + 1
        if len(files) > max_show:
            lines.append(u'  … и ещё %d' % (len(files) - max_show))
    if sheets != u'':
        lines.append(u'Листы: %s' % sheets)
    if cols != u'':
        lines.append(u'Столбцы: %s' % cols)
    if start_row != u'':
        lines.append(u'Данные с строки %s; строка заголовков: %s' % (start_row, header_row if header_row != u'' else u'—'))
    if path_disp != u'':
        lines.append(u'Колонка #Путь: %s' % path_disp)
    if dt_disp != u'':
        lines.append(u'Колонка #ДатаВремяФайла: %s' % dt_disp)
    extras = []
    if pp_range > 0:
        extras.append(u'постобработка диапазона (%d шаг.)' % pp_range)
    if pp_row > 0:
        extras.append(u'постобработка строк (%d шаг.)' % pp_row)
    if pp_xml > 0:
        extras.append(u'Постобработка_xml (%d шаг.)' % pp_xml)
    if ctc > 0:
        extras.append(u'«Ячейка_В_Столбец» (%d)' % ctc)
    if dtr != u'':
        extras.append(u'«удаление_верхних_строк»')
    if len(extras) > 0:
        lines.append(u'Дополнительно: ' + u', '.join(extras))
    return u'\n'.join(lines)

def _wp_preset_info_texts(presets, preset_name):
    name = unicode(preset_name or u'').strip()
    preset = _wp_find_preset_by_name(presets, name) if name != u'' else None
    if preset is None:
        if name != u'':
            return (
                u'(новый пресет — комментарий будет взят с первого выбранного листа при сохранении)',
                u'Будет сохранён выбранный набор листов параметров под именем «%s».\n'
                u'При нескольких листах откроется выбор (по умолчанию все).\n'
                u'После сохранения здесь появится описание набора.'
                % name,
            )
        return (
            u'',
            u'Выберите пресет из списка или укажите имя для нового.\n'
            u'«Применить к листу» — подставить параметры пресета на лист(ы).\n'
            u'В списке листов сверху: «＋ Новый лист…» — создать лист и запросить имя при применении.\n'
            u'«Сохранить» — записать лист(ы) параметров в JSON-пресеты.\n'
            u'«Экспорт» — выбрать листы книги и сохранить JSON-массив.',
        )
    entries = _wp_preset_sheet_entries(preset)
    comment = unicode(preset.get('comment') or u'').strip()
    if comment == u'':
        comment = _wp_extract_comment_from_rows((entries[0].get('rows') if entries else None) or [])
    if comment == u'':
        comment = u'(комментарий не задан в параметре «Комментарий»)'
    if _wp_preset_is_multi(preset):
        lines = [u'Мультилистовый набор: %d лист(ов) параметров' % len(entries)]
        i = 0
        while i < len(entries):
            tmpl = entries[i].get('sheet')
            label = (
                _wp_decode_param_sheet_name(tmpl)
                if tmpl is not None
                else u'(текущий лист)'
            )
            lines.append(u'— %s' % label)
            if i == 0:
                lines.append(_wp_build_preset_summary(entries[i].get('rows') or []))
            i = i + 1
        return (comment, u'\n'.join(lines))
    rows = preset.get('rows') or []
    return (comment, _wp_build_preset_summary(rows))

def _wp_example_preset_name(idx, kind_label, mode_label=None):
    if mode_label:
        return u'Я%02d — %s · %s' % (int(idx), kind_label, mode_label)
    return u'Я%02d — %s · UNO' % (int(idx), kind_label)

def _wp_example_vlookup_json_tier(tier):
    """JSON ВПР для vlookup_{tier}.xlsx (Заказы + Справочник_цен, заголовок в строке 1)."""
    tiers = {u'1to1_low': ([u'Код_позиции'], False), u'1to1_middle': ([u'Регион', u'Код_товара'], False), u'1to1_high': ([u'Регион', u'Код_товара', u'Склад'], False), u'1toN_low': ([u'Код_позиции'], True), u'1toN_middle': ([u'Регион', u'Код_товара'], True), u'1toN_high': ([u'Регион', u'Код_товара', u'Склад'], True)}
    keys, fill_dup = tiers.get(unicode(tier), ([u'Код_позиции'], False))
    return _default_wizard_json({u'v': 1, u'fn': u'впр', u'left': {u'sheet': u'Заказы', u'start_row': 2, u'start_col': 1, u'header_row': 1}, u'right': {u'sheet': u'Справочник_цен', u'start_row': 2, u'start_col': 1, u'header_row': 1}, u'keys_same': True, u'keys_left': list(keys), u'keys_right': list(keys), u'extract_columns': [u'B', u'C', u'D'], u'highlight_color': u'#FFF2CC', u'fill_duplicates': bool(fill_dup), u'not_found_fill': u'#Н/Д', u'multi_match_one_cell': False, u'trim_keys': False, u'column_suffix': True})

