def _wp_example_src_preset(*parts):
    """Путь к sources: repo/test/… если есть, иначе bundled."""
    try:
        from libre_macros_bundle_paths import repo_dev_sources_dir
        dev = repo_dev_sources_dir(__file__)
        if dev:
            out = dev
            i = 0
            while i < len(parts):
                out = os.path.join(out, unicode(parts[i]))
                i = i + 1
            return os.path.normpath(out)
    except Exception:
        pass
    return _wp_example_src(*parts)

def _wp_example_sources_root():
    try:
        from libre_macros_bundle_paths import resolve_test_sources_dir
        return resolve_test_sources_dir(__file__)
    except Exception:
        home = os.path.expanduser('~')
        return os.path.join(home, 'Documents', 'alter_office_macros', 'test', 'collect_workbooks', 'sources')

def _wp_example_src(*parts):
    try:
        from libre_macros_bundle_paths import resolve_example_source_path
        return resolve_example_source_path(__file__, *parts)
    except Exception:
        return os.path.join(_wp_example_sources_root(), *parts)

