def _wp_parse_ctc_legacy(text):
    """Разбор legacy «A:1 -> Филиал» для пресетов."""
    s = unicode(text or u'').strip()
    if s == u'' or u'->' not in s:
        return None
    left, right = s.split(u'->', 1)
    left = left.strip()
    right = right.strip()
    if left == u'' or right == u'' or u':' not in left:
        return None
    col_s, row_s = left.split(u':', 1)
    col_s = col_s.strip()
    row_s = row_s.strip()
    if col_s == u'' or row_s == u'':
        return None
    try:
        row_n = int(row_s)
    except Exception:
        return None
    if row_n < 1:
        return None
    out = {u'col': col_s, u'row': row_n, u'column': right}
    return out

def _wp_ctc_json(col, row, column, sheet=None):
    block = {u'v': 1, u'fn': u'ячейка_в_столбец', u'col': unicode(col), u'row': int(row), u'column': unicode(column)}
    if sheet:
        block[u'sheet'] = unicode(sheet)
    return _default_wizard_json(block)

def _wp_ctc_rows(*specs):
    rows = []
    i = 0
    while i < len(specs):
        spec = specs[i]
        parsed = None
        if isinstance(spec, dict):
            parsed = spec
        elif isinstance(spec, (list, tuple)):
            j = 0
            while j < len(spec):
                parsed = _wp_parse_ctc_legacy(spec[j])
                if parsed is not None:
                    break
                j = j + 1
        else:
            parsed = _wp_parse_ctc_legacy(spec)
        if parsed is not None:
            rows.append(_wp_row(_pw_cfg.P_MERGE_CELL_TO_COLUMN, _pw_cfg._PARAM_B_SEE_COLUMN_C, _wp_ctc_json(parsed[u'col'], parsed[u'row'], parsed[u'column'], parsed.get(u'sheet'))))
        i = i + 1
    return rows


def _wp_var_map_json(file_mask, sheet, cell, name):
    block = {
        u'v': 1,
        u'fn': u'добавить_в_карту_переменных',
        u'file': unicode(file_mask or u'*'),
        u'sheet': unicode(sheet or u'*'),
        u'cell': unicode(cell or u'A1'),
        u'name': unicode(name or u''),
    }
    return _default_wizard_json(block)


def _wp_var_map_rows(*specs):
    rows = []
    i = 0
    while i < len(specs):
        spec = specs[i]
        i = i + 1
        if not isinstance(spec, dict):
            continue
        name = unicode(spec.get(u'name') or u'').strip()
        cell = unicode(spec.get(u'cell') or u'').strip()
        if name == u'' or cell == u'':
            continue
        rows.append(
            _wp_row(
                _pw_cfg.P_MERGE_ADD_TO_VARIABLES_MAP,
                _pw_cfg._PARAM_B_SEE_COLUMN_C,
                _wp_var_map_json(spec.get(u'file') or u'*', spec.get(u'sheet') or u'*', cell, name),
            )
        )
    return rows

def _wp_j(fn, **fields):
    block = {u'v': 1, u'fn': fn}
    for key in fields:
        block[key] = fields[key]
    return _default_wizard_json(block)

def _wp_body_collect_header(sources, sheets, columns=None):
    srcs = tuple((_wp_example_src(s) for s in sources))
    sheet_vals = sheets if isinstance(sheets, (list, tuple)) else (sheets,)
    body = [_wp_row(u'Отображение_прогресса', u'Диалог'), _wp_row(u'Файлы-Источники', *srcs), _wp_row(u'MERGE_DEBUG', u'Да'), _wp_row(u'Листы', *sheet_vals)]
    if columns:
        body.append(_wp_row(u'Столбцы', columns))
    return body

def _wp_body_finish_collect(body, xml_mode, merge_mode, pp_steps, path=u'Коротко', datetime=u'Не_выводить', ctc=None, var_map=None):
    body.extend(_wp_block_range_rows())
    transfer = u'xml_excel_ods' if xml_mode else _pw_cfg._TRANSFER_WIZARD_DEFAULT
    body.append(_wp_row(u'Режим', merge_mode, transfer))
    if merge_mode in (u'На один лист', u'На разные листы'):
        body.append(_wp_row(u'Источник_в_первой_колонке', path))
        body.append(_wp_row(u'Дата_источника_во_второй_колонке', datetime))
    if ctc:
        body.extend(_wp_ctc_rows(*ctc))
    if var_map:
        body.extend(_wp_var_map_rows(*var_map))
    if xml_mode:
        body.append(_wp_row(u'MERGE_XML_CONVERT_TO_NUMBERS', u'Да'))
    if xml_mode:
        body.extend(_wp_pp_xml_rows(*pp_steps))
    else:
        body.extend(_wp_pp_range_rows(*pp_steps))
    return body


def _wp_final_rows(*specs):
    """Строки «Финальная_обработка» для пресетов."""
    rows = []
    pname = u'Финальная_обработка'
    i = 0
    while i < len(specs):
        spec = specs[i]
        if isinstance(spec, tuple):
            fn = spec[0]
            rest = spec[1] if len(spec) > 1 else u''
        else:
            fn = spec
            rest = u''
        rows.append(_wp_row(pname, fn, rest))
        i = i + 1
    return rows


