def _wp_scenario_preset(display_name, comment, body_rows, value_cols=5):
    rows = [_wp_row(u'Параметр', *[u'Значение %d' % (c + 1) for c in range(value_cols)]), _wp_row(_pw_cfg.P_MERGE_COMMENT, comment), _wp_row(_pw_cfg.P_MERGE_VERSION, _wp_macro_version_for_presets())]
    rows.extend(body_rows)
    i = 0
    while i < 3:
        rows.append(_wp_row(u''))
        i = i + 1
    return {'name': display_name, 'rows': rows, 'comment': comment}


def _wp_scenario_preset_multi(display_name, comment, sheet_entries, value_cols=5):
    """Мульти-пресет: несколько листов параметров ([prefix], [prefix]_2, …)."""
    sheets_out = []
    i = 0
    while i < len(sheet_entries or []):
        entry = sheet_entries[i]
        sheet_name = unicode((entry or {}).get(u'sheet') or _wp_preset_prefix_token())
        body = (entry or {}).get(u'rows') or []
        rows = [
            _wp_row(u'Параметр', *[u'Значение %d' % (c + 1) for c in range(value_cols)]),
            _wp_row(_pw_cfg.P_MERGE_COMMENT, comment if i == 0 else (comment + u' · лист %d' % (i + 1))),
            _wp_row(_pw_cfg.P_MERGE_VERSION, _wp_macro_version_for_presets()),
        ]
        rows.extend(body)
        j = 0
        while j < 3:
            rows.append(_wp_row(u''))
            j = j + 1
        item = {u'sheet': sheet_name, u'rows': rows}
        if u'protected' in (entry or {}):
            item[u'protected'] = bool(entry.get(u'protected'))
        sheets_out.append(item)
        i = i + 1
    if not sheets_out:
        return _wp_scenario_preset(display_name, comment, [])
    return {
        u'name': display_name,
        u'comment': comment,
        u'sheets': sheets_out,
        u'rows': sheets_out[0].get(u'rows') or [],
    }

