def _wp_example_pivot_json(as_values=True, source_sheet=u'Merge', sheet_name=u'Сводная', row_fields=None, data_fields=None, header_row=None, data_start=None, data_end=None):
    if row_fields is None:
        row_fields = [u'Отдел']
    if data_fields is None:
        data_fields = [{u'field': u'Сумма_руб', u'function': u'SUM'}]
    block = {u'v': 1, u'fn': u'сводная_таблица', u'source_sheet': source_sheet, u'sheet_name': sheet_name, u'as_values': bool(as_values), u'row_fields': list(row_fields), u'column_fields': [], u'filter_fields': [], u'data_fields': list(data_fields)}
    if header_row is not None:
        block[u'header_row'] = unicode(header_row)
    if data_start is not None:
        block[u'data_start'] = unicode(data_start)
    if data_end is not None:
        block[u'data_end'] = unicode(data_end)
    return _default_wizard_json(block)

def _wp_example_body_vlookup(xml_mode=True, variant=None):
    """Копирование листов + ВПР."""
    v = variant if isinstance(variant, dict) else {}
    see_c = _pw_cfg._PARAM_B_SEE_COLUMN_C
    src_parts = v.get(u'src') or (u'vlookup', u'vlookup_data_low_old.xlsx')
    src = _wp_example_src(*src_parts)
    legacy = bool(v.get(u'legacy'))
    j_skip = _default_wizard_json({u'v': 1, u'fn': u'пропуск_строк_источника', u'columns': [u'1'], u'mode': u'columns'})
    j_del_top = _default_wizard_json({u'v': 1, u'fn': u'удаление_верхних_строк', u'n': 2, u'sheet': u'1_Заказы'})
    j_rename = _default_wizard_json({u'v': 1, u'fn': u'переименовать_лист', u'new_name': u'Заказы', u'sheet': u'1_Заказы'})
    tier = v.get(u'tier')
    if tier:
        j_vl = _wp_example_vlookup_json_tier(tier)
    else:
        j_vl = _wp_example_vlookup_json()
    j_grid = _default_wizard_json({u'v': 1, u'fn': u'тонкая_сетка'})
    j_aw = _default_wizard_json({u'v': 1, u'fn': u'авто_ширина', u'sheets': [u'Заказы']})
    j_header = _default_wizard_json({u'v': 1, u'fn': u'заголовок_плюс_высота', u'height_mm': 15.0, u'h_align': u'center', u'v_align': u'center', u'sheet': u'Заказы'})
    j_zebra = _default_wizard_json({u'v': 1, u'fn': u'зебра_диапазон', u'sheet': u'Заказы'})
    transfer = u'xml_excel_ods' if xml_mode else _pw_cfg._TRANSFER_WIZARD_DEFAULT
    start_rows = (u'4', u'2') if legacy else (u'2', u'2')
    header_rows = (u'3', u'1') if legacy else (u'1', u'1')
    body = [_wp_row(u'Отображение_прогресса', u'Диалог'), _wp_row(u'Файлы-Источники', src), _wp_row(u'MERGE_DEBUG', u'Да'), _wp_row(u'Листы', u'Заказы', u'Справочник_цен'), _wp_row(u'Начало_Строка', start_rows[0], start_rows[1]), _wp_row(u'Начало_Столбец', u'1', u'1'), _wp_row(u'Число_Строк', u'', u''), _wp_row(u'Число_Столбцов', u'', u''), _wp_row(u'Строка_Заголовков', header_rows[0], header_rows[1]), _wp_row(u'Режим', u'Копирование листов', transfer), _wp_row(u'Пропуск_строк_источника', see_c, j_skip)]
    if legacy:
        body.append(_wp_row(u'Удаление_верхних_строк', see_c, j_del_top))
    if xml_mode:
        body.append(_wp_row(u'MERGE_XML_CONVERT_TO_NUMBERS', u'Да'))
        pp_tail = []
        if legacy:
            pp_tail.append((u'переименовать_лист', j_rename))
            body.extend(_wp_pp_xml_rows(*pp_tail))
            body.append(_wp_row(u'ВПР', u'', j_vl))
            pp_tail = [(u'тонкая_сетка', j_grid), (u'авто_ширина', j_aw)]
        else:
            pp_tail = [(u'тонкая_сетка', j_grid), (u'авто_ширина', j_aw)]
            body.extend(_wp_pp_xml_rows(*pp_tail))
            body.append(_wp_row(u'ВПР', u'', j_vl))
            pp_tail = []
        extra_pp = v.get(u'extra_pp') or ()
        i = 0
        while i < len(extra_pp):
            fn = extra_pp[i]
            if fn == u'заголовок_плюс_высота':
                pp_tail.append((fn, j_header))
            elif fn == u'зебра_диапазон':
                pp_tail.append((fn, j_zebra))
            else:
                pp_tail.append((fn, _default_wizard_json({u'v': 1, u'fn': fn})))
            i = i + 1
        if len(pp_tail) > 0:
            body.extend(_wp_pp_xml_rows(*pp_tail))
    else:
        pp_tail = []
        if legacy:
            pp_tail.append((u'переименовать_лист', j_rename))
        pp_tail.extend([(u'тонкая_сетка', j_grid), (u'авто_ширина', j_aw)])
        extra_pp = v.get(u'extra_pp') or ()
        i = 0
        while i < len(extra_pp):
            fn = extra_pp[i]
            if fn == u'заголовок_плюс_высота':
                pp_tail.append((fn, j_header))
            elif fn == u'зебра_диапазон':
                pp_tail.append((fn, j_zebra))
            else:
                pp_tail.append((fn, _default_wizard_json({u'v': 1, u'fn': fn})))
            i = i + 1
        if legacy:
            body.extend(_wp_pp_range_rows(*pp_tail[:1]))
            body.append(_wp_row(u'ВПР', u'', j_vl))
            if len(pp_tail) > 1:
                body.extend(_wp_pp_range_rows(*pp_tail[1:]))
        else:
            body.extend(_wp_pp_range_rows(*pp_tail))
            body.append(_wp_row(u'ВПР', u'', j_vl))
            extra_only = []
            i = 0
            while i < len(extra_pp):
                fn = extra_pp[i]
                if fn == u'заголовок_плюс_высота':
                    extra_only.append((fn, j_header))
                elif fn == u'зебра_диапазон':
                    extra_only.append((fn, j_zebra))
                i = i + 1
            if len(extra_only) > 0:
                body.extend(_wp_pp_range_rows(*extra_only))
    return body

def _wp_example_body_pivot(xml_mode=True, variant=None):
    """На один лист + сводная."""
    v = variant if isinstance(variant, dict) else {}
    sources = v.get(u'sources') or (u'source_01.xlsx',)
    if v.get(u'sources_preset'):
        srcs = tuple((_wp_example_src_preset(s) for s in sources))
    else:
        srcs = tuple((_wp_example_src(s) for s in sources))
    sheets = v.get(u'sheets') or u'Отчет*'
    sheet_vals = sheets if isinstance(sheets, (list, tuple)) else (sheets,)
    merge_mode = v.get(u'merge_mode') or u'На один лист'
    pivot_kw = {}
    if u'pivot_header_row' in v:
        pivot_kw[u'header_row'] = v[u'pivot_header_row']
    if u'pivot_data_start' in v:
        pivot_kw[u'data_start'] = v[u'pivot_data_start']
    if u'pivot_data_end' in v:
        pivot_kw[u'data_end'] = v[u'pivot_data_end']
    j_pivot = _wp_example_pivot_json(as_values=bool(xml_mode), source_sheet=v.get(u'pivot_source_sheet') or u'Merge', sheet_name=v.get(u'pivot_sheet') or u'Сводная', row_fields=v.get(u'row_fields'), data_fields=v.get(u'data_fields'), **pivot_kw)
    j_grid = _default_wizard_json({u'v': 1, u'fn': u'тонкая_сетка'})
    j_aw = _default_wizard_json({u'v': 1, u'fn': u'авто_ширина'})
    pp_tail = v.get(u'pp_tail')
    pp_tail_disabled = v.get(u'pp_tail_disabled')
    transfer = u'xml_excel_ods' if xml_mode else _pw_cfg._TRANSFER_WIZARD_DEFAULT
    body = [_wp_row(u'Отображение_прогресса', u'Диалог'), _wp_row(u'Файлы-Источники', *srcs), _wp_row(u'MERGE_DEBUG', u'Да'), _wp_row(u'Листы', *sheet_vals)]
    body.extend(_wp_block_range_rows())
    body.extend([_wp_row(u'Режим', merge_mode, transfer), _wp_row(u'Источник_в_первой_колонке', u'Коротко'), _wp_row(u'Дата_источника_во_второй_колонке', u'Не_выводить')])
    if not v.get(u'skip_ctc'):
        ctc_spec = v.get(u'ctc') or u'A:1 -> Филиал'
        body.extend(_wp_ctc_rows(ctc_spec))
    if v.get(u'var_map'):
        body.extend(_wp_var_map_rows(*v.get(u'var_map')))
    if xml_mode:
        body.append(_wp_row(u'MERGE_XML_CONVERT_TO_NUMBERS', u'Да'))
        body.extend(_wp_pp_xml_rows((u'сводная_таблица', j_pivot)))
        if pp_tail:
            body.extend(_wp_pp_xml_rows(*pp_tail))
        elif pp_tail_disabled:
            body.extend(_wp_pp_xml_rows_disabled(*pp_tail_disabled))
        else:
            body.extend(_wp_pp_xml_rows((u'тонкая_сетка', j_grid), (u'авто_ширина', j_aw)))
    else:
        body.extend(_wp_pp_range_rows((u'сводная_таблица', j_pivot)))
        if pp_tail:
            body.extend(_wp_pp_range_rows(*pp_tail))
        elif pp_tail_disabled:
            body.extend(_wp_pp_range_rows_disabled(*pp_tail_disabled))
        else:
            body.extend(_wp_pp_range_rows((u'тонкая_сетка', j_grid), (u'авто_ширина', j_aw)))
    return body

def _wp_example_body_copy(xml_mode=True, variant=None):
    """Копирование листов целиком."""
    v = variant if isinstance(variant, dict) else {}
    sources = v.get(u'sources') or (u'source_01.xlsx', u'source_02.xlsx')
    srcs = tuple((_wp_example_src(s) for s in sources))
    sheets = v.get(u'sheets') or u'Все'
    sheet_vals = sheets if isinstance(sheets, (list, tuple)) else (sheets,)
    pp_fns = v.get(u'pp') or (u'тонкая_сетка', u'авто_ширина', u'автофильтр')
    transfer = u'xml_excel_ods' if xml_mode else _pw_cfg._TRANSFER_WIZARD_DEFAULT
    body = [_wp_row(u'Отображение_прогресса', u'Диалог'), _wp_row(u'Файлы-Источники', *srcs), _wp_row(u'MERGE_DEBUG', u'Да'), _wp_row(u'Листы', *sheet_vals)]
    body.extend(_wp_block_range_rows())
    body.append(_wp_row(u'Режим', u'Копирование листов', transfer))
    pp_specs = []
    i = 0
    while i < len(pp_fns):
        fn = pp_fns[i]
        j = _default_wizard_json({u'v': 1, u'fn': fn})
        pp_specs.append((fn, j))
        i = i + 1
    if xml_mode:
        body.append(_wp_row(u'MERGE_XML_CONVERT_TO_NUMBERS', u'Да'))
        body.extend(_wp_pp_xml_rows(*pp_specs))
    else:
        body.extend(_wp_pp_range_rows(*pp_specs))
    return body

def _wp_default_example_presets():
    """
    Примеры при пустом файле пресетов: только UNO-сценарии (Я01…ЯN).
    xml_excel_ods-клоны больше не создаются.
    """
    out = []
    scenarios = _build_wp_scenarios()
    i = 0
    while i < len(scenarios):
        item = scenarios[i]
        title = item[0]
        comment = item[1]
        builder = item[2]
        is_multi = bool(item[3]) if len(item) > 3 else False
        name = _wp_example_preset_name(i + 1, title)
        built = builder(False)
        if is_multi:
            out.append(_wp_scenario_preset_multi(name, comment + u' UNO.', built))
        else:
            out.append(
                _wp_scenario_preset(
                    name,
                    comment + u' UNO: Буфер_по_заголовкам / По_API и Постобработка_Диапазон.',
                    built,
                )
            )
        i = i + 1
    return out

def _wp_presets_file_missing_or_empty():
    path = _wp_presets_path()
    if not os.path.isfile(path):
        legacy = _wp_legacy_presets_path()
        if not os.path.isfile(legacy):
            return True
        path = legacy
    try:
        items = _wp_load_presets_list()
        return len(items) == 0
    except Exception:
        return True

def _wp_create_default_presets_file():
    default_list = _wp_default_example_presets()
    err = _wp_save_presets_list(default_list)
    if err:
        return (None, err)
    return (default_list, None)

def _wp_ensure_presets_file(presets):
    """
    Если JSON нет или пуст — создать примеры Я01…ЯN (только UNO-сценарии).
    Возвращает True, если файл был создан заново.
    """
    if not _wp_presets_file_missing_or_empty():
        presets[:] = _wp_load_presets_list()
        return False
    new_list, err = _wp_create_default_presets_file()
    if err:
        print(u'param_wizard: не удалось создать пресеты: %s' % err)
        return False
    presets[:] = new_list
    return True

def _wp_delete_presets_file():
    err = None
    for path in (_wp_presets_path(), _wp_legacy_presets_path()):
        if os.path.isfile(path):
            try:
                os.remove(path)
            except OSError as exc:
                err = unicode(exc)
    return err

def _wp_confirm_clear_all_presets(doc=None, dialog=None):
    text = u'Удалить файл со всеми пресетами?\n\nПри следующем открытии вкладки «Пресеты» будут созданы примеры Я01…Я16 (только UNO-сценарии, без xml_excel_ods).'
    title = u'Очистить все пресеты'
    answer = _wp_message_box_execute(doc, dialog, QUERYBOX, MSG_BUTTONS.BUTTONS_YES_NO, title, text)
    if answer is not None:
        return answer == YES
    try:
        cw = _try_import_collect()
        if cw is not None:
            return cw.ask_yes_no(text, doc)
    except Exception:
        pass
    return False

def _show_choose_preset_on_create_dialog(doc, presets):
    """
    Диалог выбора пресета при первом создании листа параметров.
    В списке всегда первый пункт — встроенный шаблон; далее сохранённые пресеты.
    Возвращает:
      ("default", None) — шаблон по умолчанию;
      ("preset", name) — загрузить сохранённый пресет;
      None — отмена (тоже шаблон по умолчанию).
    """
    saved_names = _wp_preset_names(presets or [])
    list_names = [_pw_cfg._WP_CREATE_DEFAULT_PRESET_NAME] + list(saved_names)
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    except Exception as err:
        _show_message(u'Не удалось открыть выбор пресета: %s\nБудет шаблон по умолчанию.' % err, doc=doc)
        return (u'default', None)
    dw, dh, m = (420, 300, 10)
    dm.PositionX = 100
    dm.PositionY = 80
    dm.Width = dw
    dm.Height = dh
    dm.Title = u'Выбор пресета параметров'
    try:
        dm.Sizeable = True
    except Exception:
        pass
    y = m
    _wizard_dlg_add_fixed(dm, u'HintLbl', u'Выберите набор для нового листа параметров (collect_params…).\nПервый пункт — встроенный шаблон UNO+ВПР; ниже — сохранённые пресеты.', m, y, dw - m * 2, 36, multiline=True)
    y += 40
    _wizard_dlg_add_fixed(dm, u'ListLbl', u'Пресеты:', m, y, dw - m * 2, 14)
    y += 16
    list_h = 110
    _wizard_dlg_add_listbox(dm, u'PresetLB', m, y, dw - m * 2, list_h, multiselect=False)
    y += list_h + 8
    _wizard_dlg_add_fixed(dm, u'CommentLbl', u'Комментарий:', m, y, dw - m * 2, 14)
    y += 16
    comment_h = 48
    _wizard_dlg_add_edit(dm, u'CommentEd', m, y, dw - m * 2, comment_h, multiline=True, readonly=True)
    y += comment_h + 10
    btn_w, btn_h = (120, 22)
    load_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    load_btn.Name = u'LoadBtn'
    load_btn.Label = u'Загрузить'
    try:
        load_btn.PushButtonType = 1
    except Exception:
        pass
    load_btn.PositionX = m
    load_btn.PositionY = y
    load_btn.Width = btn_w
    load_btn.Height = btn_h
    load_btn.DefaultButton = True
    dm.insertByName(u'LoadBtn', load_btn)
    cancel_btn = dm.createInstance('com.sun.star.awt.UnoControlButtonModel')
    cancel_btn.Name = u'CancelBtn'
    cancel_btn.Label = u'Отмена'
    try:
        cancel_btn.PushButtonType = 2
    except Exception:
        pass
    cancel_btn.PositionX = dw - m - 80
    cancel_btn.PositionY = y
    cancel_btn.Width = 80
    cancel_btn.Height = btn_h
    dm.insertByName(u'CancelBtn', cancel_btn)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    if not _nested_subdialog_create_peer(dlg, toolkit, doc, None):
        return (u'default', None)
    lb = dlg.getControl(u'PresetLB')
    comment_ed = dlg.getControl(u'CommentEd')
    try:
        lb.Model.StringItemList = tuple(list_names)
        sel = 1 if len(saved_names) > 0 else 0
        lb.selectItemPos(sel, True)
    except Exception:
        pass
    chosen = {u'kind': None, u'name': None}

    def _selected_list_name():
        try:
            pos = lb.getSelectedItemPos()
            if pos is not None and int(pos) >= 0 and (int(pos) < len(list_names)):
                return list_names[int(pos)]
        except Exception:
            pass
        try:
            t = lb.getSelectedItem()
            if t is not None and unicode(t).strip() != u'':
                return unicode(t).strip()
        except Exception:
            pass
        return u''

    def _refresh_comment():
        name = _selected_list_name()
        if name == u'' or name == _pw_cfg._WP_CREATE_DEFAULT_PRESET_NAME:
            text = _pw_cfg._SCENARIO_01_COMMENT
        else:
            comment, _summary = _wp_preset_info_texts(presets, name)
            text = unicode(comment or u'')
        try:
            comment_ed.setText(text)
        except Exception:
            pass

    def _accept_selection():
        name = _selected_list_name()
        if name == u'' or name == _pw_cfg._WP_CREATE_DEFAULT_PRESET_NAME:
            chosen[u'kind'] = u'default'
            chosen[u'name'] = None
        else:
            chosen[u'kind'] = u'preset'
            chosen[u'name'] = name
        try:
            dlg.endExecute()
        except Exception:
            pass

    class _ChooseHandler(unohelper.Base, XActionListener, XItemListener):

        def disposing(self, ev):
            pass

        def itemStateChanged(self, ev):
            _refresh_comment()

        def actionPerformed(self, ev):
            cmd = u''
            try:
                cmd = unicode(ev.ActionCommand)
            except Exception:
                pass
            if cmd == u'LoadBtn':
                _accept_selection()
    h = _ChooseHandler()
    try:
        lb.addItemListener(h)
    except Exception:
        pass
    try:
        ctl = dlg.getControl(u'LoadBtn')
        ctl.addActionListener(h)
        ctl.setActionCommand(u'LoadBtn')
    except Exception:
        pass
    _refresh_comment()
    rc = dlg.execute()
    if chosen[u'kind'] is None and rc == 1:
        name = _selected_list_name()
        if name == u'' or name == _pw_cfg._WP_CREATE_DEFAULT_PRESET_NAME:
            chosen[u'kind'] = u'default'
            chosen[u'name'] = None
        else:
            chosen[u'kind'] = u'preset'
            chosen[u'name'] = name
    try:
        dlg.dispose()
    except Exception:
        pass
    if chosen[u'kind'] == u'preset' and chosen[u'name']:
        return (u'preset', chosen[u'name'])
    if chosen[u'kind'] == u'default':
        return (u'default', None)
    return None

def _wp_remove_unused_bootstrap_param_sheet(doc, bootstrap_name, applied_names):
    """
    Удалить лист, созданный при старте визарда на пустой книге
    (например «[prefix]_1»), если пресет записал другие листы и bootstrap
    не совпадает ни с одним из них. Не удаляет последний лист книги.
    """
    boot = unicode(bootstrap_name or u'').strip()
    if boot == u'' or doc is None:
        return False
    keep = {}
    i = 0
    while i < len(applied_names or []):
        nm = unicode(applied_names[i] or u'').strip()
        if nm != u'':
            keep[nm] = True
        i = i + 1
    if boot in keep:
        return False
    try:
        sheets = doc.Sheets
        if int(sheets.getCount()) <= 1:
            return False
        if not sheets.hasByName(boot):
            return False
        sheets.removeByName(boot)
        return True
    except Exception:
        return False

def _fill_new_param_sheet(doc, sheet, catalog):
    """
    Заполнить только что созданный лист параметров:
    — есть сохранённые пресеты → диалог (шаблон + пресеты) и загрузка;
    — нет пресетов / отмена / шаблон → встроенный набор UNO+ВПР.
    Возвращает лист, с которым дальше работать визарду.
    """
    if sheet is None:
        return None
    bootstrap_name = u''
    try:
        bootstrap_name = unicode(sheet.Name or u'').strip()
    except Exception:
        bootstrap_name = u''
    macro_version = u'3.9.2'
    cw = _try_import_collect()
    if cw is not None:
        try:
            macro_version = unicode(cw.MACRO_VERSION)
        except Exception:
            pass
    presets = _wp_load_presets_list()
    if len(presets) > 0:
        choice = _show_choose_preset_on_create_dialog(doc, presets)
        if choice is not None:
            kind, name = choice
            if kind == u'preset' and name:
                preset = _wp_find_preset_by_name(presets, name)
                if preset is not None:
                    applied_sheet, err, applied_names = _wp_apply_preset_to_doc(
                        doc, preset, catalog, current_sheet=sheet, parent_dialog=None
                    )
                    if err:
                        _show_message(
                            u'Не удалось загрузить пресет «%s»: %s\nБудет шаблон по умолчанию.'
                            % (name, err),
                            doc=doc,
                        )
                    elif applied_sheet is not None or applied_names:
                        _wp_remove_unused_bootstrap_param_sheet(
                            doc, bootstrap_name, applied_names
                        )
                        target = applied_sheet if applied_sheet is not None else sheet
                        try:
                            tname = unicode(target.Name) if target is not None else u''
                        except Exception:
                            tname = u''
                        if (
                            bootstrap_name != u''
                            and tname == bootstrap_name
                            and bootstrap_name not in (applied_names or [])
                        ):
                            target = None
                        if target is None and applied_names:
                            target = _get_sheet_by_name(doc, applied_names[0])
                        if target is not None:
                            _freeze_param_sheet_header(doc, target)
                            _activate_sheet(doc, target)
                            try:
                                if cw is not None:
                                    cw.set_run_param_sheet(target.Name)
                                    cw.refresh_document(doc)
                            except Exception:
                                pass
                            return target
                        return sheet
                    else:
                        _show_message(
                            u'Пресет «%s» пуст или отменён.\nБудет шаблон по умолчанию.' % name,
                            doc=doc,
                        )
                else:
                    _show_message(u'Пресет «%s» не найден.\nБудет шаблон по умолчанию.' % name, doc=doc)
    build_param_sheet_from_scratch(doc, sheet, macro_version, catalog)
    _freeze_param_sheet_header(doc, sheet)
    return sheet

def _param_b_is_see_column_c(text):
    s = unicode(text or u'').strip().casefold()
    return s in (u'смотри в с', u'смотри в c', u'см.c', u'см. c')

def _spec_has_col_c_subdialog(spec):
    return bool(spec and spec.get('col_c_subdialog'))

def _spec_col_c_subdialog_kind(spec):
    return unicode(spec.get('col_c_subdialog_kind') or u'').strip()

def _spec_col_c_keeps_b(spec):
    """True: B — обычное значение (шаблоны), C — JSON через подвизард (Листы_не_удалять)."""
    return bool(spec and spec.get('col_c_keep_b'))

def _spec_col_c_see_only(spec):
    """True: B фиксируется как «смотри в С», всё в JSON колонки C."""
    if not _spec_has_col_c_subdialog(spec):
        return False
    if _spec_col_c_keeps_b(spec):
        return False
    if spec.get('mode') == 'choice':
        return False
    return True

def _spec_col_c_fn_key(spec):
    return unicode(spec.get('col_c_fn_key') or u'').strip()

def _param_ui_yield():
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        if toolkit is not None and hasattr(toolkit, 'processEventsToIdle'):
            toolkit.processEventsToIdle(200)
    except Exception:
        pass

def _param_dispatch_optimal_row_height(doc, sheet, start_row, end_row, end_col):
    controller = None
    saved_sheet = None
    saved_sel = None
    try:
        controller = doc.getCurrentController()
        if controller is None:
            return False
        try:
            saved_sheet = controller.getActiveSheet()
        except Exception:
            pass
        try:
            saved_sel = controller.getSelection()
        except Exception:
            pass
        controller.setActiveSheet(sheet)
        rng = sheet.getCellRangeByPosition(0, int(start_row), int(end_col), int(end_row))
        controller.select(rng)
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        helper = sm.createInstanceWithContext('com.sun.star.frame.DispatchHelper', ctx)
        frame = controller.getFrame()
        if helper is None or frame is None:
            return False
        helper.executeDispatch(frame, '.uno:OptimalRowHeight', '_self', 0, ())
        _param_ui_yield()
        return True
    except Exception:
        return False
    finally:
        if controller is not None:
            try:
                if saved_sheet is not None:
                    controller.setActiveSheet(saved_sheet)
            except Exception:
                pass
            try:
                if saved_sel is not None:
                    controller.select(saved_sel)
            except Exception:
                pass

def _param_reset_row_height_before_autofit(sheet, row):
    """
    Сбросить зафиксированную высоту строки перед OptimalRowHeight.

    После insert/remove высоты «прилипают» к индексам, а не к содержимому:
    без сброса OptimalRowHeight часто оставляет старую высоту.
    """
    if sheet is None or row is None:
        return
    try:
        row_obj = sheet.getRows().getByIndex(int(row))
        try:
            row_obj.OptimalHeight = False
        except Exception:
            pass
        try:
            row_obj.Height = 100
        except Exception:
            pass
        try:
            row_obj.OptimalHeight = True
        except Exception:
            pass
    except Exception:
        pass

def _param_apply_rows_optimal_height(doc, sheet, start_row, end_row, end_col):
    if sheet is None or end_row < start_row:
        return
    rows = sheet.getRows()
    r = int(start_row)
    end_r = int(end_row)
    while r <= end_r:
        _param_reset_row_height_before_autofit(sheet, r)
        if doc is not None:
            _param_dispatch_optimal_row_height(doc, sheet, r, r, end_col)
        else:
            try:
                row_obj = rows.getByIndex(r)
                row_obj.OptimalHeight = True
            except Exception:
                pass
        r = r + 1
    _param_ui_yield()

def _param_autofit_row_heights(doc, sheet, start_row, end_row, end_col):
    """Автоподбор высоты строк таблицы параметров."""
    _param_apply_rows_optimal_height(doc, sheet, start_row, end_row, end_col)

def _param_scale_row_heights(sheet, start_row, end_row, factor=1.1):
    """Умножить высоту строк [start_row..end_row] на factor (после автофита)."""
    if sheet is None or start_row is None or end_row is None:
        return
    try:
        sr = int(start_row)
        er = int(end_row)
    except Exception:
        return
    if er < sr:
        sr, er = (er, sr)
    try:
        f = float(factor)
    except Exception:
        f = 1.1
    if f <= 0:
        return
    rows = sheet.getRows()
    r = sr
    while r <= er:
        try:
            row_obj = rows.getByIndex(r)
            h = int(row_obj.Height)
            if h > 0:
                new_h = int(round(h * f))
                if new_h < h + 1 and f > 1.0:
                    new_h = h + 1
                row_obj.Height = new_h
                try:
                    row_obj.OptimalHeight = False
                except Exception:
                    pass
        except Exception:
            pass
        r = r + 1

def _param_autofit_rows_plus_pct(doc, sheet, start_row, end_row, end_col=None, pct=10):
    """
    Автофит высоты строк, затем увеличить на pct процентов.
    Используется после перемещения параметров вверх/вниз.
    """
    if sheet is None or start_row is None or end_row is None:
        return
    try:
        sr = int(start_row)
        er = int(end_row)
    except Exception:
        return
    if er < sr:
        sr, er = (er, sr)
    if end_col is None:
        end_col = _sheet_last_used_col(sheet, 6)
        if end_col < 5:
            end_col = 5
    _param_autofit_row_heights(doc, sheet, sr, er, int(end_col))
    try:
        factor = 1.0 + float(pct) / 100.0
    except Exception:
        factor = 1.1
    _param_scale_row_heights(sheet, sr, er, factor=factor)

def _param_border_line(color=None, width=10):
    if color is None:
        color = _pw_cfg._PARAM_BORDER_COLOR
    bl = uno.createUnoStruct('com.sun.star.table.BorderLine2')
    bl.Color = int(color)
    bl.LineStyle = 0
    w = int(width)
    bl.LineWidth = w
    bl.InnerLineWidth = w
    bl.OuterLineWidth = w
    return bl

def _param_set_cell_borders(cell, color=None):
    if cell is None:
        return
    line = _param_border_line(color)
    cell.TopBorder = line
    line = _param_border_line(color)
    cell.BottomBorder = line
    line = _param_border_line(color)
    cell.LeftBorder = line
    line = _param_border_line(color)
    cell.RightBorder = line

def _param_apply_range_borders(sheet, col_start, row_start, col_end, row_end):
    try:
        rng = sheet.getCellRangeByPosition(col_start, row_start, col_end, row_end)
        line = _param_border_line()
        tb = uno.createUnoStruct('com.sun.star.table.TableBorder')
        tb.TopLine = line
        tb.BottomLine = _param_border_line()
        tb.LeftLine = _param_border_line()
        tb.RightLine = _param_border_line()
        tb.IsHorizontalLineValid = True
        tb.IsVerticalLineValid = True
        inner = _param_border_line()
        tb.HorizontalLine = inner
        tb.VerticalLine = inner
        rng.TableBorder = tb
        return
    except Exception:
        pass
    row = row_start
    while row <= row_end:
        col = col_start
        while col <= col_end:
            _param_set_cell_borders(sheet.getCellByPosition(col, row))
            col = col + 1
        row = row + 1

def _param_style_header_cell(cell):
    if cell is None:
        return
    cell.CharFontName = _pw_cfg._PARAM_FONT_NAME
    cell.CharHeight = _pw_cfg._PARAM_FONT_SIZE
    try:
        from com.sun.star.awt.FontWeight import BOLD
        cell.CharWeight = BOLD
    except Exception:
        pass
    cell.CellBackColor = _pw_cfg._PARAM_FILL_HEADER
    cell.IsCellBackgroundTransparent = False
    cell.IsTextWrapped = True
    try:
        from com.sun.star.table.CellHoriJustify import CENTER
        from com.sun.star.table.CellVertJustify2 import CENTER as VCENTER
        cell.HoriJustify = CENTER
        cell.VertJustify = VCENTER
    except Exception:
        pass

def _param_style_name_cell(cell):
    if cell is None:
        return
    cell.CharFontName = _pw_cfg._PARAM_FONT_NAME
    cell.CharHeight = _pw_cfg._PARAM_FONT_SIZE
    try:
        from com.sun.star.awt.FontWeight import BOLD
        cell.CharWeight = BOLD
    except Exception:
        pass
    cell.CellBackColor = _pw_cfg._PARAM_FILL_NAME
    cell.IsCellBackgroundTransparent = False
    cell.IsTextWrapped = True
    try:
        from com.sun.star.table.CellHoriJustify import CENTER
        from com.sun.star.table.CellVertJustify2 import CENTER as VCENTER
        cell.HoriJustify = CENTER
        cell.VertJustify = VCENTER
    except Exception:
        pass

def _param_style_value_cell(cell, wrap_top=False):
    if cell is None:
        return
    cell.CharFontName = _pw_cfg._PARAM_FONT_NAME
    cell.CharHeight = _pw_cfg._PARAM_FONT_SIZE
    try:
        from com.sun.star.awt.FontWeight import NORMAL
        cell.CharWeight = NORMAL
    except Exception:
        pass
    cell.IsTextWrapped = True
    try:
        from com.sun.star.table.CellHoriJustify import CENTER
        from com.sun.star.table.CellVertJustify2 import TOP, CENTER as VCENTER
        cell.HoriJustify = CENTER
        cell.VertJustify = TOP if wrap_top else VCENTER
    except Exception:
        pass

def _param_set_column_widths(sheet, last_col):
    if sheet is None:
        return
    try:
        cols = sheet.getColumns()
        col = 0
        while col <= last_col:
            w = _pw_cfg._PARAM_COL_WIDTHS[col] if col < len(_pw_cfg._PARAM_COL_WIDTHS) else 9500
            cols.getByIndex(col).Width = int(w)
            col = col + 1
    except Exception:
        pass

def _param_sheet_hint(name):
    if name is None or unicode(name).strip() == u'':
        return u''
    key = unicode(name).strip()
    if key in _pw_cfg.WIZARD_HINTS:
        return _pw_cfg.WIZARD_HINTS[key]
    return u''

def _param_write_hint_annotation(cell, text):
    if cell is None or text is None or unicode(text).strip() == u'':
        return
    try:
        ann = cell.Annotation
        if ann is None:
            return
        ann.String = unicode(text)
    except Exception:
        pass

def build_param_sheet_from_scratch(doc, sheet, macro_version, catalog=None):
    """
    Создать таблицу параметров с первой строки листа (индекс 0):
    шаблон UNO+ВПР (vlookup_data_low_old), оформление и выпадающие списки.
    """
    if sheet is None:
        return
    _param_sheet_begin_write(sheet)
    try:
        _build_param_sheet_from_scratch_unlocked(doc, sheet, macro_version, catalog)
    finally:
        _param_sheet_end_write(sheet)

def _build_param_sheet_from_scratch_unlocked(doc, sheet, macro_version, catalog=None):
    rows = _default_wizard_param_rows(macro_version)
    max_col = _pw_cfg._PARAM_VALUE_COLUMNS
    last_row = len(rows) - 1
    if last_row < 0:
        return
    try:
        rng = sheet.getCellRangeByPosition(0, 0, max_col, _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS - 1)
        rng.clearContents(7)
    except Exception:
        pass
    row_idx = 0
    comment_row = -1
    while row_idx < len(rows):
        name, vals = (rows[row_idx][0], rows[row_idx][1])
        if _param_match(name, _pw_cfg.P_MERGE_COMMENT):
            comment_row = row_idx
        sheet.getCellByPosition(0, row_idx).String = unicode(name)
        col = 1
        vi = 0
        while vi < max_col:
            cell = sheet.getCellByPosition(col, row_idx)
            if vi < len(vals):
                cell.String = unicode(vals[vi])
            else:
                cell.String = u''
            col = col + 1
            vi = vi + 1
        row_idx = row_idx + 1
    row_idx = 0
    while row_idx <= last_row:
        name = _cell_string(sheet.getCellByPosition(0, row_idx))
        col = 0
        while col <= max_col:
            cell = sheet.getCellByPosition(col, row_idx)
            if row_idx == 0 and _param_match(name, u'Параметр'):
                _param_style_header_cell(cell)
            elif col == 0 and name != u'':
                _param_style_name_cell(cell)
                _param_write_hint_annotation(cell, _param_sheet_hint(name))
            elif comment_row >= 0 and row_idx == comment_row and (col >= 1):
                _param_style_value_cell(cell, wrap_top=True)
            else:
                _param_style_value_cell(cell, wrap_top=False)
            col = col + 1
        row_idx = row_idx + 1
    if comment_row >= 0:
        try:
            sheet.getCellRangeByPosition(1, comment_row, max_col, comment_row).merge(True)
        except Exception:
            pass
    _param_apply_range_borders(sheet, 0, 0, max_col, last_row)
    _param_set_column_widths(sheet, max_col)
    if catalog is not None:
        _apply_param_sheet_validations(sheet, catalog, last_row, extra_empty_rows=3, doc=doc)
    _param_apply_disabled_rows_styles(sheet, catalog)
    _param_autofit_row_heights(doc, sheet, 0, last_row, max_col)

def reformat_param_sheet_table(doc, sheet, catalog=None):
    """Переоформить таблицу параметров без очистки данных (после пресета и т.п.)."""
    if sheet is None:
        return
    _param_sheet_begin_write(sheet)
    try:
        _reformat_param_sheet_table_unlocked(doc, sheet, catalog)
    finally:
        _param_sheet_end_write(sheet)

def _reformat_param_sheet_table_unlocked(doc, sheet, catalog=None):
    _param_sheet_remove_empty_name_rows(sheet)
    _restore_param_sheet_header_row(sheet)
    max_col = _param_sheet_max_value_col(sheet)
    last_row = _sheet_last_used_row(sheet, 30)
    if last_row < 0:
        return
    comment_row = -1
    row_idx = 0
    while row_idx <= last_row:
        name = _cell_string(sheet.getCellByPosition(0, row_idx))
        if _param_match(name, _pw_cfg.P_MERGE_COMMENT):
            comment_row = row_idx
        row_idx = row_idx + 1
    row_idx = 0
    while row_idx <= last_row:
        name = _cell_string(sheet.getCellByPosition(0, row_idx))
        col = 0
        while col <= max_col:
            cell = sheet.getCellByPosition(col, row_idx)
            if row_idx == 0 and _param_match(name, u'Параметр'):
                _param_style_header_cell(cell)
            elif col == 0 and name != u'':
                _param_style_name_cell(cell)
                _param_write_hint_annotation(cell, _param_sheet_hint(name))
            elif comment_row >= 0 and row_idx == comment_row and (col >= 1):
                _param_style_value_cell(cell, wrap_top=True)
            else:
                _param_style_value_cell(cell, wrap_top=False)
            col = col + 1
        row_idx = row_idx + 1
    if comment_row >= 0:
        try:
            sheet.getCellRangeByPosition(1, comment_row, max_col, comment_row).merge(True)
        except Exception:
            pass
    _param_apply_range_borders(sheet, 0, 0, max_col, last_row)
    _param_set_column_widths(sheet, max_col)
    if catalog is not None:
        _apply_param_sheet_validations(sheet, catalog, last_row, extra_empty_rows=3, doc=doc)
    _param_apply_disabled_rows_styles(sheet, catalog)
    _param_autofit_row_heights(doc, sheet, 0, last_row, max_col)

def _freeze_param_sheet_header(doc, sheet):
    if doc is None or sheet is None:
        return
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            if ctrl.getActiveSheet() is None or ctrl.getActiveSheet().Name != sheet.Name:
                ctrl.setActiveSheet(sheet)
            ctrl.freezeAtPosition(0, 1)
    except Exception:
        pass

def _sheet_last_used_row(sheet, default_row=30):
    if sheet is None:
        return default_row
    try:
        cursor = sheet.createCursor()
        cursor.gotoEndOfUsedArea(False)
        return int(cursor.RangeAddress.EndRow)
    except Exception:
        return default_row

def _param_sheet_remove_empty_name_rows(sheet):
    """
    Удалить строки с пустым именем параметра в колонке A (кроме заголовка).
    Снизу вверх, чтобы индексы не сдвигались. Возвращает число удалённых.
    """
    if sheet is None:
        return 0
    _param_sheet_begin_write(sheet)
    try:
        return _param_sheet_remove_empty_name_rows_unlocked(sheet)
    finally:
        _param_sheet_end_write(sheet)

def _param_sheet_remove_empty_name_rows_unlocked(sheet):
    end_row = _param_sheet_scan_end_row(sheet)
    if end_row < 1:
        return 0
    removed = 0
    row = end_row
    while row >= 1:
        name = unicode(_cell_string(sheet.getCellByPosition(0, row)) or u'').strip()
        if name == u'':
            try:
                sheet.getRows().removeByIndex(row, 1)
                removed = removed + 1
            except Exception:
                pass
        row = row - 1
    return removed

def _param_sheet_protect_password():
    try:
        return unicode(_pw_cfg._PARAM_SHEET_PROTECT_PASSWORD or u'')
    except Exception:
        return u''

def _param_sheet_is_protected(sheet):
    if sheet is None:
        return False
    try:
        return bool(sheet.isProtected())
    except Exception:
        pass
    try:
        return bool(sheet.getPropertyValue('IsProtected'))
    except Exception:
        return False

def _param_sheet_set_protected(sheet, protected):
    """Включить/снять защиту листа (пароль из cfg, по умолчанию пустой)."""
    if sheet is None:
        return False
    pwd = _param_sheet_protect_password()
    want = bool(protected)
    try:
        now = bool(sheet.isProtected())
    except Exception:
        now = _param_sheet_is_protected(sheet)
    if now == want:
        return True
    try:
        if want:
            sheet.protect(pwd)
        else:
            sheet.unprotect(pwd)
        return True
    except Exception:
        try:
            if want:
                sheet.protect(u'')
            else:
                sheet.unprotect(u'')
            return True
        except Exception:
            return False

def _param_sheet_write_guard_key(sheet):
    try:
        return unicode(sheet.Name)
    except Exception:
        return u'id:%s' % id(sheet)

def _param_sheet_begin_write(sheet):
    """
    Снять защиту листа перед записью (с учётом вложенности).
    Всегда парно с _param_sheet_end_write в finally.
    """
    if sheet is None:
        return
    try:
        guard = _pw_cfg._PARAM_SHEET_WRITE_GUARD
        was = _pw_cfg._PARAM_SHEET_WRITE_WAS_PROT
    except Exception:
        return
    key = _param_sheet_write_guard_key(sheet)
    depth = int(guard.get(key) or 0)
    if depth <= 0:
        was_prot = _param_sheet_is_protected(sheet)
        if was_prot:
            _param_sheet_set_protected(sheet, False)
        was[key] = bool(was_prot)
        guard[key] = 1
    else:
        guard[key] = depth + 1

def _param_sheet_end_write(sheet):
    """Вернуть защиту листа, если она была до внешнего begin_write."""
    if sheet is None:
        return
    try:
        guard = _pw_cfg._PARAM_SHEET_WRITE_GUARD
        was = _pw_cfg._PARAM_SHEET_WRITE_WAS_PROT
    except Exception:
        return
    key = _param_sheet_write_guard_key(sheet)
    depth = int(guard.get(key) or 0)
    if depth <= 1:
        was_prot = bool(was.pop(key, False))
        if key in guard:
            del guard[key]
        if was_prot:
            _param_sheet_set_protected(sheet, True)
    else:
        guard[key] = depth - 1

def _param_sheet_is_visible(sheet):
    if sheet is None:
        return True
    try:
        return bool(sheet.getPropertyValue('IsVisible'))
    except Exception:
        pass
    try:
        return bool(sheet.IsVisible)
    except Exception:
        return True

def _param_sheet_set_visible(sheet, visible):
    if sheet is None:
        return False
    want = bool(visible)
    try:
        sheet.setPropertyValue('IsVisible', want)
        return True
    except Exception:
        pass
    try:
        from com.sun.star.sheet.SheetVisibility import VISIBLE, HIDDEN
        sheet.setPropertyValue('SheetState', VISIBLE if want else HIDDEN)
        return True
    except Exception:
        try:
            sheet.IsVisible = want
            return True
        except Exception:
            return False

def _param_sheet_has_content(sheet):
    """Есть ли на листе осмысленные параметры (не пустой шаблон)."""
    if sheet is None:
        return False
    markers = (_pw_cfg.P_MERGE_VERSION, u'Файлы-Источники', u'Режим', u'Листы')
    row = 0
    while row < 40:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if name == u'':
            row = row + 1
            continue
        j = 0
        while j < len(markers):
            if _param_match(name, markers[j]):
                return True
            j = j + 1
        row = row + 1
    return False

def _get_active_sheet(doc):
    if doc is None:
        return None
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            return ctrl.getActiveSheet()
    except Exception:
        pass
    return None

def _sheet_is_absolutely_empty(sheet):
    """Быстрое определение «абсолютно пустого» листа (без занятых областей/значений).

    Цель: не переписывать лист при наличии хотя бы небольшого used-area.
    """
    if sheet is None:
        return False
    try:
        cursor = sheet.createCursor()
        cursor.gotoEndOfUsedArea(False)
        ea = cursor.RangeAddress
        end_row = int(ea.EndRow)
        end_col = int(ea.EndColumn)
    except Exception:
        return False

    # На реальном «новом пустом листе» used-area обычно в пределах top-left угла.
    if end_row > 2 or end_col > 2:
        return False

    try:
        r = 0
        while r <= end_row:
            c = 0
            while c <= end_col:
                if unicode(_cell_string(sheet.getCellByPosition(c, r)) or u'').strip() != u'':
                    return False
                c = c + 1
            r = r + 1
    except Exception:
        # Если не смогли прочитать — лучше не считать лист пустым.
        return False

    # Проверка нескольких стандартных ячеек на случай «used-area есть, но значений нет».
    for c, r in ((0, 0), (1, 0), (0, 1), (1, 1), (2, 2)):
        try:
            if unicode(_cell_string(sheet.getCellByPosition(c, r)) or u'').strip() != u'':
                return False
        except Exception:
            pass
    return True

def _next_param_sheet_name(doc, param_prefix):
    """Имя следующего листа параметров: `[prefix]_n`."""
    if doc is None:
        return None
    prefix = unicode(param_prefix or u'').strip()
    if prefix == u'':
        return None
    try:
        sheets = doc.Sheets
    except Exception:
        return None

    n = 1
    while n < 10000:
        suffix = u'_%d' % n
        candidate = prefix + suffix
        try:
            if not sheets.hasByName(candidate):
                return candidate
        except Exception:
            return candidate
        n = n + 1
    return None

def _wp_confirm_load_on_empty_sheet(doc, sheet_name):
    """Запрос при «пустом листе» перед заменой сценария на inplace."""
    title = u'Параметры'
    text = u'Лист «%s» пустой. Загрузить параметры на него сейчас?%s' % (sheet_name, u'\n(пресеты если есть, иначе шаблон по умолчанию)')
    answer = _wp_message_box_execute(doc, None, QUERYBOX, MSG_BUTTONS.BUTTONS_YES_NO, title, text)
    if answer is None:
        return False
    return answer == YES

def _insert_param_sheet(doc, sheet_name=None):
    """Создать лист параметров (надёжный insertNewByName + getByName)."""
    if doc is None:
        return (None, u'Документ недоступен')
    if sheet_name is None:
        sheet_name = _wp_param_sheet_prefix()
    name = unicode(sheet_name).strip()
    if name == u'':
        return (None, u'Пустое имя листа')
    try:
        sheets = doc.Sheets
        if sheets.hasByName(name):
            return (sheets.getByName(name), None)
        try:
            index = int(sheets.getCount())
        except Exception:
            index = 0
        sheets.insertNewByName(name, index)
        if sheets.hasByName(name):
            return (sheets.getByName(name), None)
        return (None, u'Лист не появился после insertNewByName')
    except Exception as err:
        return (None, u'Ошибка создания листа «%s»: %s' % (name, err))

def _activate_sheet(doc, sheet):
    if doc is None or sheet is None:
        return
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            ctrl.setActiveSheet(sheet)
    except Exception:
        pass

def _ensure_param_sheet(doc):
    """
    Создать лист параметров (префикс collect_params / настройка) с шаблоном UNO+ВПР,
    если его нет или он пустой. Возвращает (sheet, error_text, created).
    """
    if doc is None:
        return (None, u'Не открыта книга Calc.', False)

    active_sheet = _get_active_sheet(doc)
    sheet, sheet_err = _resolve_param_sheet_for_ui(doc, allow_create=True)
    if sheet is None and sheet_err:
        return (None, sheet_err, False)

    created = False
    repurposed = False
    param_prefix = _wp_param_sheet_prefix()

    # Новый сценарий: визард вызвали на «абсолютно пустом» листе и
    # в книге ещё нет листов параметров — загрузим inplace на него.
    if sheet is None and active_sheet is not None:
        try:
            active_name = unicode(active_sheet.Name or u'').strip()
        except Exception:
            active_name = u''
        if active_name != u'' and (not _wp_is_param_sheet_name(active_name)):
            if _sheet_is_absolutely_empty(active_sheet) and _wp_confirm_load_on_empty_sheet(doc, active_name):
                # Первый лист — ровно префикс; следующие — prefix_1, prefix_2…
                target_name = param_prefix
                try:
                    if doc.Sheets.hasByName(target_name):
                        target_name = _next_param_sheet_name(doc, param_prefix)
                except Exception:
                    target_name = _next_param_sheet_name(doc, param_prefix)
                if target_name:
                    try:
                        active_sheet.Name = target_name
                        sheet = active_sheet
                        created = True
                        repurposed = True
                    except Exception:
                        # Если переименование не удалось — продолжаем по старой логике.
                        sheet = None
                        created = False
                        repurposed = False

    # Если лист параметров (выбранный для визарда) уже существует и «абсолютно пустой» —
    # не пересоздаём его, просто заполним.
    if sheet is not None and (not repurposed):
        try:
            if active_sheet is sheet and _sheet_is_absolutely_empty(sheet) and (not _param_sheet_has_content(sheet)):
                repurposed = True
                created = True
        except Exception:
            pass

    needs_fill = sheet is None or not _param_sheet_has_content(sheet)
    if needs_fill:
        if repurposed and sheet is not None:
            cw = _try_import_collect()
            if cw is not None:
                try:
                    cw.set_run_param_sheet(sheet.Name)
                    cw.refresh_document(doc)
                except Exception:
                    pass
            _activate_sheet(doc, sheet)
            return (sheet, None, True)

        if sheet is not None:
            try:
                doc.Sheets.removeByName(sheet.Name)
            except Exception:
                pass
            sheet = None
        sheet, err = _insert_param_sheet(doc)
        if sheet is None:
            return (None, err, False)
        cw = _try_import_collect()
        if cw is not None:
            try:
                cw.set_run_param_sheet(sheet.Name)
                cw.refresh_document(doc)
            except Exception:
                pass
        _activate_sheet(doc, sheet)
        created = True
    return (sheet, None, created)

def _get_selection_cell(doc):
    """Текущая ячейка (col, row) 0-based или (None, None)."""
    if doc is None:
        return (None, None)
    try:
        ctrl = doc.getCurrentController()
        if ctrl is None:
            return (None, None)
        sel = ctrl.getSelection()
        if sel is None:
            return (None, None)
        addr = sel.getRangeAddress()
        return (int(addr.StartColumn), int(addr.StartRow))
    except Exception:
        return (None, None)

def _get_selection_row_range(doc):
    """
    Диапазон выделенных строк (start_row, end_row) 0-based или (None, None).
    Поддерживает одну ячейку, прямоугольный диапазон и множественные диапазоны.
    """
    if doc is None:
        return (None, None)
    try:
        ctrl = doc.getCurrentController()
        if ctrl is None:
            return (None, None)
        sel = ctrl.getSelection()
        if sel is None:
            return (None, None)
        try:
            addrs = sel.getRangeAddresses()
            if addrs is not None and len(addrs) > 0:
                start_row = int(addrs[0].StartRow)
                end_row = int(addrs[0].EndRow)
                i = 1
                while i < len(addrs):
                    a = addrs[i]
                    sr = int(a.StartRow)
                    er = int(a.EndRow)
                    if sr < start_row:
                        start_row = sr
                    if er > end_row:
                        end_row = er
                    i = i + 1
                if start_row > end_row:
                    start_row, end_row = (end_row, start_row)
                return (start_row, end_row)
        except Exception:
            pass
        addr = sel.getRangeAddress()
        start_row = int(addr.StartRow)
        end_row = int(addr.EndRow)
        if start_row > end_row:
            start_row, end_row = (end_row, start_row)
        return (start_row, end_row)
    except Exception:
        return (None, None)

def _sheet_last_used_col(sheet, default_col=6):
    if sheet is None:
        return default_col
    try:
        cursor = sheet.createCursor()
        cursor.gotoEndOfUsedArea(False)
        return int(cursor.RangeAddress.EndColumn)
    except Exception:
        return default_col

def _copy_sheet_row(sheet, src_row, dest_row, end_col):
    """Скопировать одну строку (значения + форматы) через copyRange."""
    src = sheet.getCellRangeByPosition(0, int(src_row), int(end_col), int(src_row))
    dest = sheet.getCellByPosition(0, int(dest_row))
    sheet.copyRange(dest.CellAddress, src.RangeAddress)

def _merge_param_move_rows(doc, sheet, start_row, end_row, direction, min_row=1):
    """
    Сдвиг блока строк на 1 вверх/вниз без потерь (перестановка с соседней строкой).
    direction: -1 (вверх) или +1 (вниз)
    min_row: минимальная разрешённая строка (0-based), по умолчанию 1 (не трогаем заголовок)

    Реализация: insertByIndex + copyRange + removeByIndex (без временных колонок
    за пределами листа Calc).

    Возвращает:
      (ok, err, new_start, new_end, touch_start, touch_end)
    где [new_start..new_end] — позиция перемещённого блока,
    [touch_start..touch_end] — все затронутые строки (блок + соседняя).
    """
    if doc is None or sheet is None or start_row is None or (end_row is None):
        return (False, u'Не удалось определить выделение.', None, None, None, None)
    try:
        start_row = int(start_row)
        end_row = int(end_row)
    except Exception:
        return (False, u'Некорректный диапазон строк.', None, None, None, None)
    if start_row > end_row:
        start_row, end_row = (end_row, start_row)
    if start_row < int(min_row):
        return (False, u'Выделите строку параметра (не заголовок таблицы).', None, None, None, None)
    last_row = _sheet_last_used_row(sheet, 30)
    if last_row < int(min_row):
        return (False, u'На листе нет параметров для перемещения.', None, None, None, None)
    end_col = _sheet_last_used_col(sheet, 6)
    if end_col < 5:
        end_col = 5
    rows = sheet.getRows()
    _param_sheet_begin_write(sheet)
    try:
        try:
            if int(direction) < 0:
                if start_row <= int(min_row):
                    return (False, u'Выше сдвигать нельзя (граница таблицы).', None, None, None, None)
                rows.insertByIndex(end_row + 1, 1)
                _copy_sheet_row(sheet, start_row - 1, end_row + 1, end_col)
                rows.removeByIndex(start_row - 1, 1)
                new_start = start_row - 1
                new_end = end_row - 1
                return (True, None, new_start, new_end, new_start, end_row)
            if end_row >= int(last_row):
                return (False, u'Ниже сдвигать нельзя (граница таблицы).', None, None, None, None)
            rows.insertByIndex(start_row, 1)
            _copy_sheet_row(sheet, end_row + 2, start_row, end_col)
            rows.removeByIndex(end_row + 2, 1)
            new_start = start_row + 1
            new_end = end_row + 1
            return (True, None, new_start, new_end, start_row, new_end)
        except Exception as e:
            return (False, u'Не удалось переместить строки: %s' % e, None, None, None, None)
    finally:
        _param_sheet_end_write(sheet)

def _active_param_sheet_for_move(doc):
    """Активный лист параметров или (None, error). Не создаёт лист заново."""
    if doc is None:
        return (None, u'Не открыта книга Calc.')
    try:
        ctrl = doc.getCurrentController()
        if ctrl is None:
            return (None, u'Не удалось определить активный лист.')
        active = ctrl.getActiveSheet()
        if active is None:
            return (None, u'Не удалось определить активный лист.')
        name = unicode(active.Name)
        if _wp_is_param_sheet_name(name):
            return (active, None)
        return (None, u'Активируйте лист «%s» (или лист с таким префиксом) и выделите строки параметров.' % _pw_cfg.MERGE_PARAM_SHEET_NAME)
    except Exception:
        return (None, u'Не удалось определить активный лист.')

def _param_wizard_select_rows(doc, sheet, start_row, end_row):
    try:
        ctrl = doc.getCurrentController()
        if ctrl is None:
            return
        ctrl.setActiveSheet(sheet)
        sr = int(start_row)
        er = int(end_row)
        if er < sr:
            sr, er = (er, sr)
        ctrl.select(sheet.getCellRangeByPosition(0, sr, 1, er))
    except Exception:
        pass

def _row_param_name(sheet, row):
    if sheet is None or row is None or int(row) < 0:
        return u''
    name = _cell_string(sheet.getCellByPosition(0, int(row)))
    if int(row) == 0 and _param_match(name, u'Параметр'):
        return u''
    return name

def _find_catalog_spec(catalog, param_name):
    if catalog is None or param_name is None:
        return None
    canonical = _param_canonical_sheet_name(param_name)
    i = 0
    while i < len(catalog):
        if _param_match(catalog[i]['name'], canonical):
            return catalog[i]
        i = i + 1
    return None

def _spec_has_inline_transfer(spec):
    """Способ переноса в колонке C строки «Режим» (визард / инлайн-атрибут)."""
    if spec is None:
        return False
    if spec.get('inline_transfer'):
        return True
    pt = spec.get('paired_transfer')
    return pt not in (None, False, u'')

def _normalize_pp_fn_key(fn_key):
    try:
        from libre_macros_param_codec import normalize_fn_key
        return normalize_fn_key(fn_key)
    except Exception:
        return unicode(fn_key or u'').strip().casefold()

def _find_sheet_pp_extra_for_fn(sheet, spec, fn_key, exclude_row=None):
    """
    Найти JSON/текст в C другой строки того же параметра (A) с той же функцией (B).
    exclude_row — текущая редактируемая строка (не копировать из себя).
    """
    if sheet is None or spec is None:
        return u''
    if spec.get('mode') not in ('postprocess_range', 'postprocess_row'):
        return u''
    want = _normalize_pp_fn_key(fn_key)
    if want == u'':
        return u''
    param_name = spec.get('name', u'')
    excl = -1
    if exclude_row is not None:
        try:
            excl = int(exclude_row)
        except Exception:
            excl = -1
    row = 0
    end_row = _param_sheet_scan_end_row(sheet)
    while row <= end_row:
        pname = _row_param_name(sheet, row)
        if row == 0 and _param_match(pname, u'Параметр'):
            row = row + 1
            continue
        if pname == u'':
            row = row + 1
            continue
        if row == excl:
            row = row + 1
            continue
        if not _sheet_name_matches_param(pname, param_name):
            row = row + 1
            continue
        primary, _plugin_ref, extra = _read_pp_row_values(sheet, row)
        got = _normalize_pp_fn_key(primary)
        if got == want:
            val = unicode(extra or u'').strip()
            if val != u'':
                return val
        row = row + 1
    return u''

def _read_pp_row_values(sheet, row):
    """B/C/D строки постобработки: (primary, plugin_ref, extra)."""
    b = _cell_string(sheet.getCellByPosition(1, int(row)))
    c = _cell_string(sheet.getCellByPosition(2, int(row)))
    d = _cell_string(sheet.getCellByPosition(3, int(row)))
    if _pp_is_plugin_primary(b):
        return (b, c, d)
    return (b, u'', c)

def _read_values_at_row(sheet, spec, row, col=None):
    """Значения B/C из конкретной строки (с учётом активной колонки)."""
    if sheet is None or spec is None or row is None or (int(row) < 1):
        return (u'', u'', u'')
    row = int(row)
    mode = spec.get('mode', 'text')
    primary = u''
    extra = u''
    plugin_ref = u''
    icol = int(col) if col is not None else -1
    if mode in ('postprocess_range', 'postprocess_row'):
        primary, plugin_ref, extra = _read_pp_row_values(sheet, row)
        return (primary, extra, plugin_ref)
    if mode == 'vlookup':
        return (_vlookup_read_row_values(sheet, row), None, u'')
    if mode in ('merge_sheets', 'split_sheets'):
        return (_cell_string(sheet.getCellByPosition(2, row)), None, u'')
    if spec.get('col_c_subdialog'):
        extra = _cell_string(sheet.getCellByPosition(2, row))
        if _spec_col_c_keeps_b(spec) or spec.get('mode') == 'choice':
            primary = _cell_string(sheet.getCellByPosition(1, row))
            return (primary, extra, u'')
        # see-only: B = «смотри в С»; C = JSON. Legacy pre_shell: JSON мог быть в B.
        if extra == u'' and spec.get('mode') == 'pre_shell':
            b_old = _cell_string(sheet.getCellByPosition(1, row))
            if b_old != u'' and (not _param_b_is_see_column_c(b_old)):
                extra = b_old
        return (_pw_cfg._PARAM_B_SEE_COLUMN_C, extra, u'')
    if mode == 'files':
        if icol >= 1:
            vals = _row_values_upto_col(sheet, row, icol)
        else:
            vals = _row_values(sheet, row)
        if len(vals) == 0:
            return (u'', extra, u'')
        return (_join_files_path_text(vals, u';'), extra, u'')
    if spec.get('multi_column'):
        if icol >= 1:
            primary = _cell_string(sheet.getCellByPosition(icol, row))
        else:
            vals = _row_values(sheet, row)
            primary = vals[0] if len(vals) > 0 else u''
        return (primary, extra, u'')
    if mode == 'choice' and _spec_has_inline_transfer(spec):
        primary = _cell_string(sheet.getCellByPosition(1, row))
        extra = _cell_string(sheet.getCellByPosition(2, row))
        return (primary, extra, u'')
    if icol >= 1:
        primary = _cell_string(sheet.getCellByPosition(icol, row))
    else:
        vals = _row_values(sheet, row)
        primary = vals[0] if len(vals) > 0 else u''
    return (primary, extra, u'')

def _transfer_param_name():
    cw = _try_import_collect()
    if cw is not None:
        return getattr(cw, 'P_MERGE_DATA_TRANSFER', u'Способ_переноса')
    return u'Способ_переноса'

def _transfer_wizard_choices(catalog=None):
    spec = None
    if catalog is not None:
        spec = _find_catalog_spec(catalog, _transfer_param_name())
    if spec is not None:
        choices = spec.get('choices') or []
        if len(choices) > 0:
            return list(choices)
    return [u'По_API', u'Буфер_по_заголовкам', u'Буфер_по_позиции', u'xml_excel_ods']

def _read_transfer_wizard_value(sheet, mode_row=None):
    """Значение для combo при редактировании «Режим» — колонка C той же строки."""
    row = None
    if mode_row is not None and int(mode_row) >= 0:
        row = int(mode_row)
    else:
        cw = _try_import_collect()
        p_mode = getattr(cw, 'P_MERGE_MODE', u'Режим') if cw is not None else u'Режим'
        found = _find_param_row(sheet, p_mode)
        if found >= 0:
            row = found
    if row is not None and row >= 0:
        val = _cell_string(sheet.getCellByPosition(2, row))
        if val != u'':
            return val
    return _pw_cfg._TRANSFER_WIZARD_DEFAULT

def _mode_value_uses_transfer(mode_primary):
    return True

def _scan_sheet_param_entries(sheet, catalog):
    """
    Строки параметров на листе в порядке следования (только имена из каталога).
    Пустые строки в A пропускаются до конца used-range.
    Возвращает список dict: row, name, spec, label.
    """
    if sheet is None or catalog is None:
        return []
    entries = []
    end_row = _param_sheet_scan_end_row(sheet)
    row = 0
    while row <= end_row:
        pname = _row_param_name(sheet, row)
        if row == 0 and pname == u'' and _param_match(_cell_string(sheet.getCellByPosition(0, 0)), u'Параметр'):
            row = row + 1
            continue
        if pname == u'':
            row = row + 1
            continue
        spec = _find_catalog_spec(catalog, pname)
        if spec is not None:
            canonical = _param_canonical_sheet_name(pname)
            entries.append({'row': int(row), 'name': canonical, 'sheet_name': pname, 'spec': spec, 'disabled': _param_sheet_name_is_disabled(pname), 'label': pname})
        row = row + 1
    name_counts = {}
    i = 0
    while i < len(entries):
        key = entries[i]['name'].lower()
        name_counts[key] = name_counts.get(key, 0) + 1
        i = i + 1
    i = 0
    while i < len(entries):
        if name_counts.get(entries[i]['name'].lower(), 0) > 1:
            entries[i]['label'] = u'%s — стр. %d' % (entries[i]['sheet_name'], entries[i]['row'] + 1)
        i = i + 1
    return entries

def _catalog_names_for_new_param(sheet, catalog):
    """
    Имена параметров для режима «новый параметр»: все из каталога, кроме
    одноэкземплярных (multi_row=False), уже присутствующих на листе.
    """
    if catalog is None:
        return []
    existing_singletons = set()
    if sheet is not None:
        end_row = _param_sheet_scan_end_row(sheet)
        row = 0
        while row <= end_row:
            pname = _row_param_name(sheet, row)
            if row == 0 and pname == u'' and _param_match(_cell_string(sheet.getCellByPosition(0, 0)), u'Параметр'):
                row = row + 1
                continue
            if pname == u'':
                row = row + 1
                continue
            spec = _find_catalog_spec(catalog, pname)
            if spec is not None and (not spec.get('multi_row')):
                existing_singletons.add(_param_canonical_sheet_name(spec['name']).lower())
            row = row + 1
    out = []
    i = 0
    while i < len(catalog):
        spec = catalog[i]
        nm = spec['name']
        if spec.get('multi_row') or nm.lower() not in existing_singletons:
            out.append(nm)
        i = i + 1
    return out

def _is_pivot_table_pp_name(name):
    return unicode(name or u'').strip().casefold() == u'сводная_таблица'

def _spec_is_postprocess_xml(spec):
    """True — параметр «Постобработка_xml» (сводная только as_values)."""
    if spec is None:
        return False
    name = unicode(spec.get('name') or u'').strip()
    if name == u'':
        return False
    return name.casefold() == u'Постобработка_xml'.casefold()

def _build_initial_from_row(sheet, catalog, row, col=-1):
    """Контекст предзаполнения основного окна визарда для строки параметра."""
    pname = _row_param_name(sheet, row)
    if pname == u'':
        return None
    spec = _find_catalog_spec(catalog, pname)
    if spec is None:
        return None
    primary, extra, plugin_ref = _read_values_at_row(sheet, spec, row, col if col is not None and int(col) >= 0 else None)
    return {'spec': spec, 'row': int(row), 'col': int(col) if col is not None and int(col) >= 0 else -1, 'primary': primary, 'extra': extra, 'plugin_ref': plugin_ref}

def _param_row_has_subdialog(spec, fn_key):
    """Есть ли у строки постобработки / ВПР отдельный субдиалог для колонки C."""
    mode = spec.get('mode') if spec is not None else None
    if mode == 'vlookup':
        return True
    if mode in ('merge_sheets', 'split_sheets'):
        return True
    if mode not in ('postprocess_range', 'postprocess_row'):
        return False
    fn = unicode(fn_key or u'').strip()
    if fn == u'' or _pp_is_plugin_primary(fn):
        return False
    try:
        from libre_macros_param_codec import normalize_fn_key
        fn = normalize_fn_key(fn) or fn
    except Exception:
        pass
    return _inner_codec_dialog_supported(fn) or _is_pivot_table_pp_name(fn)

def _try_subdialog_from_row(sheet, catalog, spec, row):
    """
    Субдиалог для колонки C существующей строки.
    Возвращает dict(kind, spec, row, …) или None.
    """
    if spec is None or row is None or int(row) < 1:
        return None
    row = int(row)
    mode = spec.get('mode')
    if mode == 'vlookup':
        return {'kind': 'vlookup', 'spec': spec, 'row': row, 'initial': _vlookup_read_row_values(sheet, row)}
    if mode == 'merge_sheets':
        return {'kind': 'merge_sheets', 'spec': spec, 'row': row, 'initial': _cell_string(sheet.getCellByPosition(2, row))}
    if mode == 'split_sheets':
        return {'kind': 'split_sheets', 'spec': spec, 'row': row, 'initial': _cell_string(sheet.getCellByPosition(2, row))}
    if mode not in ('postprocess_range', 'postprocess_row'):
        return None
    fn_b = _cell_string(sheet.getCellByPosition(1, row))
    initial_text = _cell_string(sheet.getCellByPosition(2, row))
    if _param_match(fn_b, u'объединить_листы_в_один'):
        merge_spec = _find_catalog_spec(catalog, u'объединить_листы_в_один')
        if merge_spec is not None:
            return {'kind': 'merge_sheets', 'spec': merge_spec, 'row': row, 'initial': initial_text}
    if _param_match(fn_b, u'разделить_листы'):
        split_spec = _find_catalog_spec(catalog, u'разделить_листы')
        if split_spec is not None:
            return {'kind': 'split_sheets', 'spec': split_spec, 'row': row, 'initial': initial_text}
    if not _param_row_has_subdialog(spec, fn_b):
        return None
    if _is_pivot_table_pp_name(fn_b):
        return {'kind': 'pivot', 'spec': spec, 'row': row, 'fn_key': fn_b, 'initial_text': initial_text}
    return {'kind': 'inner_codec', 'spec': spec, 'row': row, 'fn_key': fn_b, 'initial_text': initial_text}

def _active_sheet_is_param_sheet(doc, param_sheet):
    try:
        ctrl = doc.getCurrentController()
        active = ctrl.getActiveSheet() if ctrl is not None else None
        return active is not None and param_sheet is not None and (unicode(active.Name) == unicode(param_sheet.Name))
    except Exception:
        return False

def _wizard_launch_plan(doc, param_sheet, catalog):
    """
    План открытия визарда по позиции курсора.

    action: "subdialog" | "main"
    new_param_mode: для основного окна
    initial: контекст предзаполнения (main) или None
    subdialog: описание субдиалога (subdialog) или None
    """
    entries = _scan_sheet_param_entries(param_sheet, catalog)
    on_param_sheet = _active_sheet_is_param_sheet(doc, param_sheet)
    col, row = _get_selection_cell(doc) if on_param_sheet else (None, None)
    if not on_param_sheet:
        if len(entries) > 0:
            e = entries[0]
            return {'action': 'main', 'new_param_mode': False, 'initial': _build_initial_from_row(param_sheet, catalog, e['row'], -1), 'subdialog': None}
        return {'action': 'main', 'new_param_mode': True, 'initial': None, 'subdialog': None}
    if row is None or int(row) < 0:
        row = entries[0]['row'] if len(entries) > 0 else _first_empty_row(param_sheet)
    row = int(row)
    pname = _row_param_name(param_sheet, row)
    if pname == u'':
        return {'action': 'main', 'new_param_mode': True, 'initial': None, 'subdialog': None}
    spec = _find_catalog_spec(catalog, pname)
    if spec is None:
        return {'action': 'main', 'new_param_mode': True, 'initial': None, 'subdialog': None}
    icol = int(col) if col is not None else -1
    mode = spec.get('mode')
    if mode == 'source_extra' and icol >= 1:
        initial_text = _cell_string(param_sheet.getCellByPosition(icol, row))
        source_path = _source_extra_path_for_col(param_sheet, icol)
        return {
            'action': 'subdialog',
            'new_param_mode': False,
            'initial': None,
            'subdialog': {
                'kind': 'source_extra',
                'spec': spec,
                'row': row,
                'target_col': icol,
                'initial_text': initial_text,
                'source_path': source_path,
            },
        }
    if mode == 'pre_shell' and icol >= 1:
        # JSON в C (B = «смотри в С»); legacy — JSON ещё мог лежать в B.
        b_text = _cell_string(param_sheet.getCellByPosition(1, row))
        c_text = _cell_string(param_sheet.getCellByPosition(2, row))
        if _param_b_is_see_column_c(b_text) or c_text != u'':
            initial_text = c_text
        else:
            initial_text = b_text
        return {
            'action': 'subdialog',
            'new_param_mode': False,
            'initial': None,
            'subdialog': {
                'kind': 'pre_shell',
                'spec': spec,
                'row': row,
                'target_col': 2,
                'initial_text': initial_text,
            },
        }
    if mode in ('merge_sheets', 'split_sheets'):
        sub = _try_subdialog_from_row(param_sheet, catalog, spec, row)
        if sub is not None:
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': sub}
    if mode in ('postprocess_range', 'postprocess_row'):
        fn_b = _cell_string(param_sheet.getCellByPosition(1, row))
        if _param_match(fn_b, u'объединить_листы_в_один') or _param_match(fn_b, u'разделить_листы'):
            sub = _try_subdialog_from_row(param_sheet, catalog, spec, row)
            if sub is not None:
                return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': sub}
    if _param_match(pname, u'Листы') and icol >= 1:
        initial_text = _cell_string(param_sheet.getCellByPosition(icol, row))
        # C: JSON/lambda-фильтр → sheets_include_filter; иначе редактор source→target.
        looks_like_filter = False
        try:
            from libre_macros_param_codec import sheets_map_is_filter_payload
            looks_like_filter = sheets_map_is_filter_payload(initial_text)
        except Exception:
            s = unicode(initial_text or u'').strip()
            lead = s.lstrip()
            looks_like_filter = lead.startswith(u'lambda') or lead.startswith(u'def ')
        if icol == 2 and looks_like_filter:
            return {
                'action': 'subdialog',
                'new_param_mode': False,
                'initial': None,
                'subdialog': {'kind': 'sheets_include_filter', 'spec': spec, 'row': row, 'initial_text': initial_text},
            }
        return {
            'action': 'subdialog',
            'new_param_mode': False,
            'initial': None,
            'subdialog': {'kind': 'sheets_pick_rename', 'spec': spec, 'row': row, 'target_col': icol, 'initial_text': initial_text},
        }
    if _param_match(pname, u'Столбцы') and icol >= 1:
        initial_text = _cell_string(param_sheet.getCellByPosition(icol, row))
        return {
            'action': 'subdialog',
            'new_param_mode': False,
            'initial': None,
            'subdialog': {'kind': 'columns_pick_rename', 'spec': spec, 'row': row, 'target_col': icol, 'initial_text': initial_text},
        }
    if icol == 2:
        if _param_match(pname, u'удаление_верхних_строк'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'delete_top_rows', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Пропуск_строк_источника'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'skip_source_rows', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Предварительный_скрипт'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'pre_shell', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Строка_Заголовков'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'header_row', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Ячейка_В_Столбец'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'cell_to_column', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Добавить_в_карту_переменных'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'add_to_variables_map', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Ручной_ввод_в_карту_переменных') or _param_match(pname, u'ручной_ввод') or _param_match(pname, u'manual_variable_input'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'manual_variable_input', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Листы_не_удалять'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'sheets_undelete_filter', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'Листы_удалить'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'sheets_force_delete_filter', 'spec': spec, 'row': row, 'initial_text': initial_text}}
        if _param_match(pname, u'автофильтр_результата'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'sheet_list_fn', 'spec': spec, 'row': row, 'fn_key': u'автофильтр', 'initial_text': initial_text}}
        if _param_match(pname, u'закрепить_заголовок'):
            initial_text = _cell_string(param_sheet.getCellByPosition(2, row))
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': {'kind': 'sheet_list_fn', 'spec': spec, 'row': row, 'fn_key': u'закрепить_заголовок', 'initial_text': initial_text}}
        sub = _try_subdialog_from_row(param_sheet, catalog, spec, row)
        if sub is not None:
            return {'action': 'subdialog', 'new_param_mode': False, 'initial': None, 'subdialog': sub}
    return {'action': 'main', 'new_param_mode': False, 'initial': _build_initial_from_row(param_sheet, catalog, row, icol), 'subdialog': None}

def _run_subdialog_and_save(doc, sheet, catalog, sub):
    """Открыть субдиалог и записать результат в строку параметра."""
    if sub is None:
        return False
    kind = sub.get('kind')
    spec = sub.get('spec')
    row = int(sub.get('row', -1))
    if spec is None or row < 1:
        return False
    if kind == 'vlookup':
        result = show_vlookup_param_dialog(None, sub.get('initial'), doc=doc)
        if result is None:
            return False
        row = apply_param_value(sheet, spec, result, None, target_row=row, target_col=2, catalog=catalog, doc=doc)
    elif kind == 'merge_sheets':
        result = show_merge_sheets_param_dialog(None, sub.get('initial'), doc=doc)
        if result is None:
            return False
        row = apply_param_value(sheet, spec, result, None, target_row=row, target_col=2, catalog=catalog, doc=doc)
    elif kind == 'split_sheets':
        result = show_split_sheets_param_dialog(None, sub.get('initial'), doc=doc)
        if result is None:
            return False
        row = apply_param_value(sheet, spec, result, None, target_row=row, target_col=2, catalog=catalog, doc=doc)
    elif kind == 'pivot':
        pivot_json = show_pivot_table_param_dialog(None, sub.get('initial_text'), doc=doc, param_sheet=sheet, param_row=row, param_primary=sub.get('fn_key'), force_as_values=_spec_is_postprocess_xml(spec))
        if pivot_json is None:
            return False
    elif kind == 'inner_codec':
        result = _show_inner_codec_param_dialog(
            None,
            sub.get('fn_key'),
            sub.get('initial_text'),
            doc=doc,
            force_as_values=_spec_is_postprocess_xml(spec),
        )
        if result is None:
            return False
        primary = _cell_string(sheet.getCellByPosition(1, row))
        row = apply_param_value(sheet, spec, primary, result, target_row=row, catalog=catalog, doc=doc)
    elif kind == 'delete_top_rows':
        result_text = show_delete_top_rows_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'skip_source_rows':
        result_text = show_skip_source_rows_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'header_row':
        result_text = show_header_row_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'source_extra':
        target_col = int(sub.get('target_col') or 1)
        if target_col < 1:
            target_col = 1
        result_text = show_source_extra_param_dialog(
            None,
            sub.get('initial_text'),
            doc=doc,
            source_path=sub.get('source_path'),
            target_col=target_col,
        )
        if result_text is None:
            return False
        try:
            if _row_param_name(sheet, row) == u'':
                sheet.getCellByPosition(0, row).String = spec['name']
        except Exception:
            pass
        _files_prepare_value_column(doc, sheet, target_col)
        try:
            sheet.getCellByPosition(target_col, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(target_col, row).String = u''
        _ensure_param_row_formatting(sheet, row, catalog, spec, False, doc=doc)
    elif kind == 'pre_shell':
        result_text = show_pre_shell_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            if _row_param_name(sheet, row) == u'':
                sheet.getCellByPosition(0, row).String = spec['name']
        except Exception:
            pass
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
        _ensure_param_row_formatting(sheet, row, catalog, spec, False, doc=doc)
    elif kind == 'cell_to_column':
        result_text = show_cell_to_column_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'add_to_variables_map':
        result_text = show_add_to_variables_map_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'manual_variable_input':
        result_text = show_manual_variable_input_param_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
        except Exception:
            pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'sheet_list_fn':
        fn_key = sub.get('fn_key')
        result_text = _show_sheet_list_panel_dialog(None, fn_key, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        if spec.get('mode') != 'choice':
            try:
                sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
            except Exception:
                pass
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'sheets_undelete_filter':
        result_text = show_sheets_undelete_filter_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        # B не трогаем — там шаблоны имён листов
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'sheets_force_delete_filter':
        result_text = show_sheets_force_delete_filter_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'sheets_include_filter':
        result_text = show_sheets_include_filter_dialog(None, sub.get('initial_text'), doc=doc)
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(2, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(2, row).String = u''
    elif kind == 'sheets_pick_rename':
        target_col = int(sub.get('target_col', 1))
        if target_col < 1:
            target_col = 1
        source_path = u''
        try:
            source_path = _sheets_wizard_source_path_for_col(sheet, target_col, doc=doc)
        except Exception:
            source_path = u''
        result_text = show_sheets_pick_rename_dialog(
            None, sub.get('initial_text'), doc=doc, source_path=source_path,
        )
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(target_col, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(target_col, row).String = u''
    elif kind == 'columns_pick_rename':
        target_col = int(sub.get('target_col', 1))
        if target_col < 1:
            target_col = 1
        source_path = u''
        try:
            source_path = _sheets_wizard_source_path_for_col(sheet, target_col, doc=doc)
        except Exception:
            source_path = u''
        result_text = show_columns_pick_rename_dialog(
            None, sub.get('initial_text'), doc=doc, source_path=source_path,
        )
        if result_text is None:
            return False
        try:
            sheet.getCellByPosition(target_col, row).String = unicode(result_text).strip()
        except Exception:
            sheet.getCellByPosition(target_col, row).String = u''
    else:
        return False
    _param_wizard_finalize(doc, sheet, catalog, spec, row, is_new=False)
    return True

def _wizard_initial_context(doc, sheet, catalog):
    """
    Если курсор на строке с известным параметром — данные для предзаполнения формы.
    Учитывается только когда активный лист совпадает с листом параметров.
    """
    if not _active_sheet_is_param_sheet(doc, sheet):
        return None
    col, row = _get_selection_cell(doc)
    if row is None or int(row) < 0:
        return None
    return _build_initial_from_row(sheet, catalog, int(row), col)

def _try_open_pivot_from_selection(doc, sheet, catalog):
    """Устар.: используйте _wizard_launch_plan. Оставлено для совместимости."""
    plan = _wizard_launch_plan(doc, sheet, catalog)
    sub = plan.get('subdialog')
    if plan.get('action') != 'subdialog' or sub is None or sub.get('kind') != 'pivot':
        return None
    return (sub['spec'], sub['row'], sub.get('initial_text', u''))

def _find_param_row(sheet, param_name):
    end_row = _param_sheet_scan_end_row(sheet)
    row = 0
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if row == 0 and _param_match(name, u'Параметр'):
            row = row + 1
            continue
        if name == u'':
            row = row + 1
            continue
        if _sheet_name_matches_param(name, param_name):
            return row
        row = row + 1
    return -1

def _first_empty_row(sheet):
    """Первая свободная строка для нового параметра (пропуск заголовка; пустые A — кандидаты)."""
    end_row = _param_sheet_scan_end_row(sheet)
    row = 0
    last_used = 0
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if row == 0 and _param_match(name, u'Параметр'):
            row = row + 1
            continue
        if name != u'':
            last_used = row
            row = row + 1
            continue
        return row
    return last_used + 1

def _row_values(sheet, row, max_cols=20):
    vals = []
    col = 1
    while col < max_cols:
        v = _cell_string(sheet.getCellByPosition(col, row))
        if v == u'':
            break
        vals.append(v)
        col = col + 1
    return vals

def _row_values_upto_col(sheet, row, col, max_cols=20):
    """
    Непустые значения в B… до активного столбца включительно.
    На B — непрерывная цепочка с B (_row_values).
    """
    icol = int(col) if col is not None else -1
    if icol <= 1:
        return _row_values(sheet, row, max_cols)
    vals = []
    c = 1
    end = min(icol + 1, max_cols)
    while c < end:
        v = _cell_string(sheet.getCellByPosition(c, row))
        if v != u'':
            vals.append(v)
        c = c + 1
    if len(vals) == 0:
        return _row_values(sheet, row, max_cols)
    return vals

def _first_empty_value_col(sheet, row, start_col=1, max_cols=20):
    col = start_col
    while col < max_cols:
        if _cell_string(sheet.getCellByPosition(col, row)) == u'':
            return col
        col = col + 1
    return -1

def _catalog_param_names(catalog):
    names = []
    seen = set()
    for spec in catalog or []:
        n = unicode(spec.get('name', u'')).strip()
        if n == u'' or n in seen:
            continue
        names.append(n)
        seen.add(n)
    return names

def _find_param_template_row(sheet):
    """Первая строка таблицы параметров с именем в A (образец формата)."""
    end_row = _param_sheet_scan_end_row(sheet)
    row = 0
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if row == 0 and _param_match(name, u'Параметр'):
            row = row + 1
            continue
        if name == u'':
            row = row + 1
            continue
        return row
    return -1

def _find_param_format_source_row(sheet, before_row=None):
    """Последняя заполненная строка таблицы перед before_row — образец формата."""
    if before_row is not None and int(before_row) > 0:
        row = int(before_row) - 1
        while row >= 0:
            name = _cell_string(sheet.getCellByPosition(0, row))
            if row == 0 and _param_match(name, u'Параметр'):
                row = row - 1
                continue
            if name != u'':
                return row
            row = row - 1
    last = -1
    row = 0
    end_row = _param_sheet_scan_end_row(sheet)
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if row == 0 and _param_match(name, u'Параметр'):
            row = row + 1
            continue
        if name == u'':
            row = row + 1
            continue
        last = row
        row = row + 1
    if last >= 0:
        return last
    return _find_param_template_row(sheet)

def _param_sheet_row_last_col(sheet, row, max_cols=20):
    last = 0
    col = 0
    while col < max_cols:
        if _cell_string(sheet.getCellByPosition(col, row)) != u'':
            last = col
        col = col + 1
    return max(last, 2)

def _param_sheet_max_value_col(sheet, min_col=None, max_scan=40):
    """Правый индекс столбца значений (B=1) по заголовкам «Значение N» и данным листа."""
    header_last = _param_sheet_header_value_max_col(sheet, max_scan=max_scan, fallback=0)
    last = header_last
    row_end = _sheet_last_used_row(sheet, _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS - 1)
    if row_end < 0:
        row_end = 0
    row = 0
    while row <= row_end:
        lc = _param_sheet_row_last_col(sheet, row, max_cols=max_scan)
        if lc > last:
            last = lc
        row = row + 1
    if min_col is None:
        min_col = header_last if header_last > 0 else _pw_cfg._PARAM_VALUE_COLUMNS
    return max(last, int(min_col))

def _refresh_param_sheet_value_merges(doc, sheet, catalog=None):
    """Пересобрать объединение строки «Комментарий» на все столбцы «Значение N»."""
    if sheet is None:
        return
    max_col = _param_sheet_max_value_col(sheet)
    comment_row = _find_param_row(sheet, _pw_cfg.P_MERGE_COMMENT)
    if comment_row < 0:
        row = 0
        while row < 10:
            if _param_match(_row_param_name(sheet, row), _pw_cfg.P_MERGE_COMMENT):
                comment_row = row
                break
            row = row + 1
    if comment_row >= 0 and max_col >= 1:
        try:
            sheet.getCellRangeByPosition(1, comment_row, 39, comment_row).merge(False)
        except Exception:
            pass
        try:
            sheet.getCellRangeByPosition(1, comment_row, max_col, comment_row).merge(True)
        except Exception:
            pass
    last_row = _sheet_last_used_row(sheet, 30)
    if last_row < 0:
        last_row = 0
    _param_apply_range_borders(sheet, 0, 0, max_col, last_row)
    _param_set_column_widths(sheet, max_col)
    if doc is not None:
        _param_autofit_row_heights(doc, sheet, 0, last_row, max_col)

def _validation_list_formula_quoted(items):
    """Inline-список для Calc: "A";"B";"C"."""
    parts = []
    for it in items or []:
        s = unicode(it).strip()
        if s == u'':
            continue
        s = s.replace(u'"', u'""')
        parts.append(u'"%s"' % s)
    return u';'.join(parts)

def _param_dv_ensure_sheet(doc):
    if doc is None:
        return None
    try:
        sheets = doc.getSheets()
        if sheets.hasByName(_pw_cfg._PARAM_DV_SHEET_NAME):
            sh = sheets.getByName(_pw_cfg._PARAM_DV_SHEET_NAME)
        else:
            sh = sheets.insertNewByName(_pw_cfg._PARAM_DV_SHEET_NAME, sheets.getCount())
        try:
            sh.setPropertyValue('IsVisible', False)
        except Exception:
            try:
                from com.sun.star.sheet.SheetVisibility import VERY_HIDDEN
                sh.setPropertyValue('SheetState', VERY_HIDDEN)
            except Exception:
                pass
        return sh
    except Exception as err:
        print(u'param_wizard: лист списков валидации: %s' % err)
        return None

def _param_dv_reset(doc):
    _pw_cfg._PARAM_DV_LIST_CACHE = {}
    _pw_cfg._PARAM_DV_NEXT_COL = 0
    sh = _param_dv_ensure_sheet(doc)
    if sh is None:
        return
    try:
        sh.getCellRangeByPosition(0, 0, 255, 999).clearContents(7)
    except Exception:
        pass

def _param_dv_list_formula(doc, items):
    """
    Формула списка для TableValidation: короткий inline или ссылка на скрытый лист.
    """
    clean = []
    for it in items or []:
        s = unicode(it).strip()
        if s != u'':
            clean.append(s)
    if len(clean) == 0:
        return u''
    key = tuple(clean)
    if key in _pw_cfg._PARAM_DV_LIST_CACHE:
        return _pw_cfg._PARAM_DV_LIST_CACHE[key]
    inline = _validation_list_formula_quoted(clean)
    if len(inline) <= _pw_cfg._PARAM_DV_INLINE_MAX:
        _pw_cfg._PARAM_DV_LIST_CACHE[key] = inline
        return inline
    sh = _param_dv_ensure_sheet(doc)
    if sh is None:
        if inline:
            _pw_cfg._PARAM_DV_LIST_CACHE[key] = inline
            return inline
        return u''
    col = _pw_cfg._PARAM_DV_NEXT_COL
    _pw_cfg._PARAM_DV_NEXT_COL = _pw_cfg._PARAM_DV_NEXT_COL + 1
    row_i = 0
    while row_i < len(clean):
        sh.getCellByPosition(col, row_i).String = clean[row_i]
        row_i = row_i + 1
    try:
        rng = sh.getCellRangeByPosition(col, 0, col, len(clean) - 1)
        formula = rng.AbsoluteName
    except Exception:
        formula = inline
    _pw_cfg._PARAM_DV_LIST_CACHE[key] = formula
    return formula

def _set_cell_list_validation(cell, doc, items):
    if cell is None:
        return
    formula = _param_dv_list_formula(doc, items)
    if formula is None or unicode(formula).strip() == u'':
        return
    try:
        from com.sun.star.sheet.ValidationType import LIST as VALIDATION_LIST
    except Exception:
        VALIDATION_LIST = 6
    try:
        from com.sun.star.sheet.ConditionOperator import EQUAL
    except Exception:
        EQUAL = 0
    try:
        val = cell.Validation
    except Exception:
        val = None
    if val is None:
        try:
            val = uno.createUnoStruct('com.sun.star.sheet.TableValidation')
        except Exception:
            try:
                val = uno.createUnoStruct('com.sun.star.table.TableValidation')
            except Exception:
                return
    try:
        val.Type = VALIDATION_LIST
        try:
            val.setOperator(EQUAL)
        except Exception:
            val.Operator = EQUAL
        try:
            val.setFormula1(unicode(formula))
        except Exception:
            val.Formula1 = unicode(formula)
        try:
            val.IgnoreBlankCells = True
        except Exception:
            val.IgnoreBlank = True
        # ShowList: 0=скрыть, 1=без сортировки, 2=по возрастанию
        # (com.sun.star.sheet.TableValidationVisibility.SORTEDASCENDING)
        try:
            from com.sun.star.sheet.TableValidationVisibility import SORTEDASCENDING as _DV_SHOW_SORTED
            val.ShowList = _DV_SHOW_SORTED
        except Exception:
            try:
                val.ShowList = 2
            except Exception:
                try:
                    val.ShowList = True
                except Exception:
                    pass
        val.ShowErrorMessage = False
        val.ShowInputMessage = False
        try:
            cell.setPropertyValue('Validation', val)
        except Exception:
            cell.Validation = val
    except Exception as err:
        print(u'param_wizard: валидация ячейки: %s' % err)

def _apply_param_row_validations(sheet, row, catalog, spec=None, doc=None):
    """Выпадающие списки для одной строки: A — имена параметров, B… — choices."""
    if sheet is None or row is None or int(row) < 1 or (catalog is None):
        return
    row = int(row)
    names = _catalog_param_names(catalog)
    if len(names) > 0:
        _set_cell_list_validation(sheet.getCellByPosition(0, row), doc, names)
    if spec is None:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if name != u'':
            spec = _find_catalog_spec(catalog, name)
    if spec is None:
        return
    choices = spec.get('choices') or []
    if len(choices) > 0:
        ncol = int(spec.get('choices_columns', 1) or 1)
        if ncol < 1:
            ncol = 1
        ci = 0
        while ci < ncol:
            _set_cell_list_validation(sheet.getCellByPosition(1 + ci, row), doc, choices)
            ci = ci + 1
    # «Режим»: колонка C — способ переноса (отдельный список от B).
    if _spec_has_inline_transfer(spec):
        transfer_choices = spec.get('transfer_choices') or _transfer_wizard_choices(catalog)
        if len(transfer_choices) > 0:
            _set_cell_list_validation(sheet.getCellByPosition(2, row), doc, transfer_choices)

def _apply_param_sheet_validations(sheet, catalog, last_row=None, extra_empty_rows=3, doc=None):
    """
    Выпадающие списки на листе параметров: колонка A и choice-колонки B…
    для всех используемых строк и нескольких пустых строк внизу.
    """
    if sheet is None or catalog is None:
        return
    with _pw_timed(u'apply_param_sheet_validations'):
        if doc is not None:
            with _pw_timed(u'param_dv_reset'):
                _param_dv_reset(doc)
        if last_row is None:
            last_row = _sheet_last_used_row(sheet, 30)
        if last_row < 1:
            last_row = 1
        end_row = last_row + int(extra_empty_rows or 0)
        max_end = _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS - 1
        if end_row > max_end:
            end_row = max_end
        row_idx = 1
        while row_idx <= end_row:
            name = _cell_string(sheet.getCellByPosition(0, row_idx))
            spec = _find_catalog_spec(catalog, name) if name != u'' else None
            _apply_param_row_validations(sheet, row_idx, catalog, spec, doc=doc)
            row_idx = row_idx + 1
        if _pw_cfg.PARAM_WIZARD_TIMING:
            _pw_time_log(u'  validations rows: 1..%d' % end_row)

def _copy_param_row_format(sheet, src_row, dst_row, last_col):
    if sheet is None or src_row < 0 or dst_row < 0 or (src_row == dst_row):
        return False
    try:
        src = sheet.getCellRangeByPosition(0, src_row, last_col, src_row)
        dst = sheet.getCellRangeByPosition(0, dst_row, last_col, dst_row)
        if src is None or dst is None:
            return False
        try:
            from com.sun.star.sheet.CellCopyFlags import STYLES, VALIDATION, NUMBER_FORMAT, BORDER, CHARACTER_ATTR
            flags = STYLES | VALIDATION | NUMBER_FORMAT | BORDER | CHARACTER_ATTR
            src.copy(dst, flags)
            return True
        except Exception:
            pass
        try:
            src.copy(dst, 65535)
            return True
        except Exception:
            pass
    except Exception:
        pass
    return False

def _apply_param_sheet_used_area_format(sheet):
    """PT Sans 11pt, выравнивание по центру — на весь значащий диапазон листа (одним блоком)."""
    if sheet is None:
        return
    with _pw_timed(u'apply_param_sheet_used_area_format (диапазон)'):
        end_row = _sheet_last_used_row(sheet, _pw_cfg.MERGE_PARAM_SHEET_MAX_ROWS - 1)
        if end_row < 0:
            return
        end_col = _param_sheet_max_value_col(sheet)
        if _pw_cfg.PARAM_WIZARD_TIMING:
            _pw_time_log(u'  used area: 0..%d x 0..%d' % (end_col, end_row))
        try:
            rng = sheet.getCellRangeByPosition(0, 0, int(end_col), int(end_row))
            rng.CharFontName = _pw_cfg._PARAM_FONT_NAME
            rng.CharHeight = _pw_cfg._PARAM_FONT_SIZE
            rng.IsTextWrapped = True
            try:
                from com.sun.star.table.CellHoriJustify import CENTER
                from com.sun.star.table.CellVertJustify2 import CENTER as VCENTER
                rng.HoriJustify = CENTER
                rng.VertJustify = VCENTER
            except Exception:
                pass
        except Exception:
            pass

def _ensure_param_row_formatting(sheet, row, catalog, spec, needs_shell, doc=None):
    """Копия формата/валидации с последней строки таблицы для новой строки параметров."""
    if sheet is None or row < 0:
        return
    # JSON-ВПР — не раздувать строку до 5 столбцов «Значение N».
    if spec is not None and spec.get('mode') == 'vlookup':
        try:
            max_col = max(2, int(_param_sheet_header_value_max_col(sheet, max_scan=40, fallback=2) or 2))
        except Exception:
            max_col = 2
    else:
        max_col = _pw_cfg._PARAM_VALUE_COLUMNS
    if needs_shell:
        src = _find_param_format_source_row(sheet, before_row=row)
        if src >= 0 and src != row:
            last_col = max(_param_sheet_row_last_col(sheet, src), max_col)
            _copy_param_row_format(sheet, src, row, last_col)
        name = _cell_string(sheet.getCellByPosition(0, row))
        if name != u'':
            _param_style_name_cell(sheet.getCellByPosition(0, row))
            _param_write_hint_annotation(sheet.getCellByPosition(0, row), _param_sheet_hint(name))
        col = 1
        while col <= max_col:
            _param_style_value_cell(sheet.getCellByPosition(col, row))
            col = col + 1
        col = 0
        while col <= max_col:
            _param_set_cell_borders(sheet.getCellByPosition(col, row))
            col = col + 1
    row_name = _cell_string(sheet.getCellByPosition(0, row))
    col = 0
    while col <= max_col:
        cell = sheet.getCellByPosition(col, row)
        if _param_sheet_name_is_disabled(row_name):
            _param_set_cell_disabled_fill(cell)
        elif col >= 1:
            _param_clear_cell_background(cell)
        col = col + 1
    _apply_param_row_validations(sheet, row, catalog, spec, doc=doc)

def _format_rest_hint(rest_hints, key):
    if not rest_hints or key is None or unicode(key).strip() == u'':
        return u''
    item = _rest_hint_lookup(rest_hints, key)
    if item is None:
        return u''
    if isinstance(item, (tuple, list)) and len(item) >= 1:
        desc = unicode(item[0]).strip()
        example = u''
        if len(item) > 1:
            example = unicode(item[1]).strip()
        if example != u'':
            return u'%s\nПример C: %s' % (desc, example)
        return desc
    return unicode(item)

def _format_selected_b_detail(spec, selected_b):
    """Описание выбранного значения колонки B."""
    if spec is None or unicode(selected_b).strip() == u'':
        return u''
    mode = spec.get('mode', 'text')
    key = unicode(selected_b).strip()
    lines = [u'── Выбрано в колонке B: «%s» ──' % key]
    if mode in ('postprocess_range', 'postprocess_row'):
        rest = spec.get('rest_hints') or {}
        item = _rest_hint_lookup(rest, key)
        if item is None:
            fb = _pw_cfg._FALLBACK_PP_RANGE_REST_HINTS if mode == 'postprocess_range' else _pw_cfg._FALLBACK_PP_ROW_REST_HINTS
            item = _rest_hint_lookup(fb, key)
        if item is None:
            lines.append(u'Функция не найдена в каталоге макроса.')
        else:
            desc = unicode(item[0]).strip() if len(item) > 0 else u''
            example = unicode(item[1]).strip() if len(item) > 1 else u''
            if desc in (u'', u'не используется') or u'не используется' in desc:
                lines.append(u'Колонка C: не обязательна (можно оставить пустой).')
            else:
                lines.append(u'Колонка C: %s' % desc)
            if example != u'':
                lines.append(u'Пример C: %s' % example)
    elif mode == 'choice':
        vh = _pw_cfg.VALUE_HINTS.get(key, u'')
        if vh != u'':
            lines.append(vh)
    return u'\n'.join(lines)

def _format_choices_catalog(spec, max_items=35):
    """Список допустимых значений колонки B с пояснениями."""
    choices = spec.get('choices') or []
    if len(choices) == 0:
        return u''
    mode = spec.get('mode', 'text')
    rest = spec.get('rest_hints') or {}
    lines = [u'Доступные значения колонки B (%d):' % len(choices)]
    shown = 0
    i = 0
    while i < len(choices) and shown < max_items:
        key = unicode(choices[i])
        line = u'  • ' + key
        if mode in ('postprocess_range', 'postprocess_row'):
            item = _rest_hint_lookup(rest, key)
            if item and len(item) > 0:
                desc = unicode(item[0]).strip()
                if desc and desc != u'не используется' and (u'не используется' not in desc):
                    line = line + u' — C: ' + desc
                if len(item) > 1 and unicode(item[1]).strip() != u'':
                    line = line + u' (пр. C: %s)' % unicode(item[1]).strip()
        elif mode == 'choice':
            vh = _pw_cfg.VALUE_HINTS.get(key, u'')
            if vh:
                line = line + u' — ' + unicode(vh).strip()
        lines.append(line)
        shown = shown + 1
        i = i + 1
    if len(choices) > shown:
        lines.append(u'  … и ещё %d' % (len(choices) - shown))
    return u'\n'.join(lines)

def _build_wizard_description(spec, sheet, selected_b=u''):
    """Полное описание параметра для поля «Описание»."""
    if spec is None:
        return u''
    blocks = []
    detail = u''
    if unicode(selected_b).strip() != u'':
        detail = _format_selected_b_detail(spec, selected_b)
        if detail != u'':
            blocks.append(detail)
    base = spec.get('hint', u'')
    if base != u'':
        if detail != u'':
            blocks.append(_pw_cfg._DESC_GENERAL_INFO_SEPARATOR)
        blocks.append(base)
    catalog = _format_choices_catalog(spec)
    if catalog != u'':
        blocks.append(catalog)
    summary = _current_value_summary(sheet, spec)
    if summary != u'':
        blocks.append(summary)
    return u'\n\n'.join(blocks)

def _current_value_summary(sheet, spec):
    name = spec['name']
    mode = spec.get('mode', 'text')
    if spec.get('multi_row'):
        return u''
    row = _find_param_row(sheet, name)
    if row < 0:
        return u''
    if mode == 'files' or spec.get('multi_column'):
        vals = _row_values(sheet, row)
        if len(vals) == 0:
            return u''
        return u'Текущие значения: ' + u'; '.join(vals)
    vals = _row_values(sheet, row)
    if len(vals) == 0:
        return u''
    return u'Текущее значение: ' + vals[0]

def _find_param_last_row(sheet, param_name):
    """Последняя строка с данным именем в A (для повторяемых параметров)."""
    end_row = _param_sheet_scan_end_row(sheet)
    row = 0
    last = -1
    while row <= end_row:
        name = _cell_string(sheet.getCellByPosition(0, row))
        if row == 0 and _param_match(name, u'Параметр'):
            row = row + 1
            continue
        if name == u'':
            row = row + 1
            continue
        if _param_match(name, param_name):
            last = row
        row = row + 1
    return last

def _read_primary_value(sheet, spec):
    if spec.get('mode') == 'files':
        return _read_files_paths_text(sheet, spec)
    if spec.get('multi_row'):
        row = _find_param_last_row(sheet, spec['name'])
    else:
        row = _find_param_row(sheet, spec['name'])
    if row < 0:
        return u''
    vals = _row_values(sheet, row)
    if len(vals) == 0:
        return u''
    return vals[0]

def _read_extra_value(sheet, spec):
    if not spec.get('multi_row'):
        row = _find_param_row(sheet, spec['name'])
    else:
        row = _find_param_last_row(sheet, spec['name'])
    if row < 0:
        return u''
    mode = spec.get('mode', 'text')
    if mode in ('postprocess_range', 'postprocess_row'):
        _primary, _pref, extra = _read_pp_row_values(sheet, row)
        return extra
    return _cell_string(sheet.getCellByPosition(2, row))

def _validate_primary_value(spec, primary):
    mode = spec.get('mode', 'text')
    if mode == 'source_extra':
        return (True, u'')
    if mode == 'pre_shell':
        return (True, u'')
    if spec.get('col_c_subdialog'):
        return (True, u'')
    if mode == 'vlookup':
        return (True, u'')
    if mode in ('merge_sheets', 'split_sheets'):
        return (True, u'')
    if mode == 'number':
        if primary == u'':
            return (True, u'')
        try:
            int(primary)
            return (True, u'')
        except Exception:
            return (False, u'Ожидается целое число.')
    if mode == 'choice':
        choices = spec.get('choices') or []
        if primary != u'' and len(choices) > 0 and (primary not in choices):
            return (False, u'Значение не из списка. Допустимо: %s' % u', '.join(choices[:8]))
    if mode in ('postprocess_range', 'postprocess_row'):
        choices = spec.get('choices') or []
        if primary == u'':
            return (False, u'Выберите функцию постобработки (колонка B).')
        if _pp_is_plugin_primary(primary):
            return (True, u'')
        if len(choices) > 0:
            primary_cf = unicode(primary).strip().casefold()
            in_list = False
            i = 0
            while i < len(choices):
                if unicode(choices[i]).strip().casefold() == primary_cf:
                    in_list = True
                    break
                i = i + 1
            if not in_list and (not _pp_allows_freeform_b(primary)):
                try:
                    if _is_sheet_block_form_fn(primary):
                        in_list = True
                except Exception:
                    pass
            if not in_list and (not _pp_allows_freeform_b(primary)):
                return (False, u'Функция не из списка. Выберите ключ или «функция_плагин».')
    return (True, u'')

def _validate_plugin_ref(spec, primary, plugin_ref):
    if not _pp_is_plugin_primary(primary):
        return (True, u'')
    ref = unicode(plugin_ref or u'').strip()
    if ref == u'':
        return (False, u'Укажите ссылку или код в колонке C (кнопка «Редактор…»).')
    if _pp_is_plugin_json_c(ref):
        return (True, u'')
    if not _pp_allows_freeform_c(ref):
        return (False, u'Некорректная ссылка или код: functions_*.py#имя, lambda или def.')
    return (True, u'')

def apply_param_value(sheet, spec, primary, extra=None, target_row=None, target_col=None, catalog=None, doc=None, plugin_ref=None):
    if sheet is None:
        return False
    _param_sheet_begin_write(sheet)
    try:
        return _apply_param_value_unlocked(
            sheet, spec, primary, extra=extra, target_row=target_row, target_col=target_col,
            catalog=catalog, doc=doc, plugin_ref=plugin_ref,
        )
    finally:
        _param_sheet_end_write(sheet)

def _apply_param_value_unlocked(sheet, spec, primary, extra=None, target_row=None, target_col=None, catalog=None, doc=None, plugin_ref=None):
    name = spec['name']
    mode = spec.get('mode', 'text')
    if mode == 'vlookup':
        if not isinstance(primary, dict):
            primary = {}
        if primary.get('save_as_json'):
            json_c = unicode(primary.get('json_c') or u'').strip()

            def _write_vlookup_json_row(row):
                # JSON только в C; не раздувать шапку до «Значение 3..5».
                ci = 1
                while ci <= 5:
                    try:
                        sheet.getCellByPosition(ci, row).String = u''
                    except Exception:
                        pass
                    ci = ci + 1
                sheet.getCellByPosition(2, row).String = json_c
                _ensure_vlookup_json_param_headers(sheet)
                _ensure_vlookup_json_param_formats(sheet)
                return row
            if target_row is not None and int(target_row) >= 0:
                tr = int(target_row)
                rname = _row_param_name(sheet, tr)
                if rname == u'' or _param_row_matches_name(rname, name):
                    needs_shell = rname == u''
                    if rname == u'':
                        sheet.getCellByPosition(0, tr).String = name
                    row = _write_vlookup_json_row(tr)
                    _ensure_param_row_formatting(sheet, row, catalog, spec, needs_shell, doc=doc)
                    return row
            row = _first_empty_row(sheet)
            sheet.getCellByPosition(0, row).String = name
            row = _write_vlookup_json_row(row)
            _ensure_param_row_formatting(sheet, row, catalog, spec, True, doc=doc)
            return row
        left_b = primary.get('left_b', u'')
        right_c = primary.get('right_c', u'')
        keys_d = primary.get('keys_d', u'')
        extract_e = primary.get('extract_e', u'')
        color_f = primary.get('color_f', u'')

        def _write_vlookup_row(row):
            sheet.getCellByPosition(1, row).String = left_b
            sheet.getCellByPosition(2, row).String = right_c
            sheet.getCellByPosition(3, row).String = keys_d
            sheet.getCellByPosition(4, row).String = extract_e
            sheet.getCellByPosition(5, row).String = color_f
            _ensure_vlookup_param_column_headers(sheet)
            _ensure_vlookup_param_column_formats(sheet)
            _write_vlookup_cell_hints(sheet, row)
            return row
        if target_row is not None and int(target_row) >= 0:
            tr = int(target_row)
            rname = _row_param_name(sheet, tr)
            if rname == u'' or _param_row_matches_name(rname, name):
                needs_shell = rname == u''
                if rname == u'':
                    sheet.getCellByPosition(0, tr).String = name
                row = _write_vlookup_row(tr)
                _ensure_param_row_formatting(sheet, row, catalog, spec, needs_shell, doc=doc)
                return row
        row = _first_empty_row(sheet)
        sheet.getCellByPosition(0, row).String = name
        row = _write_vlookup_row(row)
        _ensure_param_row_formatting(sheet, row, catalog, spec, True, doc=doc)
        return row
    if mode in ('merge_sheets', 'split_sheets'):
        if isinstance(primary, dict):
            json_c = unicode(primary.get('json_c') or u'').strip()
        else:
            json_c = unicode(primary or u'').strip()

        def _write_splitter_json_row(row):
            ci = 1
            while ci <= 5:
                sheet.getCellByPosition(ci, row).String = u''
                ci = ci + 1
            sheet.getCellByPosition(2, row).String = json_c
            return row
        if target_row is not None and int(target_row) >= 0:
            tr = int(target_row)
            rname = _row_param_name(sheet, tr)
            if rname == u'' or _param_row_matches_name(rname, name):
                needs_shell = rname == u''
                if rname == u'':
                    sheet.getCellByPosition(0, tr).String = name
                row = _write_splitter_json_row(tr)
                _ensure_param_row_formatting(sheet, row, catalog, spec, needs_shell, doc=doc)
                return row
        row = _first_empty_row(sheet)
        sheet.getCellByPosition(0, row).String = name
        row = _write_splitter_json_row(row)
        _ensure_param_row_formatting(sheet, row, catalog, spec, True, doc=doc)
        return row
    if mode == 'files':
        paths, _fd = _split_files_path_text(primary)
        if target_row is not None and int(target_row) >= 0:
            tr = int(target_row)
            rname = _row_param_name(sheet, tr)
            if rname == u'' or _param_row_matches_name(rname, name):
                if rname == u'':
                    sheet.getCellByPosition(0, tr).String = name
                return _apply_files_paths_to_row(doc, sheet, tr, paths, catalog, spec)
        row = _find_param_row(sheet, name)
        if row < 0:
            row = _first_empty_row(sheet)
            sheet.getCellByPosition(0, row).String = name
        return _apply_files_paths_to_row(doc, sheet, row, paths, catalog, spec)
    if mode == 'source_extra':
        # Значения B/C/D… пишет субвизард; здесь только имя строки в A.
        if target_row is not None and int(target_row) >= 0:
            tr = int(target_row)
            rname = _row_param_name(sheet, tr)
            needs_shell = rname == u''
            if rname == u'' or _param_row_matches_name(rname, name):
                if rname == u'':
                    sheet.getCellByPosition(0, tr).String = name
                _ensure_param_row_formatting(sheet, tr, catalog, spec, needs_shell, doc=doc)
                return tr
        row = _find_param_row(sheet, name)
        if row < 0:
            row = _first_empty_row(sheet)
            sheet.getCellByPosition(0, row).String = name
            _ensure_param_row_formatting(sheet, row, catalog, spec, True, doc=doc)
        return row
    def _write_values_to_row(row):
        if spec.get('col_c_subdialog'):
            if _spec_col_c_keeps_b(spec) or spec.get('mode') == 'choice':
                sheet.getCellByPosition(1, row).String = unicode(primary or u'').strip()
            else:
                sheet.getCellByPosition(1, row).String = _pw_cfg._PARAM_B_SEE_COLUMN_C
            sheet.getCellByPosition(2, row).String = unicode(extra or u'').strip() if extra is not None else u''
            return (row, 1)
        if spec.get('multi_column'):
            col = -1
            if target_col is not None and int(target_col) >= 1:
                col = int(target_col)
            if col < 1:
                col = _first_empty_value_col(sheet, row)
            if col < 1:
                col = 1
            sheet.getCellByPosition(col, row).String = primary
            return (row, col)
        if mode in ('postprocess_range', 'postprocess_row'):
            sheet.getCellByPosition(1, row).String = primary
            if _pp_is_plugin_primary(primary):
                sheet.getCellByPosition(2, row).String = unicode(plugin_ref or u'').strip()
                sheet.getCellByPosition(3, row).String = unicode(extra or u'').strip() if extra is not None else u''
            else:
                if extra is not None:
                    c_val = unicode(extra).strip()
                    if _is_pivot_table_pp_name(primary):
                        c_val = _pivot_canonical_storage_json(c_val) or c_val
                    sheet.getCellByPosition(2, row).String = c_val
                sheet.getCellByPosition(3, row).String = u''
            return (row, 1)
        if mode == 'choice' and _spec_has_inline_transfer(spec) and (extra is not None):
            sheet.getCellByPosition(1, row).String = primary
            sheet.getCellByPosition(2, row).String = extra
            return (row, 1)
        sheet.getCellByPosition(1, row).String = primary
        return (row, 1)

    def _finish_row(row, needs_shell):
        _ensure_param_row_formatting(sheet, row, catalog, spec, needs_shell, doc=doc)
        return row
    if target_row is not None and int(target_row) >= 0:
        tr = int(target_row)
        rname = _row_param_name(sheet, tr)
        if rname == u'' or _param_row_matches_name(rname, name):
            needs_shell = rname == u''
            if rname == u'':
                sheet.getCellByPosition(0, tr).String = name
            row, _col = _write_values_to_row(tr)
            return _finish_row(row, needs_shell)
    if spec.get('multi_row'):
        row = _first_empty_row(sheet)
        sheet.getCellByPosition(0, row).String = name
        sheet.getCellByPosition(1, row).String = primary
        if _pp_is_plugin_primary(primary):
            sheet.getCellByPosition(2, row).String = unicode(plugin_ref or u'').strip()
            if extra is not None:
                sheet.getCellByPosition(3, row).String = extra
        elif extra is not None:
            sheet.getCellByPosition(2, row).String = extra
        return _finish_row(row, True)
    if spec.get('multi_column'):
        row = _find_param_row(sheet, name)
        needs_shell = False
        if row < 0:
            row = _first_empty_row(sheet)
            sheet.getCellByPosition(0, row).String = name
            needs_shell = True
        col = _first_empty_value_col(sheet, row)
        if col < 0:
            col = 1
        sheet.getCellByPosition(col, row).String = primary
        return _finish_row(row, needs_shell)
    row = _find_param_row(sheet, name)
    needs_shell = False
    if row < 0:
        row = _first_empty_row(sheet)
        sheet.getCellByPosition(0, row).String = name
        needs_shell = True
    if spec.get('col_c_subdialog'):
        row, _col = _write_values_to_row(row)
        return _finish_row(row, needs_shell)
    sheet.getCellByPosition(1, row).String = primary
    if _pp_is_plugin_primary(primary):
        sheet.getCellByPosition(2, row).String = unicode(plugin_ref or u'').strip()
        if extra is not None:
            sheet.getCellByPosition(3, row).String = extra
    elif extra is not None and (mode in ('postprocess_range', 'postprocess_row') or (mode == 'choice' and _spec_has_inline_transfer(spec))):
        sheet.getCellByPosition(2, row).String = extra
    return _finish_row(row, needs_shell)

def _clear_param_sheet_row(sheet, row, catalog=None, doc=None):
    """Очистить строку параметра (имя и значения), не трогая заголовок листа."""
    if sheet is None or row is None or int(row) < 0:
        return False
    row = int(row)
    if row == 0:
        hdr = _row_param_name(sheet, 0)
        if hdr == u'' or _param_match(hdr, u'Параметр'):
            return False
    _param_sheet_begin_write(sheet)
    try:
        max_col = _param_sheet_max_value_col(sheet)
        try:
            sheet.getCellRangeByPosition(0, row, max_col, row).clearContents(7)
        except Exception:
            col = 0
            while col <= max_col:
                try:
                    sheet.getCellByPosition(col, row).setString(u'')
                except Exception:
                    pass
                col = col + 1
        if catalog is not None:
            last_row = max(int(row), _sheet_last_used_row(sheet, int(row)))
            _apply_param_sheet_validations(sheet, catalog, last_row, extra_empty_rows=3, doc=doc)
            _apply_param_sheet_used_area_format(sheet)
        return True
    finally:
        _param_sheet_end_write(sheet)

def _param_wizard_select_row(doc, sheet, row):
    try:
        ctrl = doc.getCurrentController()
        if ctrl is not None:
            ctrl.setActiveSheet(sheet)
            ctrl.select(sheet.getCellRangeByPosition(0, int(row), 1, int(row)))
    except Exception:
        pass

def _param_wizard_post_save_row(doc, sheet, catalog, spec, row):
    """Валидация и авто-высота одной строки после сохранения."""
    _param_sheet_begin_write(sheet)
    try:
        with _pw_timed(u'param_wizard_post_save_row row=%d' % int(row)):
            last_col = _param_row_max_col(sheet, int(row), catalog)
            with _pw_timed(u'apply_param_row_validations'):
                _apply_param_row_validations(sheet, int(row), catalog, spec, doc=doc)
            with _pw_timed(u'param_autofit_row_heights (строка)'):
                _param_autofit_row_heights(doc, sheet, int(row), int(row), last_col)
    finally:
        _param_sheet_end_write(sheet)

def _param_wizard_post_save_full(doc, sheet, catalog, spec, row):
    """Полное обновление оформления и списков всего листа параметров."""
    _param_sheet_begin_write(sheet)
    try:
        _param_wizard_post_save_full_unlocked(doc, sheet, catalog, spec, row)
    finally:
        _param_sheet_end_write(sheet)

def _param_wizard_post_save_full_unlocked(doc, sheet, catalog, spec, row):
    with _pw_timed(u'param_wizard_post_save_full'):
        with _pw_timed(u'remove_empty_name_rows'):
            _param_sheet_remove_empty_name_rows(sheet)
        last_col = _param_sheet_max_value_col(sheet)
        last_row = max(int(row), _sheet_last_used_row(sheet, int(row)))
        with _pw_timed(u'apply_param_sheet_validations end_row=%d' % (last_row + 3)):
            _apply_param_sheet_validations(sheet, catalog, last_row, extra_empty_rows=3, doc=doc)
        with _pw_timed(u'apply_param_sheet_used_area_format'):
            _apply_param_sheet_used_area_format(sheet)
        with _pw_timed(u'param_apply_disabled_rows_styles'):
            _param_apply_disabled_rows_styles(sheet, catalog)
        with _pw_timed(u'param_autofit_row_heights (лист)'):
            _param_autofit_row_heights(doc, sheet, 0, last_row, last_col)

def _param_wizard_post_save(doc, sheet, catalog, spec, row, refresh_full_sheet=False):
    """После сохранения параметра: одна строка или весь лист (по галочке на форме)."""
    with _pw_timed(u'param_wizard_post_save row=%d param=%s full=%s' % (int(row), spec.get('name', u'?'), refresh_full_sheet)):
        if refresh_full_sheet:
            _param_wizard_post_save_full(doc, sheet, catalog, spec, row)
        else:
            _param_wizard_post_save_row(doc, sheet, catalog, spec, row)
        with _pw_timed(u'controller select row'):
            _param_wizard_select_row(doc, sheet, row)

def _show_message(message, title=u'Параметры', dialog=None, doc=None):
    text = unicode(message)
    if _wp_soft_gray_info_box(text, title=title, parent_dialog=dialog, doc=doc):
        return
    if _wp_message_box_execute(doc, dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, text) is not None:
        return
    try:
        cw = _try_import_collect()
        if cw is not None and doc is not None:
            cw.show_message(message, doc)
            return
    except Exception:
        pass
    try:
        toolkit = XSCRIPTCONTEXT.getDesktop().getToolkit()
        parent = None
        if dialog is not None:
            try:
                parent = dialog.getPeer()
            except Exception:
                pass
        if parent is None:
            parent = XSCRIPTCONTEXT.getDesktop().getCurrentFrame().getContainerWindow()
        box = toolkit.createMessageBox(parent, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, text)
        box.execute()
    except Exception:
        print(text)

def _show_file_picker():
    return _show_file_picker_with_initial(u'')

def _try_import_pick_source():
    if _pw_cfg._PICK_SOURCE is False:
        return None
    if _pw_cfg._PICK_SOURCE is None:
        try:
            here = os.path.dirname(os.path.abspath(__file__))
            if here not in sys.path:
                sys.path.insert(0, here)
            import pick_source_file as psf
            _pw_cfg._PICK_SOURCE = psf
        except Exception:
            _pw_cfg._PICK_SOURCE = False
    return _pw_cfg._PICK_SOURCE if _pw_cfg._PICK_SOURCE is not False else None

def _split_files_path_text(text):
    t = unicode(text).strip()
    if t == u'':
        return ([], u';')
    if u';' in t:
        delim = u';'
        raw = t.split(u';')
    elif u',' in t:
        delim = u','
        raw = t.split(u',')
    else:
        return ([t], u';')
    parts = []
    i = 0
    while i < len(raw):
        p = unicode(raw[i]).strip()
        if p != u'':
            parts.append(p)
        i = i + 1
    return (parts, delim)

def _join_files_path_text(parts, delim):
    if delim == u',':
        return u','.join([unicode(p) for p in parts])
    if len(parts) == 0:
        return u''
    return u'; '.join([unicode(p) for p in parts])

def _files_picker_initial(path_str):
    home = os.path.expanduser('~')
    if path_str is None or unicode(path_str).strip() == u'':
        return (home, u'')
    p = os.path.normpath(unicode(path_str).strip())
    name = os.path.basename(p)
    if name in (u'', u'.'):
        name = u''
    d = os.path.dirname(p)
    if d == u'':
        d = home
    elif not os.path.isdir(d):
        abs_d = os.path.dirname(os.path.abspath(p))
        if abs_d != u'' and os.path.isdir(abs_d):
            d = abs_d
        elif os.path.isdir(os.path.abspath(p)):
            d = os.path.abspath(p)
            name = u''
        else:
            d = home
    if os.path.isfile(p):
        d = os.path.dirname(os.path.abspath(p))
        name = os.path.basename(p)
    return (d, name)

def _normalize_files_source_path(doc, path):
    if path is None or unicode(path).strip() == u'':
        return path
    cw = _try_import_collect()
    if cw is None:
        return path
    doc_path = u''
    if doc is not None:
        try:
            doc_path = cw._merge_doc_system_path(doc)
        except Exception:
            doc_path = u''
    try:
        return unicode(cw.normalize_source_path_cell_value(unicode(path), doc_path))
    except Exception:
        return path

def _show_file_picker_with_initial(path_str, doc=None):
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        picker = sm.createInstanceWithContext('com.sun.star.ui.dialogs.FilePicker', ctx)
        picker.setTitle(u'Выбор файла-источника')
        start_dir, start_name = _files_picker_initial(path_str)
        dir_url = None
        try:
            abs_dir = os.path.abspath(unicode(start_dir).strip())
            if os.path.isdir(abs_dir):
                dir_url = uno.systemPathToFileUrl(abs_dir)
        except Exception:
            dir_url = None
        if dir_url is not None:
            try:
                picker.setDisplayDirectory(dir_url)
            except Exception:
                pass
        if start_name != u'':
            try:
                picker.setDefaultName(start_name)
            except Exception:
                pass
        if picker.execute() != 1:
            return None
        urls = picker.getFiles()
        if urls is None or len(urls) == 0:
            return None
        return _normalize_files_source_path(doc, os.path.abspath(uno.fileUrlToSystemPath(urls[0])))
    except Exception as e:
        print(u'Ошибка FilePicker: %s' % e)
        return None

def _wp_show_folder_picker(initial_dir=None):
    """Выбор папки (FolderPicker). Возвращает абсолютный путь или None."""
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        picker = sm.createInstanceWithContext('com.sun.star.ui.dialogs.FolderPicker', ctx)
        start = unicode(initial_dir or u'').strip()
        if start != u'':
            try:
                start = os.path.expanduser(os.path.expandvars(start))
            except Exception:
                pass
        if start == u'' or not os.path.isdir(start):
            start = os.path.expanduser('~')
        try:
            start_url = uno.systemPathToFileUrl(os.path.abspath(start))
            picker.setDisplayDirectory(start_url)
        except Exception:
            pass
        if int(picker.execute()) != 1:
            return None
        return os.path.abspath(uno.fileUrlToSystemPath(picker.getDirectory()))
    except Exception as e:
        print(u'Ошибка FolderPicker: %s' % e)
        return None

