    def _preview(val):
        s = unicode(val if val is not None else u'')
        if len(s) > 48:
            return s[:48] + u'…'
        return s

    def _list_labels():
        out = []
        for x in state['items']:
            mark = u' [шифр]' if bool(x.get('encrypt')) else u''
            out.append(u'%s = %s%s' % (unicode(x.get('name') or u'?'), _preview(x.get('value')), mark))
