def _inner_grid_list_height(dh, list_top_y, m=10, min_h=72):
    """Высота списков: вплотную до панели лист/ключи, затем до футера OK."""
    footer_y = _inner_dialog_footer_y(dh, m)
    avail = footer_y - list_top_y - _pw_cfg._INNER_GRID_LIST_GAP - _pw_cfg._INNER_GRID_CONTROLS_H - _pw_cfg._INNER_GRID_LIST_GAP
    return max(min_h, avail)

