def _wire_source_extra_help_button(dlg, parent_dialog=None, kind=u'book', doc=None):
    """Подключить кнопку HelpButton → справка source-extra (совместимость)."""
    title = getattr(_pw_cfg, '_SOURCE_EXTRA_HELP_TITLE', None) or u'Справка — доп. параметры источника'
