def _sheet_block_form_schema(fn_key):
    key = _inner_codec_dialog_effective_key(fn_key)
    kcf = unicode(key).casefold()
    for cand, entry in _pw_cfg._SHEET_BLOCK_FORM_SCHEMAS.items():
        if unicode(cand).casefold() == kcf:
            if entry.get('alias_of'):
                base = _sheet_block_form_schema(entry.get('alias_of'))
                if base is None:
                    return None
                merged = dict(base)
                for k, v in entry.items():
                    if k != 'alias_of':
                        merged[k] = v
                return merged
            return entry
    return None

def _sheet_list_panel_allows_convert(fn_key):
    try:
        from libre_macros_param_codec import sheet_block_form_allows_convert
        return sheet_block_form_allows_convert(fn_key)
    except Exception:
        return False

def _inner_codec_dialog_supported(fn_key):
    key = unicode(fn_key or u'').strip()
    if key == u'':
        return False
    try:
        from libre_macros_param_codec import normalize_fn_key
        key = normalize_fn_key(key) or key
    except Exception:
        pass
    if _param_match(key, u'объединить_листы_в_один') or _param_match(key, u'разделить_листы'):
        return True
    if _is_pivot_table_pp_name(key):
        return True
    if _is_sheet_list_panel_fn(key):
        return True
    if _is_sheet_block_form_fn(key):
        return True
    if _is_sheet_block_rules_fn(key):
        return True
    k = key.casefold()
    for cand in _pw_cfg._INNER_CODEC_DIALOG_REGISTRY:
        if unicode(cand).casefold() == k:
            return True
    return False

def _inner_codec_dialog_effective_key(fn_key):
    key = unicode(fn_key or u'').strip()
    if key == u'':
        return key
    try:
        from libre_macros_param_codec import normalize_fn_key
        key = normalize_fn_key(key) or key
    except Exception:
        pass
    k = key.casefold()
    for cand, entry in _pw_cfg._INNER_CODEC_DIALOG_REGISTRY.items():
        if unicode(cand).casefold() == k:
            alias = entry.get('alias_of')
            return alias or cand
    return key

def _pp_fn_has_json_params(fn_key):
    """Функция постобработки/финала с JSON в колонке C (кнопка «Параметры…»)."""
    key = unicode(fn_key or u'').strip()
    if key == u'' or _pp_is_plugin_primary(key):
        return False
    try:
        from libre_macros_param_codec import normalize_fn_key
        key = normalize_fn_key(key) or key
    except Exception:
        pass
    return _inner_codec_dialog_supported(key)

def _pp_minimal_json_for_fn(fn_key, force_as_values=False):
    """Минимальный JSON-блок для колонки C: [{"v":1,"fn":…}]."""
    try:
        from libre_macros_param_codec import normalize_fn_key, param_encode
    except Exception:
        key = unicode(fn_key or u'').strip()
        if key == u'':
            return u'[]'
        block = {u'v': 1, u'fn': key}
        if force_as_values and _is_pivot_table_pp_name(key):
            block[u'as_values'] = True
        elif force_as_values and unicode(key).casefold() == u'применить_формулу'.casefold():
            # В Постобработка_xml as_values для формул запрещён (direct криво).
            block.pop(u'as_values', None)
        try:
            import json
            return json.dumps([block], ensure_ascii=False, separators=(',', ':'))
        except Exception:
            return u'[{"v":1,"fn":"%s"}]' % key
    key = normalize_fn_key(fn_key)
    if key == u'':
        return u'[]'
    block = {u'v': 1, u'fn': key}
    if force_as_values and key == u'сводная_таблица':
        block[u'as_values'] = True
    elif force_as_values and unicode(key).casefold() == u'применить_формулу'.casefold():
        block.pop(u'as_values', None)
    try:
        return param_encode(key, [block])
    except Exception:
        try:
            import json
            return json.dumps([block], ensure_ascii=False, separators=(',', ':'))
        except Exception:
            return u'[{"v":1,"fn":"%s"}]' % key

def _pp_extra_needs_json_seed(fn_key, extra_text):
    """True — в C пусто / не JSON / другой fn → подставить минимальный шаблон."""
    key = unicode(fn_key or u'').strip()
    if key == u'' or not _pp_fn_has_json_params(key):
        return False
    raw = unicode(extra_text or u'').strip()
    if raw == u'':
        return True
    try:
        from libre_macros_param_codec import normalize_fn_key, param_decode
        blocks = param_decode(key, raw)
    except Exception:
        return True
    if not blocks:
        return True
    try:
        b0 = blocks[0] if isinstance(blocks[0], dict) else {}
        bfn = normalize_fn_key(b0.get('fn') or u'')
        return bfn != normalize_fn_key(key)
    except Exception:
        return True

def _show_inner_codec_param_dialog(parent_dialog, fn_key, initial_text, doc=None, force_as_values=False):
    """
    Простой «как у сводной» вложенный диалог-редактор:
    - поле C (многострочное)
    - ☑ Сохранять как JSON
    - OK/Отмена через PushButtonType
    """
    try:
        from libre_macros_param_codec import param_decode, param_encode
    except Exception as err:
        _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, u'Параметры', u'Не удалось загрузить libre_macros_param_codec: %s' % err)
        return None
    fn_key = _inner_codec_dialog_effective_key(fn_key)
    if unicode(fn_key).casefold() == u'объединить_листы_в_один'.casefold():
        result = show_merge_sheets_param_dialog(parent_dialog, initial_text, doc=doc)
        if result is None:
            return None
        if isinstance(result, dict):
            return unicode(result.get(u'json_c') or u'').strip() or None
        return unicode(result or u'').strip() or None
    if unicode(fn_key).casefold() == u'разделить_листы'.casefold():
        result = show_split_sheets_param_dialog(parent_dialog, initial_text, doc=doc)
        if result is None:
            return None
        if isinstance(result, dict):
            return unicode(result.get(u'json_c') or u'').strip() or None
        return unicode(result or u'').strip() or None
    if _is_pivot_table_pp_name(fn_key):
        init = unicode(initial_text or u'').strip()
        if init == u'':
            init = _pp_minimal_json_for_fn(fn_key, force_as_values=force_as_values)
        return show_pivot_table_param_dialog(parent_dialog, init, doc=doc, force_as_values=bool(force_as_values))
    if _is_sheet_list_panel_fn(fn_key):
        try:
            return _show_sheet_list_panel_dialog(parent_dialog, fn_key, initial_text, doc=doc)
        except Exception:
            pass
    if unicode(fn_key).casefold() == u'сортировка'.casefold():
        try:
            return _show_sort_param_dialog(parent_dialog, initial_text, doc=doc)
        except Exception:
            pass
    if unicode(fn_key).casefold() in (
        u'текстовые_операции'.casefold(),
        u'нормализация_текста'.casefold(),
        u'нормализовать_текст'.casefold(),
        u'normalize_text'.casefold(),
    ):
        try:
            return _show_normalize_text_param_dialog(parent_dialog, initial_text, doc=doc)
        except Exception as err:
            _wp_message_box_execute(
                doc,
                parent_dialog,
                MESSAGEBOX,
                MSG_BUTTONS.BUTTONS_OK,
                fn_key,
                u'Ошибка диалога текстовых операций:\n%s' % unicode(err),
            )
            return None
    if unicode(fn_key).casefold() in (u'раскрасить_блоки'.casefold(), u'раскрасить'.casefold()):
        try:
            return _show_colorize_blocks_param_dialog(parent_dialog, initial_text, doc=doc)
        except Exception:
            pass
    if unicode(fn_key).casefold() == u'условный_столбец'.casefold():
        try:
            return _show_conditional_column_param_dialog(parent_dialog, initial_text, doc=doc)
        except Exception as err:
            _wp_message_box_execute(
                doc,
                parent_dialog,
                MESSAGEBOX,
                MSG_BUTTONS.BUTTONS_OK,
                fn_key,
                u'Ошибка визарда условного столбца:\n%s' % unicode(err),
            )
            return None
    if _is_sheet_block_rules_fn(fn_key):
        try:
            return _show_block_rules_param_dialog(parent_dialog, fn_key, initial_text, doc=doc)
        except Exception as err:
            _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, fn_key, u'Ошибка диалога правил:\n%s' % unicode(err))
            return None
    if _is_sheet_block_form_fn(fn_key):
        try:
            forbid_av = bool(force_as_values) and (
                unicode(fn_key or u'').casefold() == u'применить_формулу'.casefold()
            )
            return _show_sheet_block_form_dialog(
                parent_dialog,
                fn_key,
                initial_text,
                doc=doc,
                forbid_as_values=forbid_av,
            )
        except Exception as err:
            _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, fn_key, u'Ошибка диалога формы:\n%s' % unicode(err))
            return None
    title = fn_key
    hint = u''
    for cand, entry in _pw_cfg._INNER_CODEC_DIALOG_REGISTRY.items():
        if unicode(cand).casefold() == unicode(fn_key).casefold():
            title = entry.get('title') or title
            hint = entry.get('hint') or u''
            break
    init = unicode(initial_text or u'').strip()
    if init == u'' and _pp_fn_has_json_params(fn_key):
        init = _pp_minimal_json_for_fn(fn_key, force_as_values=force_as_values)
    as_json_default = True
    parse_warn = None
    try:
        blocks = param_decode(fn_key, init)
        if not blocks and _pp_fn_has_json_params(fn_key):
            init = _pp_minimal_json_for_fn(fn_key, force_as_values=force_as_values)
            blocks = param_decode(fn_key, init)
        preview = param_encode(fn_key, blocks) if blocks else init
    except Exception as err:
        preview = init
        parse_warn = unicode(err)
    try:
        ctx = XSCRIPTCONTEXT.getComponentContext()
        sm = ctx.getServiceManager()
        toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
        dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    except Exception as err:
        _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, u'Не удалось создать модель диалога: %s' % err)
        return None
    dw = int(round(520 * 1.0))
    dh = _inner_dialog_height(int(round(360 * 1.0)))
    m = 10
    dm.PositionX = 120
    dm.PositionY = 80
    dm.Width = dw
    dm.Height = dh
    dm.Title = title
    try:
        dm.Sizeable = True
    except Exception:
        pass
    y = m
    if hint:
        _wizard_dlg_add_fixed(dm, 'HintLbl', hint, m, y, dw - m * 2, 32, multiline=True)
        y += 36
    _wizard_dlg_add_fixed(dm, 'MainLbl', u'Параметры (C):', m, y, 200, 14)
    y += 18
    edit_h = dh - y - _pw_cfg._INNER_FOOTER_RESERVE
    _wizard_dlg_add_edit(dm, 'ParamEdit', m, y, dw - m * 2, edit_h, multiline=True)
    _inner_dialog_add_footer(dm, m, dh, help_btn=True, dw=dw)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    _wizard_wire_help_button(dlg, doc=doc)

    try:
        dlg.getControl('ParamEdit').setText(preview)
    except Exception:
        pass
    try:
        dlg.getControl('JsonChk').setState(1 if as_json_default else 0)
    except Exception:
        pass
    if parse_warn:
        _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, u'Не удалось разобрать текущее значение:\n%s\n\nОткрыт редактор с исходной строкой.' % parse_warn)
    if dlg.execute() != 1:
        return None
    raw = u''
    try:
        raw = dlg.getControl('ParamEdit').getText().strip()
    except Exception:
        pass
    use_json = True
    try:
        use_json = bool(dlg.getControl('JsonChk').getState())
    except Exception:
        pass
    try:
        blocks = param_decode(fn_key, raw)
        return param_encode(fn_key, blocks)
    except Exception as err:
        _wp_message_box_execute(doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK, title, u'Ошибка параметров:\n%s' % unicode(err))
        return None

def _grid_create_column(col_model, title, width=90):
    try:
        col = col_model.createColumn()
        col.Title = title
        try:
            col.ColumnWidth = int(width)
        except Exception:
            pass
        col_model.addColumn(col)
    except Exception:
        pass

def _delete_rows_mode_is_formula(mode_text):
    return unicode(mode_text or u'').strip().casefold() == u'formula'

def _sync_delete_rows_mode_fields(fn_key, edits, combos, mode_text, col_pick_del_last=None, col_pick_del_all=None):
    """columns — столбцы активны; formula — поле формулы активно."""
    if unicode(fn_key or u'').casefold() not in (u'удаление_строк'.casefold(), u'пропуск_пустых_строк'.casefold()):
        return
    is_formula = _delete_rows_mode_is_formula(mode_text)
    cols_enabled = not is_formula
    cols_ctl = None
    if edits is not None:
        cols_ctl = edits.get('columns')
    if cols_ctl is None and combos is not None:
        cols_ctl = combos.get('columns')
    formula_ctl = edits.get('formula') if edits is not None else None
    for ctl, enabled in ((cols_ctl, cols_enabled), (formula_ctl, is_formula)):
        if ctl is None:
            continue
        try:
            ctl.setEnable(bool(enabled))
        except Exception:
            try:
                ctl.Model.Enabled = bool(enabled)
            except Exception:
                pass
    for btn_map in (col_pick_del_last, col_pick_del_all):
        if not btn_map:
            continue
        btn = btn_map.get('columns')
        if btn is None:
            continue
        try:
            btn.setEnable(bool(cols_enabled))
        except Exception:
            try:
                btn.Model.Enabled = bool(cols_enabled)
            except Exception:
                pass

def _validate_manual_variable_blocks_for_wizard(blocks):
    """Проверка блоков ручного ввода перед записью в C. Пустая строка = ок."""
    seen = {}
    bi = 0
    while bi < len(blocks or []):
        b = blocks[bi]
        bi = bi + 1
        if not isinstance(b, dict):
            continue
        name = unicode(b.get(u'name') or u'').strip()
        if name == u'':
            return u'Укажите имя переменной для каждого блока (поле «Имя переменной»).'
        if u'~' in name:
            return u'В имени переменной «%s» нельзя использовать тильду (~).' % name
        try:
            key = name.casefold()
        except Exception:
            key = name.lower()
        if key in seen:
            return u'Дублируется имя переменной «%s» (блоки #%d и #%d).' % (
                name,
                seen[key] + 1,
                bi,
            )
        seen[key] = bi - 1
    if len(seen) == 0:
        return u'Добавьте хотя бы одну переменную с именем («+ Блок»).'
    return u''


def _is_manual_var_wizard_fn(fn_key):
    return unicode(fn_key or u'').casefold() in (
        u'ручной_ввод_в_карту_переменных'.casefold(),
        u'ручной_ввод'.casefold(),
        u'manual_variable_input'.casefold(),
        u'Ручной_ввод_в_карту_переменных'.casefold(),
    )


def _schema_field_ids(schema):
    out = set()
    for fld in (schema.get('fields') or ()):
        fid = fld.get('id')
        if fid:
            out.add(unicode(fid))
    return out


def _strip_block_sheet_targeting(block, schema):
    """Убрать привязку блока к листу; не трогать поле sheets, если оно в схеме формы."""
    if not isinstance(block, dict):
        return
    block.pop(u'sheet', None)
    if u'sheets' not in _schema_field_ids(schema):
        block.pop(u'sheets', None)


def _sheet_block_form_label(block, schema):
    if bool((schema or {}).get('blocks_without_sheet')):
        name = unicode((block or {}).get('name') or u'').strip()
        if name == u'':
            return u'(без имени)'
        if len(name) > 28:
            return name[:28] + u'…'
        return name
    sheet = unicode(block.get('sheet') or u'').strip()
    fields = schema.get('fields') or ()
    field_ids = [unicode(f.get('id') or u'') for f in fields]
    if u'old' in field_ids and u'new' in field_ids:
        mappings = block.get('mappings') or []
        first = mappings[0] if isinstance(mappings, (list, tuple)) and mappings else {}
        if isinstance(first, dict):
            old = unicode(first.get('old') or block.get('old') or u'').strip()
            new = unicode(first.get('new') or block.get('new') or u'').strip()
            if old and new:
                tail = u'%s → %s' % (old, new)
                if len(tail) > 28:
                    tail = tail[:28] + u'…'
                return _inner_block_list_label(sheet, tail)
    tail = u''
    if len(fields) > 0:
        fid = fields[0].get('id')
        raw = block.get(fid)
        if isinstance(raw, (list, tuple)):
            val = u', '.join((unicode(x) for x in raw if unicode(x).strip() != u''))
        elif raw is None:
            val = u''
        else:
            val = unicode(raw).strip()
        tail = val[:24] + (u'…' if len(val) > 24 else u'')
    return _inner_block_list_label(sheet, tail)

def _is_send_mail_wizard_fn(fn_key):
    return unicode(fn_key or u'').casefold() in (
        u'отправить_по_почте'.casefold(),
        u'email'.casefold(),
        u'mailto'.casefold(),
        u'send_mail'.casefold(),
        u'почта'.casefold(),
    )

def _block_field_to_text(block, field_id, fn_key=None):
    if unicode(fn_key or u'').casefold() == u'градиент'.casefold() and field_id == 'sort_dir':
        raw = unicode(block.get(field_id) or u'').strip().casefold()
        if raw in (u'-', u'desc', u'убыв', u'по_убыв'):
            return u'-'
        if raw in (u'+', u'asc', u'возр', u'по_возр'):
            return u'+'
        return u'+'
    if unicode(fn_key or u'').casefold() == u'переименовать_столбцы'.casefold():
        mappings = block.get('mappings') or []
        first = mappings[0] if isinstance(mappings, (list, tuple)) and mappings else {}
        if field_id == 'old':
            return unicode((first or {}).get('old') or block.get('old') or u'').strip()
        if field_id == 'new':
            return unicode((first or {}).get('new') or block.get('new') or u'').strip()
    if unicode(fn_key or u'').casefold() == u'замена_значений'.casefold() and field_id in ('find', 'replace'):
        val = block.get(field_id)
        empty_tok = (u'_пусто_', u'_empty_', u'__пусто__')
        parts = []

        def _replace_token_for_ui(x):
            s = unicode(x).strip() if x is not None else u''
            try:
                from libre_macros_param_codec import (
                    unwrap_column_name_token,
                    wrap_column_name_token_exact,
                )
                bare, quoted = unwrap_column_name_token(s)
            except Exception:
                bare, quoted = s, False
            if bare.casefold() in empty_tok or (field_id == 'replace' and bare == u''):
                return u'_ПУСТО_'
            if quoted:
                return wrap_column_name_token_exact(bare, strip_name=False)
            return bare

        if isinstance(val, (list, tuple)):
            for x in val:
                s = _replace_token_for_ui(x)
                if s != u'' or field_id == 'replace':
                    parts.append(s)
        else:
            s = _replace_token_for_ui(val)
            if s != u'' or (field_id == 'replace' and val is not None):
                parts.append(s)
        try:
            from libre_macros_param_codec import join_sep_list_respecting_quotes
            return join_sep_list_respecting_quotes(parts, sep=u';', keep_quotes=True)
        except Exception:
            return u'; '.join(parts)
    if field_id == 'ops':
        val = block.get('ops')
        if val is None or val == u'' or val == []:
            return u''
        if isinstance(val, (unicode, str)):
            return unicode(val)
        try:
            import json
            return unicode(json.dumps(val, ensure_ascii=False))
        except Exception:
            return unicode(val)
    if field_id == 'choices':
        val = block.get('choices')
        if val is None or val == u'' or val == []:
            return u''
        parts = []
        if isinstance(val, (list, tuple)):
            seq = val
        else:
            try:
                from libre_macros_param_codec import split_column_name_tokens
                seq = split_column_name_tokens(unicode(val))
            except Exception:
                seq = re.split(u'[,;]', unicode(val))
        for x in seq:
            t = unicode(x or u'').strip()
            if t == u'':
                continue
            try:
                from libre_macros_param_codec import unwrap_column_name_token
                bare, _q = unwrap_column_name_token(t)
                t = unicode(bare or u'').strip() or t
            except Exception:
                if len(t) >= 2 and t[0] == t[-1] and t[0] in (u"'", u'"'):
                    t = t[1:-1].strip()
            if t != u'':
                parts.append(t)
        if not parts:
            return u''
        sep = u';' if any((u',' in p) for p in parts) else u','
        return sep.join(parts)
    if field_id == 'keep':
        raw = unicode(block.get('keep') or u'first').strip().casefold()
        return _pw_cfg.DEDUP_KEEP_LABEL.get(raw, unicode(block.get('keep') or u'first'))
    if _is_send_mail_wizard_fn(fn_key):
        if field_id in (u'to', u'cc', u'bcc'):
            val = block.get(field_id) or []
            if isinstance(val, (list, tuple)):
                return u'; '.join(
                    unicode(x).strip() for x in val if unicode(x).strip() != u''
                )
            return unicode(val or u'').strip()
        if field_id == u'sheets':
            val = block.get('sheets') or []
            if isinstance(val, (list, tuple)):
                return u', '.join(
                    unicode(x).strip() for x in val if unicode(x).strip() != u''
                )
            return unicode(val or u'').strip()
        if field_id == u'attach':
            raw = unicode(block.get('attach') or u'whole_book').strip().casefold()
            return _pw_cfg.SEND_MAIL_ATTACH_LABEL.get(
                raw, unicode(block.get('attach') or u'whole_book')
            )
        if field_id == u'format':
            raw = unicode(block.get('format') or u'ods').strip().casefold()
            return _pw_cfg.SEND_MAIL_FORMAT_LABEL.get(
                raw, unicode(block.get('format') or u'ods')
            )
        if field_id == u'os':
            raw = unicode(block.get('os') or u'auto').strip().casefold()
            return _pw_cfg.SEND_MAIL_OS_LABEL.get(
                raw, unicode(block.get('os') or u'auto')
            )
        if field_id == u'client':
            raw = unicode(block.get('client') or u'auto').strip().casefold()
            return _pw_cfg.SEND_MAIL_CLIENT_LABEL.get(
                raw, unicode(block.get('client') or u'auto')
            )
    if field_id == 'value_kind':
        raw = unicode(block.get('value_kind') or u'scalar').strip().casefold()
        return getattr(_pw_cfg, 'MANUAL_VAR_VALUE_KIND_LABEL', {}).get(
            raw, unicode(block.get('value_kind') or u'scalar')
        )
    if field_id == 'data_type' and unicode(fn_key or u'').casefold() in (
        u'ручной_ввод_в_карту_переменных'.casefold(),
        u'ручной_ввод'.casefold(),
        u'manual_variable_input'.casefold(),
        u'добавить_столбец'.casefold(),
        u'add_column'.casefold(),
        u'новый_столбец'.casefold(),
    ):
        raw = unicode(block.get('data_type') or u'text').strip().casefold()
        if unicode(fn_key or u'').casefold() in (
            u'добавить_столбец'.casefold(),
            u'add_column'.casefold(),
            u'новый_столбец'.casefold(),
        ):
            return getattr(_pw_cfg, 'ADD_COLUMN_DATA_TYPE_LABEL', {}).get(
                raw, unicode(block.get('data_type') or u'text')
            )
        return getattr(_pw_cfg, 'MANUAL_VAR_DATA_TYPE_LABEL', {}).get(
            raw, unicode(block.get('data_type') or u'text')
        )
    if field_id == 'required' and unicode(fn_key or u'').casefold() in (
        u'ручной_ввод_в_карту_переменных'.casefold(),
        u'ручной_ввод'.casefold(),
        u'manual_variable_input'.casefold(),
    ):
        raw = block.get('required')
        if isinstance(raw, bool):
            return u'Да' if raw else u'Нет'
        s = unicode(raw if raw is not None else u'true').strip().casefold()
        if s in (u'0', u'false', u'no', u'нет', u'n', u'off'):
            return u'Нет'
        return u'Да'
    if field_id == 'mode' and unicode(fn_key or u'').casefold() in (
        u'копирование_диапазонов'.casefold(),
        u'копировать_диапазон'.casefold(),
        u'copy_ranges'.casefold(),
        u'copy_range'.casefold(),
        u'вставить_диапазон'.casefold(),
    ):
        raw = unicode(block.get('mode') or u'replace').strip().casefold()
        return _pw_cfg.COPY_RANGES_MODE_LABEL.get(
            raw, unicode(block.get('mode') or u'replace')
        )
    if field_id == 'insert_axis':
        raw = unicode(block.get('insert_axis') or u'auto').strip().casefold()
        return _pw_cfg.COPY_RANGES_AXIS_LABEL.get(
            raw, unicode(block.get('insert_axis') or u'auto')
        )
    if field_id == 'content' and unicode(fn_key or u'').casefold() in (
        u'копирование_диапазонов'.casefold(),
        u'копировать_диапазон'.casefold(),
        u'copy_ranges'.casefold(),
        u'copy_range'.casefold(),
        u'вставить_диапазон'.casefold(),
    ):
        raw = unicode(block.get('content') or u'values').strip().casefold()
        return _pw_cfg.COPY_RANGES_CONTENT_LABEL.get(
            raw, unicode(block.get('content') or u'values')
        )
    if field_id == 'name_mode' and unicode(fn_key or u'').casefold() in (
        u'создать_лист'.casefold(),
        u'create_sheet'.casefold(),
    ):
        raw = unicode(block.get('name_mode') or u'manual').strip().casefold()
        return _pw_cfg.CREATE_SHEET_NAME_MODE_LABEL.get(
            raw, unicode(block.get('name_mode') or u'manual')
        )
    if field_id == 'data_mode' and unicode(fn_key or u'').casefold() in (
        u'создать_лист'.casefold(),
        u'create_sheet'.casefold(),
    ):
        raw = unicode(block.get('data_mode') or u'none').strip().casefold()
        return _pw_cfg.CREATE_SHEET_DATA_MODE_LABEL.get(
            raw, unicode(block.get('data_mode') or u'none')
        )
    if field_id == 'sheet_name' and unicode(fn_key or u'').casefold() in (
        u'создать_лист'.casefold(),
        u'create_sheet'.casefold(),
    ):
        mode = unicode(block.get('name_mode') or u'manual').strip().casefold()
        if mode in (u'expr', u'lambda', u'compute', u'вычислить', u'лямбда'):
            return unicode(block.get('sheet_name_expr') or u'').strip()
        return unicode(block.get('sheet_name') or u'').strip()
    if field_id == 'match_pick':
        raw = unicode(block.get('match_pick') or u'all').strip().casefold()
        return _pw_cfg.REPLACE_MATCH_PICK_LABEL.get(
            raw, unicode(block.get('match_pick') or u'all')
        )
    if field_id == 'replace_mode':
        raw = unicode(block.get('replace_mode') or u'manual').strip().casefold()
        if raw in (u'', u'manual'):
            # авто: есть expr без списка
            if unicode(block.get('replace_expr') or u'').strip() and not (
                block.get('replace') not in (None, u'', [], ())
            ):
                raw = u'lambda'
            else:
                raw = u'manual'
        return _pw_cfg.REPLACE_MODE_LABEL.get(
            raw, unicode(block.get('replace_mode') or u'Вручную')
        )
    if field_id == 'replace_expr':
        return unicode(
            block.get('replace_expr')
            or block.get('replace_lambda')
            or u''
        ).strip()
    if field_id == 'output':
        if bool(block.get('mark_duplicates')):
            return _pw_cfg.DEDUP_OUTPUT_LABEL.get(
                u'mark', u'Маркировка (столбец)'
            )
        raw = unicode(block.get('output') or u'inplace').strip().casefold()
        fk = unicode(fn_key or u'').casefold()
        if fk in (u'развернуть_столбцы'.casefold(), u'unpivot', u'unpivot_columns'):
            return _pw_cfg.UNPIVOT_OUTPUT_LABEL.get(
                raw, unicode(block.get('output') or u'inplace')
            )
        if fk in (
            u'транспонировать_таблицу'.casefold(),
            u'transpose',
            u'transpose_table',
        ):
            return _pw_cfg.TRANSPOSE_OUTPUT_LABEL.get(
                raw, unicode(block.get('output') or u'inplace')
            )
        if fk in (
            u'анкета_в_таблицу'.casefold(),
            u'таблица_в_анкету'.casefold(),
            u'form_to_table',
            u'table_to_form',
        ):
            return _pw_cfg.FORM_TABLE_OUTPUT_LABEL.get(
                raw, unicode(block.get('output') or u'new_sheet')
            )
        return _pw_cfg.DEDUP_OUTPUT_LABEL.get(raw, unicode(block.get('output') or u'inplace'))
    if field_id == 'block_mode':
        raw = unicode(block.get('block_mode') or u'by_repeat_key').strip().casefold()
        return _pw_cfg.FORM_BLOCK_MODE_LABEL.get(
            raw, unicode(block.get('block_mode') or u'by_repeat_key')
        )
    if field_id == 'block_separator':
        raw = unicode(block.get('block_separator') or u'blank_row').strip().casefold()
        return _pw_cfg.FORM_BLOCK_SEP_LABEL.get(
            raw, unicode(block.get('block_separator') or u'blank_row')
        )
    if field_id == 'skip_empty_cells':
        if 'skip_empty_cells' in block:
            return bool(block.get('skip_empty_cells'))
        raw = unicode(block.get('empty_key_policy') or u'dedup').strip().casefold()
        return raw == u'skip'
    if field_id in ('key_columns', 'exclude_columns', 'unpivot_columns', 'body_columns', 'skip_columns', 'sheet_preamble_columns', 'block_preamble_columns', 'columns', 'markers', 'marker', 'agg_columns', 'style_columns', 'source_columns'):
        val = block.get(field_id)
        if val is None or val == u'' or val == []:
            return u''
        try:
            from libre_macros_param_codec import (
                canonicalize_column_token_list_for_store,
                join_column_name_tokens,
            )
            parts = canonicalize_column_token_list_for_store(val)
            if not parts:
                return u''
            sep = u';' if any((u',' in unicode(p) or u';' in unicode(p)) for p in parts) else u','
            return join_column_name_tokens([unicode(p) for p in parts], sep=sep)
        except Exception:
            pass
        if isinstance(val, (list, tuple)):
            parts = [unicode(x).strip() for x in val if unicode(x).strip()]
        else:
            parts = [unicode(val).strip()] if unicode(val).strip() else []
        if not parts:
            return u''
        return u','.join(parts)
    if field_id == 'agg_fn':
        raw = unicode(block.get(field_id) or u'sum').strip().casefold()
        return _pw_cfg.GROUP_AGG_FN_LABEL.get(raw, unicode(block.get(field_id) or u'sum'))
    if fn_key == u'зебра_диапазон' and field_id in ('header', 'even', 'odd'):
        roles = block.get('roles') or {}
        spec = roles.get(field_id) or {}
        fill = unicode(spec.get('fill') or u'').strip()
        font = unicode(spec.get('font') or u'').strip()
        if fill and font:
            return u'%s/%s' % (fill, font)
        return fill or font
    if field_id in ('wrap', 'include_header', 'whole_sheet', 'whole_row', 'sort', 'bold', 'italic', 'font_color_auto', 'as_values', 'copy'):
        return u'1' if block.get(field_id) else u'0'
    val = block.get(field_id)
    if isinstance(val, (list, tuple)):
        return u', '.join((unicode(x) for x in val if unicode(x).strip()))
    if field_id in ('height_mm', 'width_mm', 'steps', 'fit_pages', 'font_size'):
        if val is None:
            return u''
        if val == int(val):
            return unicode(int(val))
        return unicode(val)
    if field_id in ('size_data', 'size_header'):
        if val is None:
            return u''
        if val == int(val):
            return unicode(int(val))
        return unicode(val)
    if field_id in ('threshold', 'threshold_min', 'threshold_max') and val is not None:
        try:
            fv = float(val)
            if fv == int(fv):
                return unicode(int(fv))
            return unicode(fv)
        except (TypeError, ValueError):
            return unicode(val)
    if field_id == 'separator':
        raw = val if val is not None else u''
        try:
            from libre_macros_param_wizard_cfg import HEADER_SEP_LABEL
            lab = HEADER_SEP_LABEL.get(raw)
            if lab:
                return lab
        except Exception:
            pass
        return unicode(raw)
    if field_id == 'format':
        fmt = unicode(val or u'').strip()
        if unicode(fn_key or u'').casefold() in (u'формат_даты'.casefold(), u'формат_деньги'.casefold()):
            return fmt if fmt else u'(глобальный)'
        return fmt
    if field_id == 'mappings':
        items = val if isinstance(val, (list, tuple)) else []
        parts = []
        for item in items:
            if isinstance(item, dict):
                old = unicode(item.get('old') or u'').strip()
                new = unicode(item.get('new') or u'').strip()
                if old and new:
                    parts.append(u'%s=%s' % (old, new))
        return u', '.join(parts)
    if field_id == 'position':
        raw = unicode(val or u'').strip().casefold()
        rev = {u'start': u'_начало_', u'end': u'_конец_', u'before': u'_перед_', u'after': u'_после_'}
        return rev.get(raw, unicode(val or u'').strip())
    return unicode(val or u'').strip()

def _text_to_block_field(field_id, text, field_type=None, fn_key=None):
    if field_type == 'bool':
        if isinstance(text, bool):
            return text
        text = unicode(text or u'').strip()
        return text.lower() not in (u'0', u'false', u'нет', u'no', u'-')
    if field_id == 'sort_dir':
        t = unicode(text or u'').strip().casefold()
        if t in (u'-', u'desc', u'убыв', u'по_убыв'):
            return u'по_убыв'
        if t in (u'+', u'asc', u'возр', u'по_возр'):
            return u'по_возр'
        return u'по_возр'
    if field_id in ('find', 'replace'):
        text = unicode(text or u'').strip()
        empty_tok = (u'_пусто_', u'_empty_', u'__пусто__')
        if text == u'':
            if field_id == 'replace':
                return [u'_ПУСТО_']
            return []
        try:
            from libre_macros_param_codec import (
                split_sep_list_respecting_quotes,
                unwrap_column_name_token,
                wrap_column_name_token_exact,
            )
            parts_raw = split_sep_list_respecting_quotes(
                text, keep_empty_quoted=True, keep_quotes=True
            )
        except Exception:
            parts_raw = [p.strip() for p in re.split('[;,]', text)]
            unwrap_column_name_token = None
            wrap_column_name_token_exact = None
        parts = []
        for p in parts_raw:
            p = unicode(p).strip() if p is not None else u''
            bare, quoted = p, False
            if unwrap_column_name_token is not None:
                try:
                    bare, quoted = unwrap_column_name_token(p)
                except Exception:
                    bare, quoted = p, False
            if bare.casefold() in empty_tok or (field_id == 'replace' and bare == u''):
                parts.append(u'_ПУСТО_')
            elif quoted and wrap_column_name_token_exact is not None:
                parts.append(wrap_column_name_token_exact(bare, strip_name=False))
            elif bare != u'':
                parts.append(bare)
        if field_id == 'replace' and not parts:
            return [u'_ПУСТО_']
        return parts
    if field_id == 'ops':
        text = unicode(text or u'').strip()
        if text == u'':
            return []
        try:
            from libre_macros_normalize_lib import coerce_ops_list
            return coerce_ops_list(text)
        except Exception:
            try:
                import json
                parsed = json.loads(text)
                if isinstance(parsed, list):
                    return parsed
            except Exception:
                pass
            return [{'op': p.strip()} for p in re.split(r'[;\n]+', text) if p.strip()]
    if field_id == 'separator':
        raw = unicode(text) if text is not None else u''
        try:
            from libre_macros_param_wizard_cfg import HEADER_SEP_CODE
            key = raw.strip().casefold()
            if key in HEADER_SEP_CODE:
                return HEADER_SEP_CODE[key]
        except Exception:
            pass
        return raw
    if field_id == 'format':
        t = unicode(text or u'').strip()
        if t == u'' or t == u'(глобальный)':
            return u''
        try:
            gs_lib = _wp_import_global_settings_lib()
            if gs_lib and t == gs_lib['CUSTOM_NUMBER_FORMAT_LABEL']:
                return u''
        except Exception:
            pass
        return t
    if field_id == 'mappings':
        text = unicode(text or u'').strip()
        if text == u'':
            return []
        try:
            from libre_macros_param_codec import _parse_column_rename_mappings
            return _parse_column_rename_mappings(text)
        except Exception:
            out = []
            for part in re.split('[,;]', text):
                part = part.strip()
                if u'=' in part:
                    old, _, new = part.partition(u'=')
                elif u'->' in part:
                    old, _, new = part.partition(u'->')
                else:
                    continue
                old = old.strip()
                new = new.strip()
                if old and new:
                    out.append({'old': old, 'new': new})
            return out
    if field_id == 'position':
        t = unicode(text or u'').strip().casefold()
        rev = {
            u'_перед_': u'before',
            u'_после_': u'after',
            u'перед': u'before',
            u'до': u'before',
            u'после': u'after',
            u'before': u'before',
            u'after': u'after',
        }
        code = rev.get(t, t)
        return code if code in (u'before', u'after') else unicode(text or u'').strip()
    if field_id in ('old', 'new'):
        return unicode(text or u'').strip()
    text = unicode(text or u'').strip()
    if field_type == 'columns_pick' or field_id in ('key_columns', 'exclude_columns', 'unpivot_columns', 'body_columns', 'skip_columns', 'sheet_preamble_columns', 'block_preamble_columns', 'style_columns'):
        text = unicode(text or u'').strip()
        if text == u'':
            return []
        try:
            from libre_macros_param_codec import canonicalize_column_token_list_for_store
            return canonicalize_column_token_list_for_store(text)
        except Exception:
            pass
        try:
            from libre_macros_param_codec import split_column_name_tokens
            parts = split_column_name_tokens(text)
            if parts:
                return parts
        except Exception:
            pass
        out = []
        for p in re.split('[,;]', text):
            p = p.strip()
            if p != u'':
                out.append(p)
        return out
    if field_id == 'choices':
        text = unicode(text or u'').strip()
        if text == u'':
            return []
        parts = []
        try:
            from libre_macros_param_codec import (
                split_column_name_tokens,
                unwrap_column_name_token,
            )
            for tok in split_column_name_tokens(text):
                bare, _q = unwrap_column_name_token(tok)
                t = unicode(bare or u'').strip()
                if t != u'':
                    parts.append(t)
        except Exception:
            parts = []
        if not parts:
            for chunk in re.split(u'[,;]', text):
                t = chunk.strip()
                if len(t) >= 2 and t[0] == t[-1] and t[0] in (u"'", u'"'):
                    t = t[1:-1].strip()
                if t != u'':
                    parts.append(t)
        return parts
    if field_id == 'value_kind':
        t = unicode(text or u'').strip()
        code = _pw_cfg.MANUAL_VAR_VALUE_KIND_CODE.get(t, None)
        if code is None:
            code = _pw_cfg.MANUAL_VAR_VALUE_KIND_CODE.get(t.casefold(), None)
        if code is None:
            tc = t.casefold()
            if tc in (u'list', u'список', u'array'):
                code = u'list'
            else:
                code = u'scalar'
        return code
    if field_id == 'data_type':
        t = unicode(text or u'').strip()
        code = getattr(_pw_cfg, 'ADD_COLUMN_DATA_TYPE_CODE', {}).get(t, None)
        if code is None:
            code = getattr(_pw_cfg, 'ADD_COLUMN_DATA_TYPE_CODE', {}).get(t.casefold(), None)
        if code is None:
            code = _pw_cfg.MANUAL_VAR_DATA_TYPE_CODE.get(t, None)
        if code is None:
            code = _pw_cfg.MANUAL_VAR_DATA_TYPE_CODE.get(t.casefold(), None)
        if code is None:
            tc = t.casefold()
            dt_map = {
                u'text': u'text', u'str': u'text', u'string': u'text', u'текст': u'text',
                u'number': u'number', u'num': u'number', u'число': u'number',
                u'date': u'date', u'дата': u'date',
                u'datetime': u'datetime', u'дата_время': u'datetime', u'дата-время': u'datetime',
                u'bool': u'bool', u'boolean': u'bool', u'логическое': u'bool',
            }
            code = dt_map.get(tc, u'text')
        if code not in (u'text', u'number', u'date', u'datetime', u'bool'):
            code = u'text'
        return code
    if field_id == 'required':
        t = unicode(text or u'').strip().casefold()
        if t in (u'0', u'false', u'no', u'нет', u'n', u'off'):
            return False
        if t in (u'1', u'true', u'yes', u'да', u'y', u'on', u''):
            return True
        return True
    if field_id == 'keep':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.DEDUP_KEEP_CODE.get(t, t)
        return code if code in (u'first', u'last') else u'first'
    if _is_send_mail_wizard_fn(fn_key):
        if field_id in (u'to', u'cc', u'bcc'):
            text = unicode(text or u'').strip()
            if text == u'':
                return []
            return [
                p.strip()
                for p in re.split(u'[;,]', text)
                if p.strip() != u''
            ]
        if field_id == u'sheets':
            text = unicode(text or u'').strip()
            if text == u'':
                return []
            return [
                p.strip()
                for p in re.split(u'[;,]', text)
                if p.strip() != u''
            ]
        if field_id == u'attach':
            t = unicode(text or u'').strip().casefold()
            code = _pw_cfg.SEND_MAIL_ATTACH_CODE.get(t, t)
            if code in _pw_cfg.SEND_MAIL_ATTACH_LABEL:
                return code
            return u'whole_book'
        if field_id == u'format':
            t = unicode(text or u'').strip().casefold()
            code = _pw_cfg.SEND_MAIL_FORMAT_CODE.get(t, t)
            if code in _pw_cfg.SEND_MAIL_FORMAT_LABEL:
                return code
            return u'ods'
        if field_id == u'os':
            t = unicode(text or u'').strip().casefold()
            code = _pw_cfg.SEND_MAIL_OS_CODE.get(t, t)
            if code in _pw_cfg.SEND_MAIL_OS_LABEL:
                return code
            return u'auto'
        if field_id == u'client':
            t = unicode(text or u'').strip().casefold()
            code = _pw_cfg.SEND_MAIL_CLIENT_CODE.get(t, t)
            if code in _pw_cfg.SEND_MAIL_CLIENT_LABEL:
                return code
            return u'auto'
    if field_id == 'mode':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.COPY_RANGES_MODE_CODE.get(t, t)
        if code in (u'replace', u'insert'):
            return code
        return unicode(text or u'').strip()
    if field_id == 'insert_axis':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.COPY_RANGES_AXIS_CODE.get(t, t)
        if code in (u'auto', u'rows', u'cols'):
            return code
        return u'auto'
    if field_id == 'content':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.COPY_RANGES_CONTENT_CODE.get(t, t)
        if code in (u'values', u'formulas'):
            return code
        return unicode(text or u'').strip() or u'values'
    if field_id == 'name_mode':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.CREATE_SHEET_NAME_MODE_CODE.get(t, t)
        if code in (u'manual', u'expr'):
            return code
        return u'manual'
    if field_id == 'data_mode':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.CREATE_SHEET_DATA_MODE_CODE.get(t, t)
        if code in (u'none', u'sheet', u'rows'):
            return code
        return u'none'
    if field_id == 'dest_sheets':
        text = unicode(text or u'').strip()
        if text == u'':
            return []
        return [
            p.strip()
            for p in re.split(u'[,;]', text)
            if p.strip() != u''
        ]
    if field_id == 'match_pick':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.REPLACE_MATCH_PICK_CODE.get(t, t)
        if code in _pw_cfg.REPLACE_MATCH_PICK_LABEL:
            return code
        return u'all'
    if field_id == 'replace_mode':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.REPLACE_MODE_CODE.get(t, t)
        if code in _pw_cfg.REPLACE_MODE_LABEL:
            return code
        return u'manual'
    if field_id == 'agg_fn':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.GROUP_AGG_FN_CODE.get(t, t)
        if code in _pw_cfg.GROUP_AGG_FN_LABEL:
            return code
        return u'sum'
    if field_id == 'output':
        t = unicode(text or u'').strip().casefold()
        if unicode(fn_key or u'').casefold() in (
            u'развернуть_столбцы'.casefold(),
            u'unpivot',
            u'unpivot_columns',
        ):
            code = _pw_cfg.UNPIVOT_OUTPUT_CODE.get(t, t)
            if code in (u'inplace', u'new_sheet'):
                return code
            return u'inplace'
        if unicode(fn_key or u'').casefold() in (
            u'транспонировать_таблицу'.casefold(),
            u'transpose',
            u'transpose_table',
        ):
            code = _pw_cfg.TRANSPOSE_OUTPUT_CODE.get(t, t)
            if code in (u'inplace', u'new_sheet', u'offset'):
                return code
            return u'inplace'
        if unicode(fn_key or u'').casefold() in (
            u'анкета_в_таблицу'.casefold(),
            u'таблица_в_анкету'.casefold(),
            u'form_to_table',
            u'table_to_form',
        ):
            code = _pw_cfg.FORM_TABLE_OUTPUT_CODE.get(t, t)
            if code in (u'inplace', u'new_sheet', u'replace_sheet'):
                return code
            return u'new_sheet'
        code = _pw_cfg.DEDUP_OUTPUT_CODE.get(t, t)
        if code in (u'inplace', u'new_sheet', u'offset', u'mark'):
            return code
        return u'inplace'
    if field_id == 'block_mode':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.FORM_BLOCK_MODE_CODE.get(t, t)
        if code in _pw_cfg.FORM_BLOCK_MODE_LABEL:
            return code
        return u'by_repeat_key'
    if field_id == 'block_separator':
        t = unicode(text or u'').strip().casefold()
        code = _pw_cfg.FORM_BLOCK_SEP_CODE.get(t, t)
        if code in _pw_cfg.FORM_BLOCK_SEP_LABEL:
            return code
        return u'blank_row'
    if field_id in ('markers', 'columns', 'new_names', 'result_headers'):
        if text == u'':
            return []
        if field_id in ('new_names', 'result_headers'):
            out = []
            for p in re.split('[,;]', text):
                p = p.strip()
                if p != u'':
                    out.append(p)
            return out
        try:
            from libre_macros_param_codec import canonicalize_column_token_list_for_store
            return canonicalize_column_token_list_for_store(text)
        except Exception:
            pass
        out = []
        for p in re.split('[,;]', text):
            p = p.strip()
            if p == u'':
                continue
            if p.isdigit():
                out.append(int(p))
            else:
                out.append(p)
        return out
    if field_id == 'fit_pages':
        if text == u'':
            return 1
        try:
            return int(text)
        except (TypeError, ValueError):
            return 1
    if field_id == 'threshold':
        if text == u'':
            return 1000.0
        try:
            return float(text.replace(u',', u'.'))
        except (TypeError, ValueError):
            return 1000.0
    if field_id in ('threshold_min', 'threshold_max'):
        if text == u'':
            return None
        try:
            return float(text.replace(u',', u'.'))
        except (TypeError, ValueError):
            return None
    if field_id in ('height_mm', 'width_mm', 'steps', 'size_data', 'size_header', 'font_size'):
        if text in (u'', u'-', u'—'):
            return None
        try:
            return float(text.replace(u',', u'.'))
        except (TypeError, ValueError):
            return text
    return text

def _zebra_role_from_field_text(text):
    text = unicode(text or u'').strip()
    if text == u'':
        return None
    fill, font = (text, u'')
    if u'/' in text:
        fill, _, font = text.partition(u'/')
    return {'fill': fill.strip(), 'font': font.strip()}

def _sheet_block_field_row_height(fld, fn_key=None):
    ftype = fld.get('type')
    if unicode(fn_key or u'').casefold() == u'градиент'.casefold():
        try:
            if unicode(fld.get('id') or u'').casefold() == u'sort_dir'.casefold():
                return 0
        except Exception:
            pass
    # Второй checkbox в pair_after / второй в row_group — не добавляет высоту
    if ftype == 'bool' and fld.get('pair_after'):
        return 0
    if ftype == 'bool' and int(fld.get('row_group_slot') or 0) > 0:
        return 0
    if fld.get('row_group') and int(fld.get('row_group_slot') or 0) > 0:
        return 0
    gap = _pw_cfg._SHEET_BLOCK_FIELD_GAP
    if unicode(fn_key or u'').casefold() in (
        u'создать_лист'.casefold(),
        u'create_sheet'.casefold(),
        u'замена_значений'.casefold(),
        u'replace_values'.casefold(),
        u'отправить_по_почте'.casefold(),
        u'email'.casefold(),
        u'mailto'.casefold(),
        u'send_mail'.casefold(),
        u'почта'.casefold(),
        u'анкета_в_таблицу'.casefold(),
        u'form_to_table'.casefold(),
    ):
        gap = min(int(gap), 2)
    if ftype == 'bool':
        return 16 + gap
    if ftype == 'columns_pick':
        return 12 + 2 + 18 + gap
    if fld.get('tall'):
        return 12 + 2 + 36 + gap
    if ftype == 'combo' and fld.get('with_auto_check'):
        return 12 + 2 + 18 + 18 + gap
    if fld.get('with_bool_check'):
        return 12 + 2 + 18 + gap
    if ftype == 'lambda_pick':
        return 12 + 2 + 18 + gap
    return 12 + 2 + 18 + gap

def _wp_saved_lambda_pick_labels(saved_lambdas):
    return (u'—',) + tuple(
        unicode(x.get('name') or u'')
        for x in (saved_lambdas or [])
        if unicode(x.get('name') or u'').strip()
    )

def _wp_saved_lambda_name_for_expr(expr, saved_lambdas):
    ex = unicode(expr or u'').strip()
    if ex == u'':
        return u'—'
    for item in saved_lambdas or ():
        if unicode(item.get('expr') or u'').strip() == ex:
            return unicode(item.get('name') or u'—')
    return u'—'

def _wp_refresh_lambda_pick_combo(ctl, saved_lambdas, expr_text=u''):
    if ctl is None:
        return
    labels = _wp_saved_lambda_pick_labels(saved_lambdas)
    pick_name = _wp_saved_lambda_name_for_expr(expr_text, saved_lambdas)
    try:
        _apply_combo_selection(ctl, labels, select_name=pick_name)
    except Exception:
        try:
            _set_combo_items(ctl, labels, select_text=pick_name)
        except Exception:
            pass

def _wp_lambda_builder_kind_for_field(fid, fn_key=u''):
    """kind конструктора по id поля / fn родительской формы."""
    f = unicode(fid or u'').strip()
    fk = unicode(fn_key or u'').strip()
    if f in (u'row_filter_lambda', u'match_expr', u'RowLambdaEd'):
        return u'rows_predicate'
    if f in (u'new_column_expr',):
        return u'name'
    if f in (u'sheet_name', u'sheet_expr', u'sheet_name_expr'):
        return u'sheets'
    if f in (u'expr', u'replace_expr', u'ComputeLambdaEd'):
        return u'rows_value'
    if fk == u'столбец_по_лямбде' and f == u'expr':
        return u'rows_value'
    return u'rows_value'

def _show_lambda_builder_dialog( parent_dialog, kind=u'rows_value', initial_expr=u'', doc=None, sheet_name=u'', headers=None, saved_lambdas=None, title=None, lock_kind=True):
    """Обёртка → libre_macros_lambda_builder_lib.show_lambda_builder_dialog."""
    try:
        from libre_macros_lambda_builder_lib import show_lambda_builder_dialog as _impl
    except Exception as err:
        _show_message(
            u'Конструктор лямбды недоступен: %s' % err,
            dialog=parent_dialog,
            doc=doc,
        )
        return False, unicode(initial_expr or u'')
    ok, expr = _impl(
        parent_dialog,
        kind=kind,
        initial_expr=initial_expr,
        doc=doc,
        sheet_name=sheet_name,
        headers=headers,
        saved_lambdas=saved_lambdas,
        title=title,
        lock_kind=lock_kind,
    )
    # Обновить список сохранённых у родителя, если менеджер менял его.
    try:
        from libre_macros_lambda_builder_lib import show_lambda_builder_dialog as _impl2

        updated = getattr(_impl2, 'last_saved_lambdas', None)
        if updated is not None and saved_lambdas is not None:
            # мутировать переданный список, если это list
            if isinstance(saved_lambdas, list):
                saved_lambdas[:] = list(updated)
    except Exception:
        pass
    return bool(ok), unicode(expr or u'')

def _show_saved_lambda_manager_dialog(parent_dialog, current_expr, saved_lambdas):
    """
    Сохранить / править / удалить лямбду.
    Возвращает (updated_lambdas, expr_text).
    """
    from libre_macros_wizard_profile_lib import (
        delete_saved_lambda,
        save_named_lambda,
    )

    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 520
    m = 10
    dm.PositionX = 140
    dm.PositionY = 90
    dm.Width = dw
    dm.Height = 400
    dm.Title = u'Сохранённые лямбды'
    _inner_dialog_set_sizeable(dm)
    y = m
    _wizard_dlg_add_fixed(
        dm,
        'HintLbl',
        u'Имя и выражение можно править здесь. «Сохранить» добавляет или обновляет '
        u'запись с этим именем. В списке — уже сохранённые; «Удалить» убирает выбранную.',
        m,
        y,
        dw - m * 2,
        32,
        multiline=True,
    )
    y += 36
    _wizard_dlg_add_fixed(dm, 'NameLbl', u'Имя:', m, y, 40, 14)
    _wizard_dlg_add_edit(dm, 'NameEd', m + 44, y - 2, dw - m * 2 - 44, 18)
    y += 22
    _wizard_dlg_add_fixed(dm, 'ExprLbl', u'Выражение:', m, y, dw - m * 2, 14)
    y += 14
    expr_h = 110
    _wizard_dlg_add_edit(dm, 'ExprEd', m, y, dw - m * 2, expr_h, multiline=True)
    y += expr_h + 8
    _wizard_dlg_add_fixed(dm, 'ListLbl', u'Сохранённые:', m, y, dw - m * 2, 14)
    y += 14
    list_h = 120
    _wizard_dlg_add_listbox(dm, 'ItemsLB', m, y, dw - m * 2, list_h, multiselect=False)
    y += list_h + 8
    _wizard_dlg_add_button(dm, 'SaveBtn', u'Сохранить', m, y, 90, 18)
    _wizard_dlg_add_button(dm, 'DelBtn', u'Удалить', m + 96, y, 80, 18)
    _wizard_dlg_add_button(dm, 'CloseBtn', u'Закрыть', dw - m - 80, y, 80, 18)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, None, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    name_ed = dlg.getControl('NameEd')
    expr_ed = dlg.getControl('ExprEd')
    items_lb = dlg.getControl('ItemsLB')
    state = {'lambdas': list(saved_lambdas or [])}
    loading = {'on': True}

    def _list_labels():
        return [
            u'%s — %s'
            % (
                unicode(x.get('name') or u'?'),
                (unicode(x.get('expr') or u'')[:70] + u'…')
                if len(unicode(x.get('expr') or u'')) > 70
                else unicode(x.get('expr') or u''),
            )
            for x in state['lambdas']
        ]

    def _refresh_list(select_index=None):
        labels = _list_labels()
        try:
            items_lb.Model.StringItemList = tuple(labels)
        except Exception:
            pass
        if select_index is None or len(labels) <= 0:
            return
        try:
            items_lb.selectItemPos(max(0, min(int(select_index), len(labels) - 1)), True)
        except Exception:
            pass

    def _selected_index():
        try:
            pos = items_lb.getSelectedItemPos()
        except Exception:
            pos = -1
        if pos is None:
            return -1
        try:
            idx = int(pos)
        except Exception:
            return -1
        if idx < 0 or idx >= len(state['lambdas']):
            return -1
        return idx

    def _selected_item():
        idx = _selected_index()
        if idx < 0:
            return None
        return state['lambdas'][idx]

    def _expr_text():
        try:
            return unicode(expr_ed.getText() or u'')
        except Exception:
            return u''

    def _name_text():
        try:
            return unicode(name_ed.getText() or u'').strip()
        except Exception:
            return u''

    def _index_by_name(name):
        key = unicode(name or u'').strip().casefold()
        i = 0
        while i < len(state['lambdas']):
            if unicode(state['lambdas'][i].get('name') or u'').strip().casefold() == key:
                return i
            i += 1
        return -1

    def _fill_from_item(item):
        if item is None:
            return
        try:
            name_ed.setText(unicode(item.get('name') or u''))
        except Exception:
            pass
        try:
            expr_ed.setText(unicode(item.get('expr') or u''))
        except Exception:
            pass

    _refresh_list(None)
    init_name = _wp_saved_lambda_name_for_expr(current_expr, state['lambdas'])
    if init_name in (u'—', u'-', u'--', u''):
        init_name = u''
    try:
        name_ed.setText(init_name)
    except Exception:
        pass
    try:
        expr_ed.setText(unicode(current_expr or u''))
    except Exception:
        pass
    if init_name:
        idx0 = _index_by_name(init_name)
        if idx0 >= 0:
            _refresh_list(idx0)

    result = {'lambdas': None, 'expr': unicode(current_expr or u'')}

    class _Handler(unohelper.Base, XActionListener, XItemListener):

        def disposing(self, ev):
            pass

        def actionPerformed(self, ev):
            name = u''
            try:
                name = _wizard_dlg_control_name(ev.Source)
            except Exception:
                name = u''
            if not name:
                try:
                    name = unicode(ev.ActionCommand or u'')
                except Exception:
                    return
            try:
                if name == u'SaveBtn':
                    nm = _name_text()
                    ex = _expr_text().strip()
                    updated, err = save_named_lambda(nm, ex, state['lambdas'])
                    if err:
                        _wp_notify(unicode(err), dialog=dlg, title=u'Сохранённые лямбды')
                        return
                    state['lambdas'] = list(updated)
                    result['lambdas'] = list(updated)
                    result['expr'] = ex
                    sel = _index_by_name(nm)
                    if sel < 0:
                        sel = max(0, len(state['lambdas']) - 1)
                    _refresh_list(sel)
                    try:
                        name_ed.setText(nm)
                    except Exception:
                        pass
                    try:
                        expr_ed.setText(ex)
                    except Exception:
                        pass
                    return
                if name == u'DelBtn':
                    item = _selected_item()
                    nm = unicode((item or {}).get('name') or u'').strip()
                    if nm == u'':
                        nm = _name_text()
                    if nm == u'':
                        _wp_notify(
                            u'Выберите элемент списка или введите имя.',
                            dialog=dlg,
                            title=u'Сохранённые лямбды',
                        )
                        return
                    updated, err = delete_saved_lambda(nm, state['lambdas'])
                    if err:
                        _wp_notify(unicode(err), dialog=dlg, title=u'Сохранённые лямбды')
                        return
                    state['lambdas'] = list(updated)
                    result['lambdas'] = list(updated)
                    _refresh_list(0 if len(state['lambdas']) > 0 else None)
                    nxt = _selected_item()
                    if nxt is not None:
                        _fill_from_item(nxt)
                    else:
                        try:
                            name_ed.setText(u'')
                        except Exception:
                            pass
                        try:
                            expr_ed.setText(u'')
                        except Exception:
                            pass
                    return
                if name == u'CloseBtn':
                    result['lambdas'] = list(state['lambdas'])
                    result['expr'] = _expr_text()
                    try:
                        dlg.endExecute(1)
                    except Exception:
                        try:
                            dlg.endExecute()
                        except Exception:
                            dlg.endDialog(1)
            except Exception as err:
                _wp_notify(unicode(err), dialog=dlg, title=u'Сохранённые лямбды')

        def itemStateChanged(self, ev):
            if loading.get('on'):
                return
            item = _selected_item()
            if item is None:
                return
            _fill_from_item(item)

    handler = _Handler()
    for ctl_name in ('SaveBtn', 'DelBtn', 'CloseBtn'):
        try:
            ctl = dlg.getControl(ctl_name)
            ctl.addActionListener(handler)
            try:
                ctl.setActionCommand(ctl_name)
            except Exception:
                pass
            try:
                ctl.Model.ActionCommand = ctl_name
            except Exception:
                pass
            try:
                ctl.Model.PushButtonType = 0
            except Exception:
                pass
        except Exception:
            pass
    try:
        items_lb.addItemListener(handler)
    except Exception:
        pass
    loading['on'] = False
    try:
        dlg.execute()
    except Exception:
        pass
    lambdas_out = list(state['lambdas'])
    expr_out = result.get('expr')
    if expr_out is None:
        expr_out = _expr_text()
    try:
        dlg.dispose()
    except Exception:
        pass
    return lambdas_out, expr_out

def _sheet_block_form_fields_height(fields, convert_flag=False, fn_key=None):
    total = 0
    for fld in fields or ():
        total += _sheet_block_field_row_height(fld, fn_key=fn_key)
    if convert_flag:
        total += 24
    return total

def _show_sheet_block_form_dialog(parent_dialog, fn_key, initial_text, doc=None, forbid_as_values=False):
    """SheetBlockGrid (форма): блоки по листам + поля из схемы §6.1.

    forbid_as_values — для Постобработка_xml + «применить_формулу»:
    галка «Как значение» сброшена и заблокирована; из JSON as_values убирается.
    """
    from libre_macros_param_codec import param_decode, param_encode
    fn_key = _inner_codec_dialog_effective_key(fn_key)
    forbid_as_values = bool(forbid_as_values)
    schema = _sheet_block_form_schema(fn_key)
    if schema is None:
        return None
    init = unicode(initial_text or u'').strip()
    _pw_dbg(u'=== sheet_block_form open fn=%s forbid_as_values=%s ===' % (fn_key, forbid_as_values))
    _pw_dbg_kv(u'initial_text', init)
    try:
        blocks = param_decode(fn_key, init)
    except Exception as err:
        blocks = []
        _pw_dbg(u'param_decode failed: %s' % unicode(err))
    if _pw_cfg.PARAM_WIZARD_DEBUG:
        try:
            for i, b in enumerate(blocks or []):
                _pw_dbg(u'decoded[%d] repr=%s' % (i, repr(b)))
        except Exception:
            pass
    norm_blocks = [dict(b) for b in blocks if isinstance(b, dict)]
    if forbid_as_values:
        for b in norm_blocks:
            b.pop(u'as_values', None)
    no_sheet_blocks = bool(schema.get('blocks_without_sheet'))
    single_form = bool(schema.get('single_form'))
    is_manual_var_wizard = _is_manual_var_wizard_fn(fn_key)
    if single_form:
        # Один блок без листа: несколько блоков → один (иначе N диалогов при сборе).
        kept = None
        for b in norm_blocks:
            if isinstance(b, dict):
                kept = dict(b)
                break
        if kept is None:
            kept = {'v': 1, 'fn': fn_key}
            for fld in schema.get('fields') or ():
                kept[fld['id']] = _text_to_block_field(fld['id'], fld.get('default'), fld.get('type'))
        _strip_block_sheet_targeting(kept, schema)
        if forbid_as_values:
            kept.pop(u'as_values', None)
        norm_blocks = [kept]
    elif no_sheet_blocks:
        for b in norm_blocks:
            _strip_block_sheet_targeting(b, schema)
    if len(norm_blocks) == 0:
        empty = {'v': 1, 'fn': fn_key}
        for fld in schema.get('fields') or ():
            empty[fld['id']] = _text_to_block_field(fld['id'], fld.get('default'), fld.get('type'))
        if forbid_as_values:
            empty.pop(u'as_values', None)
        if no_sheet_blocks:
            _strip_block_sheet_targeting(empty, schema)
        norm_blocks = [empty]
    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 560 if (not single_form) else 480
    m = 10
    fields = schema.get('fields') or ()
    convert_flag = bool(schema.get('convert_existing'))
    form_bottom_pad = int(schema.get('form_bottom_pad') or 0)
    form_h = _sheet_block_form_fields_height(fields, convert_flag, fn_key=fn_key) + form_bottom_pad
    hint = schema.get('hint') or u''
    hint_lines = int(schema.get('hint_lines') or 2) if hint else 0
    compact_fields = bool(schema.get('compact_fields'))
    if compact_fields:
        hint_h = max(16, min(40, hint_lines * 12 + 4)) if hint else 0
    else:
        hint_h = max(28, min(80, hint_lines * 14 + 6)) if hint else 0
    form_opt_h = 20 if (is_manual_var_wizard and no_sheet_blocks and not single_form) else 0
    y0 = m + (hint_h + (2 if compact_fields else 4) if hint else 0) + form_opt_h
    if single_form:
        list_top = y0
        list_h = 0
        fy_start = y0 + (14 if compact_fields else 16) + 2
        fields_bottom = fy_start + form_h
        left_bottom = fields_bottom
        content_bottom = fields_bottom
        dh_content = content_bottom + 8 + _pw_cfg._INNER_FOOTER_RESERVE + m
        if schema.get('dialog_fit_content'):
            dh = max(fields_bottom + m + _pw_cfg._INNER_FOOTER_RESERVE, 280)
        else:
            dh = max(280, dh_content)
    else:
        # «Параметры» на одной линии с «Одинаково…» (или с «Блоки» без листа); поля сразу под меткой.
        fy_start = y0 + 16 + 2
        list_top = y0 + 22 + 16
        list_h = max(72, min(140 if no_sheet_blocks else 110, form_h + 20))
        fields_bottom = fy_start + form_h
        # без SheetEd Add/Del ближе к списку
        left_extra = 24 if no_sheet_blocks else (40 + 16)
        left_bottom = list_top + list_h + 8 + left_extra
        content_bottom = max(fields_bottom, left_bottom)
        dh_content = content_bottom + 8 + _pw_cfg._INNER_FOOTER_RESERVE + m
        if schema.get('dialog_fit_content'):
            min_footer_y = left_bottom + 6
            dh = max(
                fields_bottom + m + _pw_cfg._INNER_FOOTER_RESERVE,
                min_footer_y + _pw_cfg._INNER_FOOTER_RESERVE + m,
            )
        else:
            dh = max(280, dh_content)
    dm.PositionX = 120
    dm.PositionY = 80
    dm.Width = dw
    dm.Height = dh
    dm.Title = schema.get('title') or fn_key
    _inner_dialog_set_sizeable(dm)
    y = m
    if hint:
        _wizard_dlg_add_fixed(dm, 'HintLbl', hint, m, y, dw - m * 2, hint_h, multiline=True)
        y += hint_h + 4
    if form_opt_h > 0:
        _wizard_dlg_add_checkbox(
            dm,
            'CombinedDialogChk',
            u'Показать все блоки в одном диалоге',
            m,
            y,
            dw - m * 2,
            16,
        )
        y += form_opt_h
    same_all_init = True if single_form else (
        (not no_sheet_blocks)
        and len(norm_blocks) <= 1
        and all((not unicode(b.get('sheet') or u'').strip() for b in norm_blocks))
    )
    col_gap = 0 if single_form else 14
    left_w = 0 if single_form else 176
    right_w = dw - m * 2 - left_w - col_gap
    rx = m + left_w + col_gap
    if not single_form:
        if not no_sheet_blocks:
            _wizard_dlg_add_checkbox(
                dm, 'SameAllChk', u'Одинаково на всех листах', m, y, left_w + col_gap - 4, 16
            )
        _wizard_dlg_add_fixed(dm, 'ParamsLbl', u'Параметры:', rx, y, right_w, 14)
        fy = y + 16 + 2
        y += 22
        _wizard_dlg_add_fixed(dm, 'BlocksLbl', u'Блоки:', m, y, left_w, 14)
        y += 16
        _wizard_dlg_add_listbox(dm, 'BlocksLB', m, y, left_w, list_h, multiselect=False)
    else:
        _wizard_dlg_add_fixed(dm, 'ParamsLbl', u'Параметры:', m, y, right_w, 14)
        y += 16
        fy = y + 2
    field_edits = {}
    field_checks = {}
    field_combos = {}
    field_choices = {}
    field_types = {}
    field_col_pick_btns = {}
    field_col_pick_from_headers = set()
    field_plain_token_picks = set()
    field_header_choice_combos = set()
    field_sheet_choice_combos = set()
    field_lambda_pick_combos = set()
    field_lambda_save_btns = {}
    field_lambda_builder_btns = {}
    fields_by_id = {}
    saved_lambdas_state = [[]]
    try:
        from libre_macros_wizard_profile_lib import (
            ensure_replace_values_default_lambdas,
            load_saved_lambdas,
        )

        if unicode(fn_key or u'').casefold() == u'замена_значений'.casefold():
            saved_lambdas_state[0] = list(ensure_replace_values_default_lambdas())
        else:
            saved_lambdas_state[0] = list(load_saved_lambdas() or [])
    except Exception:
        saved_lambdas_state[0] = []
    for fld in fields:
        fields_by_id[fld['id']] = fld
    for fld in fields:
        fid = fld['id']
        ftype = fld.get('type')
        field_types[fid] = ftype
        # pair_after bool — рисуем вместе с родительским combo
        if ftype == 'bool' and fld.get('pair_after'):
            continue
        row_h = _sheet_block_field_row_height(fld, fn_key=fn_key)
        if row_h <= 0 and ftype == 'bool' and int(fld.get('row_group_slot') or 0) > 0:
            continue
        lbl = fld.get('label') or fid
        if fld.get('row_group'):
            rg_slot = int(fld.get('row_group_slot') or 0)
            if rg_slot > 0:
                continue
            peer = None
            for other in fields:
                if other.get('row_group') == fld.get('row_group') and int(other.get('row_group_slot') or 0) == 1:
                    peer = other
                    break
            rg_gap = 8
            try:
                frac = float(fld.get('row_group_frac'))
            except (TypeError, ValueError):
                frac = 0.5
            if frac <= 0.0 or frac >= 1.0:
                frac = 0.5
            w0 = max(48, int((right_w - rg_gap) * frac))
            w1 = max(60, right_w - rg_gap - w0)
            # если min сдвинул доли — ужать первый, сохранив долю «по возможности»
            if w0 + rg_gap + w1 > right_w:
                w0 = max(48, right_w - rg_gap - w1)

            def _row_group_add_cell(cell_fld, x, w):
                cfid = cell_fld['id']
                cftype = cell_fld.get('type')
                clbl = cell_fld.get('label') or cfid
                field_types[cfid] = cftype
                if cftype == 'bool':
                    _wizard_dlg_add_checkbox(dm, cfid + 'Chk', clbl, x, fy, w, 16)
                    field_checks[cfid] = cfid + 'Chk'
                elif cftype == 'combo':
                    _wizard_dlg_add_fixed(dm, cfid + 'Lbl', clbl, x, fy, w, 12)
                    _wizard_dlg_add_combo(dm, cfid + 'Cb', x, fy + 12, w, 18)
                    field_combos[cfid] = cfid + 'Cb'
                    field_choices[cfid] = tuple(cell_fld.get('choices') or ())
                    if cell_fld.get('choices_from_headers'):
                        field_header_choice_combos.add(cfid)
                    if cell_fld.get('choices_from_sheets'):
                        field_sheet_choice_combos.add(cfid)
                else:
                    _wizard_dlg_add_fixed(dm, cfid + 'Lbl', clbl, x, fy, w, 12)
                    _wizard_dlg_add_edit(dm, cfid + 'Ed', x, fy + 12, w, 18)
                    field_edits[cfid] = cfid + 'Ed'

            _row_group_add_cell(fld, rx, w0)
            if peer is not None:
                _row_group_add_cell(peer, rx + w0 + rg_gap, w1)
            fy += row_h
            continue
        if ftype == 'bool':
            if fn_key == u'градиент' and fid == 'sort':
                sort_cb_w = max(160, right_w - 86)
                _wizard_dlg_add_checkbox(dm, fid + 'Chk', lbl, rx, fy, sort_cb_w, 16)
                field_checks[fid] = fid + 'Chk'
                _wizard_dlg_add_combo(dm, 'sort_dirCb', rx + sort_cb_w + 6, fy - 2, right_w - sort_cb_w - 6, 18)
                field_combos['sort_dir'] = 'sort_dirCb'
            else:
                _wizard_dlg_add_checkbox(dm, fid + 'Chk', lbl, rx, fy, right_w, 16)
                field_checks[fid] = fid + 'Chk'
        elif ftype == 'columns_pick':
            btn_w = 22
            gap = 4
            combo_w = max(80, right_w - 2 * btn_w - 2 * gap)
            _wizard_dlg_add_fixed(dm, fid + 'Lbl', lbl, rx, fy, right_w, 12)
            _wizard_dlg_add_combo(dm, fid + 'Cb', rx, fy + 12, combo_w, 18)
            _wizard_dlg_add_button(dm, fid + 'DelLastBtn', u'×', rx + combo_w + gap, fy + 12, btn_w, 16)
            _wizard_dlg_add_button(dm, fid + 'DelAllBtn', u'××', rx + combo_w + gap + btn_w + gap, fy + 12, btn_w, 16)
            field_combos[fid] = fid + 'Cb'
            field_choices[fid] = tuple(fld.get('choices') or ())
            field_col_pick_btns[fid] = (fid + 'DelLastBtn', fid + 'DelAllBtn')
            # По умолчанию для columns_pick — заголовки листа (если нет явного choices).
            use_headers = fld.get('choices_from_headers')
            if use_headers is None:
                use_headers = not bool(fld.get('choices'))
            if use_headers:
                field_col_pick_from_headers.add(fid)
            if fld.get('plain_tokens') or fid == 'choices':
                field_plain_token_picks.add(fid)
        elif ftype == 'lambda_pick':
            pick_w = min(110, max(80, int(right_w * 0.28)))
            save_w = 52
            build_w = 22
            gap = 3
            edit_w = max(70, right_w - pick_w - save_w - build_w - 3 * gap)
            _wizard_dlg_add_fixed(dm, fid + 'Lbl', lbl, rx, fy, right_w, 12)
            _wizard_dlg_add_combo(dm, fid + 'PickCb', rx, fy + 12, pick_w, 18)
            _wizard_dlg_add_edit(dm, fid + 'Ed', rx + pick_w + gap, fy + 12, edit_w, 18)
            _wizard_dlg_add_button(
                dm, fid + 'SaveBtn', u'Сохранить',
                rx + pick_w + gap + edit_w + gap, fy + 12, save_w, 16,
            )
            _wizard_dlg_add_button(
                dm, fid + 'BuildBtn', u'…',
                rx + pick_w + gap + edit_w + gap + save_w + gap, fy + 12, build_w, 16,
            )
            field_combos[fid] = fid + 'PickCb'
            field_edits[fid] = fid + 'Ed'
            field_lambda_pick_combos.add(fid)
            field_lambda_save_btns[fid] = fid + 'SaveBtn'
            field_lambda_builder_btns[fid] = fid + 'BuildBtn'
            field_choices[fid] = _wp_saved_lambda_pick_labels(saved_lambdas_state[0])
        elif ftype == 'combo':
            if fn_key == u'градиент' and fid == 'sort_dir':
                field_choices[fid] = tuple(fld.get('choices') or ())
                fy += row_h
                continue
            auto_id = fld.get('with_auto_check')
            auto_fld = fields_by_id.get(auto_id) if auto_id else None
            _wizard_dlg_add_fixed(dm, fid + 'Lbl', lbl, rx, fy, right_w, 12)
            if auto_fld is not None:
                combo_w = max(120, int(right_w * 0.52))
                chk_w = max(100, right_w - combo_w - 6)
                _wizard_dlg_add_combo(dm, fid + 'Cb', rx, fy + 12, combo_w, 18)
                field_combos[fid] = fid + 'Cb'
                field_choices[fid] = tuple(fld.get('choices') or ())
                _wizard_dlg_add_checkbox(dm, auto_id + 'Chk', auto_fld.get('label') or auto_id, rx + combo_w + 6, fy + 14, chk_w, 16)
                field_checks[auto_id] = auto_id + 'Chk'
                field_types[auto_id] = 'bool'
            else:
                _wizard_dlg_add_combo(dm, fid + 'Cb', rx, fy + 12, right_w, 18)
                field_combos[fid] = fid + 'Cb'
                field_choices[fid] = tuple(fld.get('choices') or ())
            if fld.get('choices_from_headers'):
                field_header_choice_combos.add(fid)
            if fld.get('choices_from_sheets'):
                field_sheet_choice_combos.add(fid)
        else:
            edit_h = 36 if fld.get('tall') else 18
            bool_id = fld.get('with_bool_check')
            bool_fld = fields_by_id.get(bool_id) if bool_id else None
            _wizard_dlg_add_fixed(dm, fid + 'Lbl', lbl, rx, fy, right_w, 12)
            if bool_fld is not None:
                try:
                    frac = float(fld.get('edit_frac') or 0.32)
                except (TypeError, ValueError):
                    frac = 0.32
                if frac < 0.2:
                    frac = 0.2
                if frac > 0.6:
                    frac = 0.6
                edit_w = max(56, int(right_w * frac))
                chk_w = max(90, right_w - edit_w - 6)
                _wizard_dlg_add_edit(dm, fid + 'Ed', rx, fy + 12, edit_w, edit_h)
                field_edits[fid] = fid + 'Ed'
                _wizard_dlg_add_checkbox(dm, bool_id + 'Chk', bool_fld.get('label') or bool_id, rx + edit_w + 6, fy + 14, chk_w, 16)
                field_checks[bool_id] = bool_id + 'Chk'
                field_types[bool_id] = 'bool'
            else:
                _wizard_dlg_add_edit(dm, fid + 'Ed', rx, fy + 12, right_w, edit_h)
                field_edits[fid] = fid + 'Ed'
        fy += row_h
    if fn_key in (u'формат_даты', u'формат_деньги', u'применить_формулу', u'добавить_столбец') and field_combos.get('format'):
        gs_lib = _wp_import_global_settings_lib()
        if gs_lib:
            blank = u'(глобальный)'
            if fn_key in (u'формат_деньги', u'применить_формулу'):
                calc_fn = gs_lib.get('calc_number_format_choices')
                if calc_fn is not None:
                    base = (blank,) + tuple(calc_fn())
                else:
                    base = (blank,) + tuple(gs_lib['NUMBER_FORMAT_CHOICES'])
            elif fn_key == u'добавить_столбец':
                # стартовый набор — числа; синк по типу данных обновит
                calc_fn = gs_lib.get('calc_number_format_choices')
                if calc_fn is not None:
                    base = (blank, u'@') + tuple(calc_fn())
                else:
                    base = (blank, u'@') + tuple(gs_lib['NUMBER_FORMAT_CHOICES'])
            else:
                base = (blank,) + tuple(gs_lib['DATE_FORMAT_CHOICES'])
            extra = []
            seen = set((unicode(x).strip().casefold() for x in base))
            for b in norm_blocks:
                fmt = unicode((b or {}).get('format') or u'').strip()
                if fmt == u'' or fmt.casefold() == blank.casefold():
                    continue
                if fmt.casefold() not in seen:
                    seen.add(fmt.casefold())
                    extra.append(fmt)
            field_choices['format'] = base + tuple(extra)
    if convert_flag:
        conv_lbl = schema.get('convert_label') or u'Конвертировать текст в число/дату перед форматом'
        _wizard_dlg_add_checkbox(dm, 'ConvertChk', conv_lbl, rx, fy, right_w, 16)
    if not single_form:
        y2 = y + list_h + 8
        if not no_sheet_blocks:
            _wizard_dlg_add_fixed(dm, 'SheetLbl', u'Лист (пусто = все листы):', m, y2, left_w, 14)
            _wizard_dlg_add_combo(dm, 'SheetEd', m, y2 + 16, left_w, 18)
            _wizard_dlg_add_button(dm, 'AddBlockBtn', u'+ Блок', m, y2 + 40, 80, 16)
            _wizard_dlg_add_button(dm, 'DelBlockBtn', u'Удалить', m + 90, y2 + 40, 80, 16)
        else:
            _wizard_dlg_add_button(dm, 'AddBlockBtn', u'+ Блок', m, y2, 80, 16)
            _wizard_dlg_add_button(dm, 'DelBlockBtn', u'Удалить', m + 90, y2, 80, 16)
    actual_fields_end = fy + (24 if convert_flag else 0)
    need_dh = actual_fields_end + 8 + _pw_cfg._INNER_FOOTER_RESERVE + m
    if int(need_dh) > int(dh):
        dh = int(need_dh)
        dm.Height = dh
    footer_btn_h = 30 if single_form else None
    footer_btn_w = 110 if single_form else int(_pw_cfg._INNER_BTN_W)
    if single_form and footer_btn_h:
        # Запас под более высокие OK/Отмена.
        try:
            extra = int(footer_btn_h) - int(_pw_cfg._INNER_BTN_H)
        except Exception:
            extra = 14
        if extra > 0:
            dm.Height = int(dm.Height) + extra
            dh = int(dm.Height)
    _inner_dialog_add_footer(dm, m, dh, btn_h=footer_btn_h, btn_w=footer_btn_w, help_btn=True, dw=dw, help_key=fn_key)
    if unicode(fn_key or u'').casefold() == u'применить_формулу'.casefold():
        _wizard_apply_soft_gray_theme(dm, title_text=schema.get('title') or fn_key)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    _wizard_wire_help_button(dlg, doc=doc, help_key=fn_key)

    if unicode(fn_key or u'').casefold() == u'применить_формулу'.casefold():
        _wizard_try_paint_titlebar(dlg)
    blocks_lb = None
    sheet_ed = None
    if not single_form:
        blocks_lb = dlg.getControl('BlocksLB')
        sheet_ed = dlg.getControl('SheetEd')
    edits = {fid: dlg.getControl(name) for fid, name in field_edits.items()}
    checks = {fid: dlg.getControl(name) for fid, name in field_checks.items()}
    combos = {fid: dlg.getControl(name) for fid, name in field_combos.items()}
    lambda_save_btns = {}
    for fid, btn_name in field_lambda_save_btns.items():
        try:
            lambda_save_btns[fid] = dlg.getControl(btn_name)
        except Exception:
            lambda_save_btns[fid] = None
    lambda_builder_btns = {}
    for fid, btn_name in field_lambda_builder_btns.items():
        try:
            lambda_builder_btns[fid] = dlg.getControl(btn_name)
        except Exception:
            lambda_builder_btns[fid] = None

    def _refresh_saved_lambda_combos(expr_by_fid=None):
        expr_by_fid = expr_by_fid or {}
        for fid in field_lambda_pick_combos:
            field_choices[fid] = _wp_saved_lambda_pick_labels(saved_lambdas_state[0])
            pick_ctl = combos.get(fid)
            edit_ctl = edits.get(fid)
            ex = expr_by_fid.get(fid)
            if ex is None and edit_ctl is not None:
                try:
                    ex = unicode(edit_ctl.getText() or u'')
                except Exception:
                    ex = u''
            _wp_refresh_lambda_pick_combo(pick_ctl, saved_lambdas_state[0], ex)

    def _lambda_pick_apply_name(fid, name):
        if fid not in field_lambda_pick_combos:
            return
        nm = unicode(name or u'').strip()
        if nm in (u'', u'—'):
            return
        try:
            from libre_macros_wizard_profile_lib import saved_lambda_expr_by_name

            ex = saved_lambda_expr_by_name(nm, saved_lambdas_state[0])
        except Exception:
            ex = u''
        if ex == u'':
            return
        edit_ctl = edits.get(fid)
        if edit_ctl is not None:
            try:
                edit_ctl.setText(ex)
            except Exception:
                pass

    def _set_form_ctl_enabled(ctl, enabled):
        if ctl is None:
            return
        try:
            ctl.setEnable(bool(enabled))
        except Exception:
            try:
                ctl.Model.Enabled = bool(enabled)
            except Exception:
                pass

    def _match_pick_code_from_ui():
        ctl = combos.get(u'match_pick')
        if ctl is None:
            return u'all'
        try:
            raw = _combo_control_text(ctl)
        except Exception:
            raw = u''
        t = unicode(raw or u'').strip().casefold()
        code = _pw_cfg.REPLACE_MATCH_PICK_CODE.get(t, t)
        if code in _pw_cfg.REPLACE_MATCH_PICK_LABEL:
            return code
        return u'all'

    def _sync_match_expr_lambda_ui():
        if u'match_expr' not in field_lambda_pick_combos:
            return
        on = _match_pick_code_from_ui() == u'lambda'
        pick_ctl = combos.get(u'match_expr')
        edit_ctl = edits.get(u'match_expr')
        save_ctl = lambda_save_btns.get(u'match_expr')
        lbl_ctl = None
        try:
            lbl_ctl = dlg.getControl(u'match_exprLbl')
        except Exception:
            lbl_ctl = None
        _set_form_ctl_enabled(pick_ctl, on)
        _set_form_ctl_enabled(edit_ctl, on)
        _set_form_ctl_enabled(save_ctl, on)
        _set_form_ctl_enabled(lambda_builder_btns.get(u'match_expr'), on)
        _set_form_ctl_enabled(lbl_ctl, on)
        if on:
            _wp_refresh_lambda_pick_combo(
                pick_ctl,
                saved_lambdas_state[0],
                unicode(edit_ctl.getText() or u'') if edit_ctl is not None else u'',
            )
            return
        if edit_ctl is not None:
            try:
                edit_ctl.setText(u'')
            except Exception:
                pass
        _wp_refresh_lambda_pick_combo(pick_ctl, saved_lambdas_state[0], u'')

    def _replace_mode_code_from_ui():
        ctl = combos.get(u'replace_mode')
        if ctl is None:
            return u'manual'
        try:
            raw = _combo_control_text(ctl)
        except Exception:
            raw = u''
        t = unicode(raw or u'').strip().casefold()
        code = _pw_cfg.REPLACE_MODE_CODE.get(t, t)
        if code in _pw_cfg.REPLACE_MODE_LABEL:
            return code
        return u'manual'

    def _sync_replace_mode_ui():
        if unicode(fn_key or u'').casefold() not in (
            u'замена_значений'.casefold(),
            u'replace_values'.casefold(),
        ):
            return
        mode = _replace_mode_code_from_ui()
        is_lambda = mode == u'lambda'
        # manual edit «replace»
        repl_ed = edits.get(u'replace')
        repl_lbl = None
        try:
            repl_lbl = dlg.getControl(u'replaceLbl')
        except Exception:
            repl_lbl = None
        _set_form_ctl_enabled(repl_ed, not is_lambda)
        _set_form_ctl_enabled(repl_lbl, not is_lambda)
        # lambda_pick replace_expr
        if u'replace_expr' in field_lambda_pick_combos:
            pick_ctl = combos.get(u'replace_expr')
            edit_ctl = edits.get(u'replace_expr')
            save_ctl = lambda_save_btns.get(u'replace_expr')
            lbl_ctl = None
            try:
                lbl_ctl = dlg.getControl(u'replace_exprLbl')
            except Exception:
                lbl_ctl = None
            _set_form_ctl_enabled(pick_ctl, is_lambda)
            _set_form_ctl_enabled(edit_ctl, is_lambda)
            _set_form_ctl_enabled(save_ctl, is_lambda)
            _set_form_ctl_enabled(lambda_builder_btns.get(u'replace_expr'), is_lambda)
            _set_form_ctl_enabled(lbl_ctl, is_lambda)
            if is_lambda:
                _wp_refresh_lambda_pick_combo(
                    pick_ctl,
                    saved_lambdas_state[0],
                    unicode(edit_ctl.getText() or u'') if edit_ctl is not None else u'',
                )
            else:
                if edit_ctl is not None:
                    try:
                        edit_ctl.setText(u'')
                    except Exception:
                        pass
                _wp_refresh_lambda_pick_combo(pick_ctl, saved_lambdas_state[0], u'')

    def _sync_manual_var_remember_ui():
        if unicode(fn_key or u'').casefold() not in (
            u'ручной_ввод_в_карту_переменных'.casefold(),
            u'ручной_ввод'.casefold(),
            u'manual_variable_input'.casefold(),
            u'Ручной_ввод_в_карту_переменных'.casefold(),
        ):
            return
        rem_ctl = checks.get(u'remember_last')
        enc_ctl = checks.get(u'encrypt_last')
        if enc_ctl is None:
            return
        on = True
        if rem_ctl is not None:
            try:
                on = bool(rem_ctl.getState())
            except Exception:
                on = True
        _set_form_ctl_enabled(enc_ctl, on)
        if not on:
            try:
                enc_ctl.setState(0)
            except Exception:
                pass

    def _create_sheet_name_mode_from_ui():
        ctl = combos.get(u'name_mode')
        if ctl is None:
            return u'manual'
        try:
            raw = _combo_control_text(ctl)
        except Exception:
            raw = u''
        return _text_to_block_field(u'name_mode', raw, u'combo') or u'manual'

    def _sync_create_sheet_name_ui():
        if unicode(fn_key or u'').casefold() not in (
            u'создать_лист'.casefold(),
            u'create_sheet'.casefold(),
        ):
            return
        if u'sheet_name' not in field_lambda_pick_combos and u'sheet_name' not in edits:
            return
        mode = unicode(_create_sheet_name_mode_from_ui() or u'manual').casefold()
        is_expr = mode == u'expr'
        lbl = u'Лямбда выражения' if is_expr else u'Имя вручную'
        try:
            lbl_ctl = dlg.getControl(u'sheet_nameLbl')
            lbl_ctl.Model.Label = lbl
        except Exception:
            try:
                lbl_ctl = dlg.getControl(u'sheet_nameLbl')
                lbl_ctl.setText(lbl)
            except Exception:
                pass
        pick_ctl = combos.get(u'sheet_name')
