    def _sync_create_sheet_data_ui():
        if unicode(fn_key or u'').casefold() not in (
            u'создать_лист'.casefold(),
            u'create_sheet'.casefold(),
        ):
            return
        mode = unicode(_create_sheet_data_mode_from_ui() or u'none').casefold()
        is_sheet = mode == u'sheet'
        is_rows = mode == u'rows'
        for name, on in (
            (u'source_sheet', is_sheet),
            (u'source_sheetLbl', is_sheet),
            (u'source_sheetCb', is_sheet),
            (u'source_range', is_sheet),
            (u'source_rangeLbl', is_sheet),
            (u'source_rangeEd', is_sheet),
            (u'values_only', is_sheet),
            (u'values_onlyChk', is_sheet),
            (u'rows', is_rows),
            (u'rowsLbl', is_rows),
            (u'rowsEd', is_rows),
        ):
            try:
                _set_form_ctl_enabled(dlg.getControl(name), on)
            except Exception:
                pass
        # Также через maps
        _set_form_ctl_enabled(combos.get(u'source_sheet'), is_sheet)
        _set_form_ctl_enabled(edits.get(u'source_range'), is_sheet)
        _set_form_ctl_enabled(checks.get(u'values_only'), is_sheet)
        _set_form_ctl_enabled(edits.get(u'rows'), is_rows)

