    def _refresh_columns_pick_choices():
        if not field_col_pick_btns:
            return
        sheet_name = u''
        try:
            sheet_name = _inner_dialog_sheet_text(sheet_ed)
        except Exception:
            sheet_name = u''
        names = []
        try:
            if sheet_name:
                names = _wp_list_sheet_header_columns(doc, sheet_name)
            if not names and doc is not None:
                try:
                    active = doc.getCurrentController().getActiveSheet()
                    nm = unicode(getattr(active, 'Name', u'') or u'')
                    if nm:
                        names = _wp_list_sheet_header_columns(doc, nm)
                except Exception:
                    pass
            if not names:
                for sn in _pivot_list_doc_sheet_names(doc) or []:
                    names = _wp_list_sheet_header_columns(doc, sn)
                    if names:
                        break
        except Exception:
            names = []
        names_t = tuple(names)
        for fid in field_col_pick_btns:
            if fid in field_col_pick_from_headers:
                names_t = tuple(names)
            else:
                fld = fields_by_id.get(fid) or {}
                names_t = tuple(fld.get('choices') or ())
            field_choices[fid] = names_t
            ctl = combos.get(fid)
            if ctl is None:
                continue
            if fid in columns_acc:
                cur = columns_acc[fid][0]
            else:
                cur = u''
                try:
                    cur = _combo_edit_text(ctl)
                except Exception:
                    cur = u''
            try:
                columns_pick_guard[0] = True
                # Не через _set_combo_items: при select_text='' оно подставляет первый пункт списка.
                try:
                    ctl.Model.StringItemList = names_t
                except Exception:
                    pass
                _set_combo_edit_text(ctl, cur)
            except Exception:
                pass
            finally:
                columns_pick_guard[0] = False

    def _columns_pick_parts_from_text(text, fid=None):
        known = field_choices.get(fid) if fid else None
        try:
            from libre_macros_param_codec import split_column_name_tokens
            parts = split_column_name_tokens(text, known_names=known)
        except Exception:
            parts = []
        if not parts:
            for chunk in re.split(u'[,;]', unicode(text or u'')):
                t = unicode(chunk or u'').strip()
                if t != u'':
                    parts.append(t)
        seen = set()
        out = []
        for t in parts:
            k = t.casefold()
            if k in seen:
                continue
            seen.add(k)
            out.append(t)
        return out

    def _columns_pick_remember_sep(fid, text=None, parts=None):
        """Выбрать и запомнить разделитель по тексту / токенам / known headers."""
        known = field_choices.get(fid) or ()
        raw = unicode(text if text is not None else columns_acc.get(fid, [u''])[0] or u'')
        try:
            from libre_macros_param_codec import detect_column_name_list_sep
            sep = detect_column_name_list_sep(raw, known_names=known)
        except Exception:
            sep = u';' if u';' in raw else u','
        toks = parts if parts is not None else _columns_pick_parts_from_text(raw, fid=fid)
        if any(u',' in unicode(t) for t in toks):
            sep = u';'
        # Уже зафиксированный «;» не откатываем на «,» (пока поле не очищено).
        prev = columns_sep.get(fid)
        if prev == u';' and unicode(raw or u'').strip() != u'':
            sep = u';'
        columns_sep[fid] = sep
        return sep

    def _columns_pick_join_parts(parts, fid=None):
        sep = columns_sep.get(fid) if fid else None
        try:
            from libre_macros_param_codec import join_column_name_tokens
            return join_column_name_tokens(parts, sep=sep)
        except Exception:
            use = sep if sep in (u',', u';') else u','
            return use.join(parts)

    def _columns_pick_set_text(fid, parts):
        ctl = combos.get(fid)
        if ctl is None:
            return
        if any(u',' in unicode(p) for p in parts or ()):
            columns_sep[fid] = u';'
        text = _columns_pick_join_parts(parts, fid=fid)
        if fid in columns_acc:
            columns_acc[fid][0] = text
        try:
            columns_pick_guard[0] = True
            _set_combo_edit_text(ctl, text)
        except Exception:
            pass
        finally:
            columns_pick_guard[0] = False

    def _columns_pick_sync_from_acc(fid):
        ctl = combos.get(fid)
        if ctl is None:
            return
        acc = columns_acc.get(fid, [u''])[0] if fid in columns_acc else u''
        _columns_pick_remember_sep(fid, text=acc)
        try:
            columns_pick_guard[0] = True
            try:
                ctl.Model.StringItemList = tuple(field_choices.get(fid) or ())
            except Exception:
                pass
            _set_combo_edit_text(ctl, acc)
        except Exception:
            pass
        finally:
            columns_pick_guard[0] = False

    def _columns_pick_control_name(control):
        try:
            return unicode(control.getModel().Name)
        except Exception:
            try:
                return unicode(control.Model.Name)
            except Exception:
                return u''

    def _columns_pick_fid_for_control(control):
        """Сопоставить combo с полем columns_pick (по имени модели; is/== для AO)."""
        if control is None:
            return None
        name = _columns_pick_control_name(control)
        for cp_fid in field_col_pick_btns:
            expect = cp_fid + u'Cb'
            if name == expect:
                return cp_fid
            ctl = combos.get(cp_fid)
            if ctl is None:
                continue
            if control is ctl or control == ctl:
                return cp_fid
        return None

    def _columns_pick_dropdown_token(control, items, ev=None):
        pos = -1
        if ev is not None:
            try:
                pos = int(ev.Selected)
            except Exception:
                pos = -1
            if pos < 0:
                try:
                    pos = int(getattr(ev, 'Selected', -1))
                except Exception:
                    pos = -1
        if pos < 0:
            try:
                p = control.getSelectedItemPos()
                if p is not None:
                    pos = int(p)
            except Exception:
                pos = -1
        seq = items or ()
        if pos >= 0 and pos < len(seq):
            return unicode(seq[pos]).strip()
        try:
            seq2 = control.Model.StringItemList or ()
            if pos >= 0 and pos < len(seq2):
                return unicode(seq2[pos]).strip()
        except Exception:
            pass
        return u''

    def _columns_pick_is_single_dropdown_item(text, items):
        cur = unicode(text or u'').strip()
        if cur == u'':
            return u''
        try:
            from libre_macros_param_codec import (
                split_column_name_tokens,
                unwrap_column_name_token,
            )
            parts = split_column_name_tokens(cur, known_names=tuple(items or ()))
            if len(parts) == 1:
                bare = unwrap_column_name_token(parts[0])[0]
                bare_cf = bare.casefold()
                for it in items or ():
                    if unicode(it).strip().casefold() == bare_cf:
                        return unicode(it).strip()
        except Exception:
            pass
        cur_cf = cur.casefold()
        for it in items or ():
            if unicode(it).strip().casefold() == cur_cf:
                return unicode(it).strip()
        if u',' in cur or u';' in cur:
            return u''
        return u''

    def _columns_pick_handle_select(cp_fid, token):
        """Накопить токен из списка и обновить блок/подпись слева."""
        if not token:
            return False
        if not _columns_pick_append_token(cp_fid, token):
            return False
        bi = form_block_index[0]
        if bi < 0:
            return True
        _apply_form_to_block(bi)
        form_loading[0] = True
        try:
            _inner_dialog_update_blocks_list_label(
                blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
            )
        finally:
            form_loading[0] = False
        return True

    def _columns_pick_handle_text(cp_fid, control):
        """textChanged для columns_pick: накопление или ручной ввод."""
        if columns_pick_guard[0] or form_loading[0]:
            return
        cur = _combo_edit_text(control)
        if u',' in cur or u';' in cur:
            items = field_choices.get(cp_fid) or ()
            picked = _columns_pick_is_single_dropdown_item(cur, items)
            if not picked:
                try:
                    picked = _columns_pick_is_single_dropdown_item(
                        cur, control.Model.StringItemList or ()
                    )
                except Exception:
                    picked = u''
            if picked:
                acc = columns_acc.get(cp_fid, [u''])[0]
                same = False
                try:
                    from libre_macros_param_codec import (
                        split_column_name_tokens,
                        unwrap_column_name_token,
                    )
                    parts = split_column_name_tokens(acc)
                    if len(parts) == 1:
                        same = (
                            unwrap_column_name_token(parts[0])[0].casefold()
                            == picked.casefold()
                        )
                except Exception:
                    same = False
                if not same:
                    same = picked.casefold() == unicode(acc or u'').casefold()
                if not same:
                    _columns_pick_handle_select(cp_fid, picked)
                else:
                    columns_acc[cp_fid][0] = cur
                    _columns_pick_remember_sep(cp_fid, text=cur)
                    bi = form_block_index[0]
                    if bi >= 0:
                        _apply_form_to_block(bi)
                        form_loading[0] = True
                        try:
                            _inner_dialog_update_blocks_list_label(
                                blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
                            )
                        finally:
                            form_loading[0] = False
                return
            columns_acc[cp_fid][0] = cur
            _columns_pick_remember_sep(cp_fid, text=cur)
            bi = form_block_index[0]
            if bi >= 0:
                _apply_form_to_block(bi)
                form_loading[0] = True
                try:
                    _inner_dialog_update_blocks_list_label(
                        blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
                    )
                finally:
                    form_loading[0] = False
            return
        items = field_choices.get(cp_fid) or ()
        picked = _columns_pick_is_single_dropdown_item(cur, items)
        if not picked:
            try:
                picked = _columns_pick_is_single_dropdown_item(
                    cur, control.Model.StringItemList or ()
                )
            except Exception:
                picked = u''
        if picked:
            # Выбор из списка подменил CSV одним пунктом — дописать, если это не весь acc.
            acc = columns_acc.get(cp_fid, [u''])[0]
            same = False
            try:
                from libre_macros_param_codec import (
                    split_column_name_tokens,
                    unwrap_column_name_token,
                )
                parts = split_column_name_tokens(acc)
                if len(parts) == 1:
                    same = (
                        unwrap_column_name_token(parts[0])[0].casefold()
                        == picked.casefold()
                    )
            except Exception:
                same = False
            if not same:
                same = picked.casefold() == unicode(acc or u'').casefold()
            if not same:
                _columns_pick_handle_select(cp_fid, picked)
            else:
                # Тот же одиночный пункт уже в acc — всё равно синхронизировать блок/подпись.
                bi = form_block_index[0]
                if bi >= 0:
                    _apply_form_to_block(bi)
                    form_loading[0] = True
                    try:
                        _inner_dialog_update_blocks_list_label(
                            blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
                        )
                    finally:
                        form_loading[0] = False
            return
        columns_acc[cp_fid][0] = cur
        _columns_pick_remember_sep(cp_fid, text=cur)
        bi = form_block_index[0]
        if bi >= 0:
            _apply_form_to_block(bi)
            form_loading[0] = True
            try:
                _inner_dialog_update_blocks_list_label(
                    blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
                )
            finally:
                form_loading[0] = False

    def _columns_pick_append_token(fid, token):
        if fid not in columns_acc or columns_pick_guard[0] or form_loading[0]:
            return False
        token = unicode(token or u'').strip()
        if token == u'':
            return False
        ctl = combos.get(fid)
        if ctl is None:
            return False
        # Выбор из списка заголовков → 'имя' (exact); new/new_names/choices — без кавычек.
        exact_from_list = fid not in ('new', 'new_names', 'choices')
        if fid in field_plain_token_picks:
            exact_from_list = False
        try:
            from libre_macros_param_codec import append_column_name_token
            merged, sep = append_column_name_token(
                columns_acc[fid][0],
                token,
                sep=columns_sep.get(fid),
                known_names=field_choices.get(fid) or (),
                exact=exact_from_list,
            )
        except Exception:
            if exact_from_list:
                try:
                    from libre_macros_param_codec import wrap_column_name_token_exact
                    token = wrap_column_name_token_exact(token)
                except Exception:
                    pass
            merged = _append_csv_token_no_dup(columns_acc[fid][0], token)
            sep = u';' if (u';' in merged or u',' in token) else u','
        columns_acc[fid][0] = merged
        columns_sep[fid] = sep
        columns_pick_guard[0] = True
        try:
            _set_combo_edit_text(ctl, merged)
        finally:
            columns_pick_guard[0] = False
        return True

    def _columns_pick_del_last(fid):
        if fid in columns_acc:
            parts = _columns_pick_parts_from_text(columns_acc[fid][0], fid=fid)
            if parts:
                parts = parts[:-1]
            if not parts:
                columns_sep[fid] = u','
            columns_acc[fid][0] = _columns_pick_join_parts(parts, fid=fid)
            _columns_pick_sync_from_acc(fid)
            return
        ctl = combos.get(fid)
        if ctl is None:
            return
        try:
            cur = _combo_control_text(ctl)
        except Exception:
            cur = u''
        parts = _columns_pick_parts_from_text(cur, fid=fid)
        if parts:
            parts = parts[:-1]
        if not parts:
            columns_sep[fid] = u','
        _columns_pick_set_text(fid, parts)

    def _columns_pick_del_all(fid):
        columns_sep[fid] = u','
        if fid in columns_acc:
            columns_acc[fid][0] = u''
            _columns_pick_sync_from_acc(fid)
            return
        _columns_pick_set_text(fid, [])

    convert_chk = dlg.getControl('ConvertChk') if convert_flag else None
    combined_dialog_chk = dlg.getControl('CombinedDialogChk') if form_opt_h > 0 else None
    if combined_dialog_chk is not None and len(norm_blocks) > 0:
        try:
            combined_dialog_chk.setState(
                1 if bool((norm_blocks[0] or {}).get(u'combined_dialog')) else 0
            )
        except Exception:
            pass
    same_all_chk = None if (single_form or no_sheet_blocks) else dlg.getControl('SameAllChk')
    doc_sheet_names = _pivot_list_doc_sheet_names(doc)
    if (not single_form) and (not no_sheet_blocks) and len(doc_sheet_names) > 0 and sheet_ed is not None:
        try:
            _set_combo_items(sheet_ed, doc_sheet_names, select_text=u'')
        except Exception:
            pass
    if same_all_chk is not None:
        try:
            same_all_chk.setState(1 if same_all_init else 0)
        except Exception:
            pass
    try:
        dlg.getControl('JsonChk').setState(1)
    except Exception:
        pass
    form_block_index = [-1]
    sheet_field_guard = [False]
    form_loading = [False]

    def _sync_forbid_as_values_ui():
        """Постобработка_xml: as_values для «применить_формулу» выключен и недоступен."""
        if not forbid_as_values:
            return
        ctl = checks.get(u'as_values')
        if ctl is None:
            return
        try:
            ctl.setState(0)
        except Exception:
            pass
        try:
            ctl.Model.Enabled = False
        except Exception:
            try:
                ctl.setEnable(False)
            except Exception:
                pass
        try:
            ctl.Model.Label = u'Как значение (в Постобработка_xml недоступно)'
        except Exception:
            pass

    def _strip_forbid_as_values(blocks):
        if not forbid_as_values:
            return
        for b in blocks or []:
            if isinstance(b, dict):
                b.pop(u'as_values', None)

    def _refresh_blocks(selected_index=0):
        if single_form or blocks_lb is None:
            return
        form_loading[0] = True
        items = [_sheet_block_form_label(b, schema) for b in norm_blocks]
        try:
            blocks_lb.Model.StringItemList = tuple(items)
        except Exception:
            pass
        try:
            if len(items) > 0:
                blocks_lb.selectItemPos(max(0, min(selected_index, len(items) - 1)), True)
        except Exception:
            pass
        form_loading[0] = False

    def _block_index_selected():
        if single_form or blocks_lb is None:
            return 0 if len(norm_blocks) > 0 else -1
        try:
            pos = blocks_lb.getSelectedItemPos()
            return int(pos) if pos is not None else -1
        except Exception:
            return -1

    def _load_block_to_form(block_index):
        form_loading[0] = True
        form_block_index[0] = block_index
        if block_index < 0 or block_index >= len(norm_blocks):
            if sheet_ed is not None:
                _inner_dialog_set_sheet_field_text(sheet_ed, u'', sheet_field_guard)
            for fid, ctl in edits.items():
                try:
                    ctl.setText(u'')
                except Exception:
                    pass
            for fid, ctl in combos.items():
                try:
                    _set_combo_items(ctl, field_choices.get(fid) or (), select_text=u'')
                except Exception:
                    pass
            for fid, ctl in checks.items():
                try:
                    ctl.setState(0)
                except Exception:
                    pass
            if convert_chk is not None:
                try:
                    convert_chk.setState(0)
                except Exception:
                    pass
            _sync_delete_rows_mode_fields(
                fn_key, edits, combos, u'columns',
                col_pick_del_last=col_pick_del_last,
                col_pick_del_all=col_pick_del_all,
            )
            if field_lambda_pick_combos:
                _refresh_saved_lambda_combos({})
            _sync_match_expr_lambda_ui()
            _sync_replace_mode_ui()
            _sync_manual_var_remember_ui()
            _sync_add_column_type_ui()
            _sync_create_sheet_name_ui()
            _sync_create_sheet_data_ui()
            if forbid_as_values:
                _sync_forbid_as_values_ui()
            form_loading[0] = False
            return
        b = norm_blocks[block_index]
        _pw_dbg(u'_load_block_to_form idx=%s roles=%s' % (block_index, repr(b.get('roles'))))
        if sheet_ed is not None:
            _inner_dialog_set_sheet_field_text(sheet_ed, unicode(b.get('sheet') or u'').strip(), sheet_field_guard)
        _refresh_header_choice_combos()
        for fid, ctl in edits.items():
            try:
                field_text = _block_field_to_text(b, fid, fn_key=fn_key)
                ctl.setText(field_text)
                _pw_dbg(u'  field %s -> %r' % (fid, field_text))
            except Exception:
                pass
        for fid, ctl in combos.items():
            if fid in field_lambda_pick_combos:
                continue
            try:
                field_text = _block_field_to_text(b, fid, fn_key=fn_key)
                if fid in columns_acc:
                    columns_acc[fid][0] = field_text
                    _columns_pick_remember_sep(fid, text=field_text)
                    # Если в токенах есть запятая — пересобрать через «;».
                    parts = _columns_pick_parts_from_text(field_text, fid=fid)
                    if len(parts) > 1 and columns_sep.get(fid) == u';':
                        rebuilt = _columns_pick_join_parts(parts, fid=fid)
                        columns_acc[fid][0] = rebuilt
                    _columns_pick_sync_from_acc(fid)
                else:
                    _apply_combo_selection(ctl, field_choices.get(fid) or (), select_name=field_text)
                _pw_dbg(u'  combo %s -> %r' % (fid, field_text))
            except Exception:
                pass
        for fid, ctl in checks.items():
            try:
                if forbid_as_values and fid == u'as_values':
                    ctl.setState(0)
                else:
                    ctl.setState(1 if b.get(fid) else 0)
            except Exception:
                pass
        if forbid_as_values:
            _sync_forbid_as_values_ui()
        if fn_key == u'градиент':
            try:
                sort_on = bool(b.get('sort'))
            except Exception:
                sort_on = False
            try:
                if combos.get('sort_dir') is not None:
                    combos['sort_dir'].setEnable(bool(sort_on))
            except Exception:
                try:
                    combos['sort_dir'].Model.Enabled = bool(sort_on)
                except Exception:
                    pass
        if convert_chk is not None:
            try:
                convert_chk.setState(1 if b.get('convert_existing') else 0)
            except Exception:
                pass
        if fn_key == u'заголовок_плюс_высота' or _threshold_fn():
            fc = unicode(b.get('font_color') or u'').strip()
            auto_ctl = checks.get('font_color_auto')
            if auto_ctl is not None:
                try:
                    if fc:
                        auto_ctl.setState(0)
                    else:
                        auto_ctl.setState(1 if b.get('font_color_auto', True) else 0)
                except Exception:
                    pass
        if _has_columns_pick():
            _refresh_columns_pick_choices()
        _refresh_sheet_choice_combos()
        _refresh_header_choice_combos()
        if unicode(fn_key or u'').casefold() in (u'удаление_строк'.casefold(), u'пропуск_пустых_строк'.casefold()):
            mode_text = unicode(b.get('mode') or u'columns')
            if combos.get('mode') is not None:
                try:
                    mode_text = _combo_control_text(combos['mode'])
                except Exception:
                    pass
            _sync_delete_rows_mode_fields(
                fn_key, edits, combos, mode_text,
                col_pick_del_last=col_pick_del_last,
                col_pick_del_all=col_pick_del_all,
            )
        if field_lambda_pick_combos:
            expr_map = {}
            for lf in field_lambda_pick_combos:
                try:
                    expr_map[lf] = unicode(edits[lf].getText() or u'')
                except Exception:
                    expr_map[lf] = u''
            _refresh_saved_lambda_combos(expr_map)
        _sync_match_expr_lambda_ui()
        _sync_replace_mode_ui()
        _sync_manual_var_remember_ui()
        _sync_add_column_type_ui()
        _sync_create_sheet_name_ui()
        _sync_create_sheet_data_ui()
        form_loading[0] = False

    def _sync_header_height_font_color_ui(clear_color=False, disable_auto=False):
        if form_loading[0]:
            return
        if fn_key != u'заголовок_плюс_высота' and (not _threshold_fn()):
            return
        fc_ctl = combos.get('font_color')
        auto_ctl = checks.get('font_color_auto')
        if fc_ctl is None or auto_ctl is None:
            return
        if clear_color:
            try:
                fc_ctl.setText(u'')
            except Exception:
                pass
            return
        if disable_auto:
            try:
                auto_ctl.setState(0)
            except Exception:
                pass
            return
        try:
            if bool(auto_ctl.getState()):
                fc_ctl.setText(u'')
        except Exception:
            pass

    def _apply_form_to_block(block_index):
        if block_index < 0 or block_index >= len(norm_blocks):
            return
        b = norm_blocks[block_index]
        if single_form or no_sheet_blocks:
            b.pop('sheet', None)
            b.pop('sheets', None)
        else:
            _inner_dialog_set_block_sheet(b, _inner_dialog_sheet_text(sheet_ed))
        for fid, ctl in edits.items():
            try:
                raw = unicode(ctl.getText() or u'')
            except Exception:
                raw = u''
            val = _text_to_block_field(fid, raw, field_types.get(fid), fn_key=fn_key)
            if fn_key == u'зебра_диапазон' and fid in ('header', 'even', 'odd'):
                continue
            b[fid] = val
        for fid, ctl in combos.items():
            if fid in field_lambda_pick_combos:
                continue
            try:
                if fid in columns_acc:
                    raw = columns_acc[fid][0]
                    if not unicode(raw or u'').strip():
                        # Acc ещё пуст, а в combo уже выбран пункт (AO: событие мимо is).
                        raw = _combo_edit_text(ctl)
                        columns_acc[fid][0] = raw
                elif fid in field_sheet_choice_combos:
                    raw = _combo_resolved_text(ctl, prefer_edit=True)
                    if not unicode(raw or u'').strip():
                        raw = unicode(b.get(fid) or u'').strip()
                else:
                    raw = _combo_resolved_text(ctl, prefer_edit=False)
                    if not unicode(raw or u'').strip() and fid == u'position':
                        raw = _block_field_to_text(b, fid, fn_key=fn_key)
            except Exception:
                raw = u''
            val = _text_to_block_field(fid, raw, field_types.get(fid), fn_key=fn_key)
            b[fid] = val
        if u'match_expr' in field_lambda_pick_combos and _match_pick_code_from_ui() != u'lambda':
            b.pop(u'match_expr', None)
            b.pop(u'match_lambda', None)
            b.pop(u'match_filter', None)
        if unicode(fn_key or u'').casefold() in (
            u'замена_значений'.casefold(),
            u'replace_values'.casefold(),
        ):
            rmode = _replace_mode_code_from_ui()
            if rmode == u'lambda':
                b[u'replace_mode'] = u'lambda'
                b.pop(u'replace', None)
            else:
                b[u'replace_mode'] = u'manual'
                b.pop(u'replace_expr', None)
        if unicode(fn_key or u'').casefold() in (
            u'ручной_ввод_в_карту_переменных'.casefold(),
            u'ручной_ввод'.casefold(),
            u'manual_variable_input'.casefold(),
            u'Ручной_ввод_в_карту_переменных'.casefold(),
        ):
            if not bool(b.get(u'remember_last', True)):
                b[u'remember_last'] = False
                b[u'encrypt_last'] = False
            else:
                b[u'remember_last'] = True
                b[u'encrypt_last'] = bool(b.get(u'encrypt_last', False))
        if unicode(fn_key or u'').casefold() in (
            u'создать_лист'.casefold(),
            u'create_sheet'.casefold(),
        ):
            mode = unicode(b.get(u'name_mode') or u'manual').strip().casefold()
            name_raw = unicode(b.get(u'sheet_name') or u'').strip()
            if mode == u'expr':
                b[u'sheet_name_expr'] = name_raw
                b.pop(u'sheet_name', None)
            else:
                b[u'sheet_name'] = name_raw
                b.pop(u'sheet_name_expr', None)
            # columns: список имён с учётом кавычек
            cols_raw = b.get(u'columns')
            try:
                from libre_macros_param_codec import split_sep_list_respecting_quotes
                b[u'columns'] = split_sep_list_respecting_quotes(
                    cols_raw, keep_quotes=False
                )
            except Exception:
                pass
            dm = unicode(b.get(u'data_mode') or u'none').strip().casefold()
            if dm == u'sheet':
                b.pop(u'rows', None)
            elif dm == u'rows':
                b.pop(u'source_sheet', None)
                b.pop(u'source_range', None)
            else:
                b.pop(u'rows', None)
                b.pop(u'source_sheet', None)
                b.pop(u'source_range', None)
        if unicode(fn_key or u'').casefold() == u'переименовать_столбцы'.casefold():
            old_name = unicode(b.get('old') or u'').strip()
            new_name = unicode(b.get('new') or u'').strip()
            if old_name and new_name:
                b['mappings'] = [{'old': old_name, 'new': new_name}]
            else:
                b.pop('mappings', None)
            b.pop('old', None)
            b.pop('new', None)
        if fn_key == u'зебра_диапазон':
            roles = {}
            for role_id in ('header', 'even', 'odd'):
                raw = u''
                if role_id in edits:
                    try:
                        raw = unicode(edits[role_id].getText() or u'')
                    except Exception:
                        pass
                spec = _zebra_role_from_field_text(raw)
                if spec:
                    roles[role_id] = spec
            _pw_dbg(u'_apply_form roles=%s' % repr(roles))
            if roles:
                b['roles'] = roles
            else:
                b.pop('roles', None)
            for role_id in ('header', 'even', 'odd'):
                b.pop(role_id, None)
        for fid, ctl in checks.items():
            try:
                b[fid] = bool(ctl.getState())
            except Exception:
                b[fid] = False
        if forbid_as_values:
            b.pop(u'as_values', None)
        if fn_key == u'заголовок_плюс_высота' or _threshold_fn():
            fc = unicode(b.get('font_color') or u'').strip()
            if fc:
                b['font_color_auto'] = False
            elif b.get('font_color_auto'):
                b['font_color'] = u''
            fill = unicode(b.get('color') or u'').strip()
            if not fill:
                b.pop('color', None)
        if convert_chk is not None:
            try:
                if convert_chk.getState():
                    b['convert_existing'] = True
                else:
                    b.pop('convert_existing', None)
            except Exception:
                b.pop('convert_existing', None)
        if fn_key == u'копировать_значения' and 'whole_sheet' in checks:
            try:
                if checks['whole_sheet'].getState():
                    b['whole_sheet'] = True
                    b['columns'] = []
                else:
                    b.pop('whole_sheet', None)
            except Exception:
                b.pop('whole_sheet', None)
        if unicode(fn_key or u'').casefold() == u'удалить_дубликаты'.casefold():
            out_code = unicode(b.get('output') or u'inplace').strip().casefold()
            if out_code == u'mark':
                b['mark_duplicates'] = True
                b.pop('output', None)
                b.pop('dest_sheet', None)
                b.pop('dest_cell', None)
                mc = unicode(b.get('mark_column') or u'').strip()
                if mc == u'':
                    b['mark_column'] = u'Дубликаты'
            else:
                b['mark_duplicates'] = False
                b['output'] = out_code
                if out_code != u'new_sheet':
                    b.pop('dest_sheet', None)
                if out_code != u'offset':
                    b.pop('dest_cell', None)
                else:
                    dc = unicode(b.get('dest_cell') or u'').strip()
                    if dc == u'':
                        b['dest_cell'] = u'A1'
                b.pop('mark_column', None)
        b['v'] = 1
        b['fn'] = fn_key

    def _sync_sheet_field_to_block():
        if no_sheet_blocks or sheet_ed is None:
            return
        if sheet_field_guard[0] or form_loading[0]:
            return
        bi = form_block_index[0]
        if bi < 0 or bi >= len(norm_blocks):
            return
        _inner_dialog_set_block_sheet(norm_blocks[bi], _inner_dialog_sheet_text(sheet_ed))
        form_loading[0] = True
        try:
            _inner_dialog_update_blocks_list_label(
                blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
            )
        finally:
            form_loading[0] = False

    def _switch_block_form(block_index):
        prev = form_block_index[0]
        if prev >= 0 and prev != block_index:
            _apply_form_to_block(prev)
            form_loading[0] = True
            try:
                _inner_dialog_update_blocks_list_label(
                    blocks_lb, prev, _sheet_block_form_label(norm_blocks[prev], schema)
                )
            finally:
                form_loading[0] = False
        _load_block_to_form(block_index)

    def _add_block_form_empty():
        if single_form:
            return
        prev = form_block_index[0]
        if prev >= 0:
            _apply_form_to_block(prev)
            _inner_dialog_update_blocks_list_label(blocks_lb, prev, _sheet_block_form_label(norm_blocks[prev], schema))
        new_block = {'v': 1, 'fn': fn_key}
        for fld in fields:
            new_block[fld['id']] = _text_to_block_field(fld['id'], fld.get('default'), fld.get('type'))
        norm_blocks.append(new_block)
        new_idx = len(norm_blocks) - 1
        _refresh_blocks(selected_index=new_idx)
        _load_block_to_form(new_idx)

    def _sync_same_all_ui():
        if single_form or same_all_chk is None:
            return
        same_on = False
        try:
            same_on = bool(same_all_chk.getState())
        except Exception:
            pass
        for ctl_name in ('BlocksLB', 'BlocksLbl', 'SheetLbl', 'SheetEd', 'AddBlockBtn', 'DelBlockBtn'):
            try:
                dlg.getControl(ctl_name).Model.Enabled = not same_on
            except Exception:
                pass
        if same_on and len(norm_blocks) > 1:
            while len(norm_blocks) > 1:
                norm_blocks.pop()
            _refresh_blocks(0)
            _load_block_to_form(0)

    class _BlockFormHandler(unohelper.Base, XActionListener, XItemListener, XTextListener):

        def disposing(self, ev):
            pass

        def _sync_params_to_block(self):
            if form_loading[0]:
                return
            bi = form_block_index[0]
            if bi < 0:
                return
            _apply_form_to_block(bi)
            # Обновление StringItemList иначе сбрасывает selection и перезагружает форму.
            if blocks_lb is None:
                return
            form_loading[0] = True
            try:
                _inner_dialog_update_blocks_list_label(
                    blocks_lb, bi, _sheet_block_form_label(norm_blocks[bi], schema)
                )
            finally:
                form_loading[0] = False

        def textChanged(self, ev):
            try:
                src = ev.Source
            except Exception:
                return
            if _wizard_dlg_is_named_control(src, sheet_ed, u'SheetEd'):
                _sync_sheet_field_to_block()
            elif src in edits.values():
                self._sync_params_to_block()
            else:
                cp_fid = _columns_pick_fid_for_control(src)
                if cp_fid is not None:
                    _columns_pick_handle_text(cp_fid, src)
                    return
                # Fallback по имени модели (AO иногда даёт другой proxy).
                src_name = _columns_pick_control_name(src)
                for fid, ctl in combos.items():
                    if src_name == fid + u'Cb' or src is ctl or src == ctl:
                        if fid in field_col_pick_btns:
                            _columns_pick_handle_text(fid, ctl or src)
                        elif (fn_key == u'заголовок_плюс_высота' or _threshold_fn()) and fid == u'font_color':
                            _sync_header_height_font_color_ui(disable_auto=True)
                            self._sync_params_to_block()
                        else:
                            self._sync_params_to_block()
                        return

        def itemStateChanged(self, ev):
            try:
                src = ev.Source
            except Exception:
                return
            src_name = _columns_pick_control_name(src)
            if src == blocks_lb or src_name == u'BlocksLB':
                if form_loading[0]:
                    return
                _switch_block_form(_block_index_selected())
            elif src == same_all_chk or src_name == u'SameAllChk':
                if form_loading[0]:
                    return
                _sync_same_all_ui()
            elif (fn_key == u'заголовок_плюс_высота' or _threshold_fn()) and (
                src is checks.get('font_color_auto') or src_name == u'font_color_autoChk'
            ):
                try:
                    if bool(src.getState()):
                        _sync_header_height_font_color_ui(clear_color=True)
                except Exception:
                    pass
                self._sync_params_to_block()
            elif fn_key == u'градиент' and (src is checks.get('sort') or src_name == u'sortChk'):
                try:
                    sort_on = bool(src.getState())
                except Exception:
                    sort_on = False
                try:
                    if combos.get('sort_dir') is not None:
                        combos['sort_dir'].setEnable(bool(sort_on))
                except Exception:
                    try:
                        combos['sort_dir'].Model.Enabled = bool(sort_on)
                    except Exception:
                        pass
                self._sync_params_to_block()
            elif unicode(fn_key or u'').casefold() in (u'удаление_строк'.casefold(), u'пропуск_пустых_строк'.casefold()) and (
                src is combos.get('mode') or src_name == u'modeCb'
            ):
                try:
                    mode_text = _combo_control_text(combos['mode'])
                except Exception:
                    mode_text = u'columns'
                _sync_delete_rows_mode_fields(
                    fn_key, edits, combos, mode_text,
                    col_pick_del_last=col_pick_del_last,
                    col_pick_del_all=col_pick_del_all,
                )
                self._sync_params_to_block()
            else:
                cp_fid = _columns_pick_fid_for_control(src)
                if cp_fid is not None:
                    if columns_pick_guard[0] or form_loading[0]:
                        return
                    token = _columns_pick_dropdown_token(
                        src, field_choices.get(cp_fid) or (), ev
                    )
                    if token == u'':
                        try:
                            token = _columns_pick_dropdown_token(
                                src, src.Model.StringItemList or (), ev
                            )
                        except Exception:
                            token = u''
                    if token == u'':
                        return
                    _columns_pick_handle_select(cp_fid, token)
                    return
                if _wizard_dlg_is_named_control(src, sheet_ed, u'SheetEd'):
                    if form_loading[0]:
                        return
                    _sync_sheet_field_to_block()
                    if _has_columns_pick():
                        _refresh_columns_pick_choices()
                    _refresh_header_choice_combos()
                    return
                for fid, ctl in checks.items():
                    if src is ctl or src == ctl or src_name == fid + u'Chk':
                        if fid == u'remember_last':
                            _sync_manual_var_remember_ui()
                        self._sync_params_to_block()
                        return
                if convert_chk is not None and (src is convert_chk or src_name == u'ConvertChk'):
                    self._sync_params_to_block()
                    return
                if src is combos.get(u'match_pick') or src_name == u'match_pickCb':
                    _sync_match_expr_lambda_ui()
                    self._sync_params_to_block()
                    return
                if src is combos.get(u'replace_mode') or src_name == u'replace_modeCb':
                    _sync_replace_mode_ui()
                    self._sync_params_to_block()
                    return
                if src is combos.get(u'data_type') or src_name == u'data_typeCb':
                    _sync_add_column_type_ui()
                    self._sync_params_to_block()
                    return
                if src is combos.get(u'name_mode') or src_name == u'name_modeCb':
                    _sync_create_sheet_name_ui()
                    self._sync_params_to_block()
