def _source_extra_path_for_col(sheet, col):
    """Путь источника из строки «Файлы-Источники» для столбца col (1=B)."""
    if sheet is None:
        return u''
    try:
        col_i = int(col)
    except (TypeError, ValueError):
        return u''
    if col_i < 1:
        return u''
    row = _find_param_row(sheet, _source_extra_files_param_name())
    if row < 0:
        return u''
    return _cell_string(sheet.getCellByPosition(col_i, row))


def _sheets_wizard_resolve_first_source_file(path_raw, doc=None):
    """
    Путь к одному файлу для списка листов визарда.
    Glob (*) → первый существующий match; ошибка/пусто → ''.
    Без UNO-открытия книги.
    """
    path = unicode(path_raw or u'').strip()
    if path == u'':
        return u''
    try:
        from libre_macros_collect_cfg import is_current_book_marker_key
        if is_current_book_marker_key(path):
            # текущая книга — путь с диска, если есть URL
            try:
                url = unicode(getattr(doc, 'URL', '') or u'').strip() if doc is not None else u''
                if url:
                    import uno as _uno
                    return unicode(_uno.fileUrlToSystemPath(url))
            except Exception:
                return u''
            return u''
    except Exception:
        pass
    try:
        from collect_workbooks import (
            get_current_book_path,
            path_looks_like_glob,
            resolve_source_path,
            _merge_expand_glob_files,
        )
        cur = get_current_book_path() if doc is not None else None
        resolved, is_marker = resolve_source_path(path, cur)
        if is_marker:
            return _sheets_wizard_resolve_first_source_file(u'эта_книга', doc=doc)
        if path_looks_like_glob(resolved):
            matched = _merge_expand_glob_files(resolved, source_extra=None)
            for p in matched or []:
                if p and os.path.isfile(p):
                    return os.path.abspath(p)
            return u''
        if resolved and os.path.isfile(resolved):
            return os.path.abspath(resolved)
        return u''
    except Exception:
        pass
    # fallback без collect_workbooks
    try:
        if ('*' in path) or ('?' in path) or ('[' in path):
            import glob as _glob
            matched = sorted(_glob.glob(path))
            for p in matched:
                if os.path.isfile(p):
                    return os.path.abspath(p)
            return u''
        if os.path.isfile(path):
            return os.path.abspath(path)
    except Exception:
        return u''
    return u''


def _sheets_wizard_source_path_for_col(sheet, col, doc=None):
    """
    Файл-источник для колонки параметра «Листы».
    Пустая ячейка «Файлы-Источники» → ближайший непустой путь слева (как sparse merge).
    """
    if sheet is None:
        return u''
    try:
        col_i = int(col)
    except (TypeError, ValueError):
        return u''
    if col_i < 1:
        return u''
    row = _find_param_row(sheet, _source_extra_files_param_name())
    if row < 0:
        return u''
    try:
        paths = _wp_read_row_values(sheet, row, max_col=max(40, col_i + 2))
    except Exception:
        paths = []
    anchor = u''
    i = 0
    while i < col_i:
        cell = paths[i] if i < len(paths) else u''
        cell_s = unicode(cell or u'').strip()
        if cell_s != u'':
            anchor = cell_s
        i = i + 1
    if anchor == u'':
        return u''
    return _sheets_wizard_resolve_first_source_file(anchor, doc=doc)


def _sheets_wizard_list_sheet_names(source_path):
    """Имена листов файла через openpyxl/odf (без UNO). Ошибка → []."""
    path = unicode(source_path or u'').strip()
    if path == u'' or (not os.path.isfile(path)):
        return []
    try:
        from libre_macros_book_source_lib import book_source_sheet_names
        return [unicode(n).strip() for n in (book_source_sheet_names(path) or []) if unicode(n).strip()]
    except Exception:
        pass
    try:
        from libre_macros_direct_lib import _xlsx_sheet_names, _ods_sheet_names, _is_ods, _is_xlsx, _is_xlsm
        if _is_ods(path):
            return [unicode(n).strip() for n in (_ods_sheet_names(path) or []) if unicode(n).strip()]
        if _is_xlsx(path) or _is_xlsm(path):
            return [unicode(n).strip() for n in (_xlsx_sheet_names(path) or []) if unicode(n).strip()]
    except Exception:
        return []
    return []


def _source_extra_column_labels(sheet, min_cols=1):
    """
    Подписи колонок для списка «Доп_Параметры_Источника».

    Возвращает list[(col_index, label)] где col_index 1=B.
    """
    paths = []
    row = _find_param_row(sheet, _source_extra_files_param_name())
    if row >= 0:
        paths = _wp_read_row_values(sheet, row, max_col=40)
    n = max(int(min_cols or 1), len(paths), 1)
    out = []
    i = 0
    while i < n:
        col = i + 1
        path = paths[i] if i < len(paths) else u''
        short = path
        if path != u'':
            try:
                short = os.path.basename(path.replace(u'\\', u'/'))
            except Exception:
                short = path
            if len(short) > 48:
                short = short[:45] + u'…'
        if path == u'':
            label = u'Значение %d (столбец %s) — источник не задан' % (col, _col_letter(col))
        else:
            label = u'Значение %d (%s): %s' % (col, _col_letter(col), short)
        out.append((col, label))
        i = i + 1
    return out


def _col_letter(col_1based):
    """1 → B, 2 → C (столбцы значений параметра)."""
    try:
        n = int(col_1based) + 1  # B=2 in A1
    except (TypeError, ValueError):
        n = 2
    letters = u''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        letters = unichr(65 + rem) + letters
    return letters or u'B'


def _source_extra_is_csv_path(path):
    p = unicode(path or u'').strip().lower()
    if p.endswith(u'.csv'):
        return True
    try:
        from libre_macros_csv_source_lib import is_csv_source_path
        return bool(is_csv_source_path(path))
    except Exception:
        return False


def _source_extra_is_xml_path(path):
    p = unicode(path or u'').strip().lower()
    if p.endswith(u'.xml'):
        return True
    try:
        from libre_macros_xml_source_lib import is_xml_source_path
        return bool(is_xml_source_path(path))
    except Exception:
        return False


def _source_extra_is_book_path(path):
    p = unicode(path or u'').strip().lower()
    if p.endswith((u'.ods', u'.xls', u'.xlsx', u'.xlsm')):
        return True
    try:
        from libre_macros_book_source_lib import is_book_source_path
        return bool(is_book_source_path(path))
    except Exception:
        return False


def _source_extra_is_current_book_marker(path):
    """True, если «Файлы-Источники» — маркер Эта_книга / this_book / …"""
    try:
        from libre_macros_collect_cfg import is_current_book_marker_key
        return bool(is_current_book_marker_key(path))
    except Exception:
        pass
    try:
        from libre_macros_collect_cfg import merge_normalize_current_book_marker_key
        key = merge_normalize_current_book_marker_key(path)
    except Exception:
        p = unicode(path or u'').strip().lower().replace(u'ё', u'е')
        key = u''.join((ch for ch in p if ch not in u' \t_-.'))
    return key in (
        u'этакнига',
        u'thisworkbook',
        u'thisbook',
        u'currentworkbook',
        u'currentbook',
        u'current',
    )


def _source_extra_is_current_book_source(path, doc=None):
    """True — источник «Эта_книга» (маркер или путь к открытой книге)."""
    if _source_extra_is_current_book_marker(path):
        return True
    p = unicode(path or u'').strip()
    if p == u'':
        return False
    cw = _try_import_collect()
    if cw is None:
        return False
    try:
        if hasattr(cw, 'source_path_refers_to_current_book'):
            return bool(cw.source_path_refers_to_current_book(p))
    except Exception:
        pass
    return False


def show_pre_shell_param_dialog(parent_dialog=None, initial_text=u'', doc=None):
    """
    Субвизард «Предварительный_скрипт».

    Поля: argv (по строке), cwd, timeout, env (KEY=VALUE), clean_env.
    Возвращает JSON-строку или None при отмене.
    """
    try:
        import libre_macros_pre_shell_cfg as _ps_cfg
        from libre_macros_pre_shell_lib import (
            argv_lines_to_text,
            encode_pre_shell_json,
            env_dict_to_text,
            parse_pre_shell_dict,
        )
    except Exception as err:
        _wp_message_box_execute(
            doc, parent_dialog, MESSAGEBOX, MSG_BUTTONS.BUTTONS_OK,
            u'Параметры', u'Не удалось загрузить libre_macros_pre_shell_*: %s' % err,
        )
        return None
    init = unicode(initial_text or u'').strip()
    spec = parse_pre_shell_dict(init) or {}
    cur_argv = argv_lines_to_text(spec.get(_ps_cfg.PRE_SHELL_KEY_ARGV) or [])
    cur_cwd = unicode(spec.get(_ps_cfg.PRE_SHELL_KEY_CWD) or u'')
    timeout_raw = spec.get(_ps_cfg.PRE_SHELL_KEY_TIMEOUT)
    if timeout_raw is None and init == u'':
        cur_timeout = unicode(_ps_cfg.PRE_SHELL_DEFAULT_TIMEOUT_SEC)
    elif timeout_raw is None:
        cur_timeout = u''
    else:
        cur_timeout = unicode(timeout_raw)
    cur_env = env_dict_to_text(spec.get(_ps_cfg.PRE_SHELL_KEY_ENV) or {})
    if _ps_cfg.PRE_SHELL_KEY_CLEAN_ENV in spec:
        cur_clean = bool(spec.get(_ps_cfg.PRE_SHELL_KEY_CLEAN_ENV))
    else:
        cur_clean = bool(_ps_cfg.PRE_SHELL_DEFAULT_CLEAN_ENV)

    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 500
    dh = _inner_dialog_height(450)
    m = 10
    dm.PositionX = 140
    dm.PositionY = 80
    dm.Width = dw
    dm.Height = dh
    dm.Title = u'Предварительный_скрипт'
    _inner_dialog_set_sizeable(dm)
    y = m
    hint = (
        u'Команда без shell=True: argv — по одному аргументу на строку.\n'
        u'Пустой argv → параметр не сохраняется (скрипт не запускается).\n'
        u'На лист: B = «смотри в С», JSON — в колонке C.\n'
        u'Допуск: env MERGE_ALLOW_PRE_SCRIPT = зашифрованная глобальная\n'
        u'Merge_Allow_Pre_Scripts (иначе сбор прерывается до confirm).'
    )
    _wizard_dlg_add_fixed(dm, 'HintLbl', hint, m, y, dw - m * 2, 54, multiline=True)
    y += 58
    _wizard_dlg_add_fixed(dm, 'ArgvLbl', u'Аргументы (argv), по одному на строку:', m, y, dw - m * 2, 12)
    y += 14
    _wizard_dlg_add_edit(dm, 'ArgvEd', m, y, dw - m * 2, 72, multiline=True)
    y += 78
    _wizard_dlg_add_fixed(dm, 'CwdLbl', u'Рабочий каталог (cwd), пусто — не менять:', m, y, dw - m * 2, 12)
    y += 14
    _wizard_dlg_add_edit(dm, 'CwdEd', m, y, dw - m * 2, 18)
    y += 24
    _wizard_dlg_add_fixed(dm, 'TimeoutLbl', u'Таймаут (сек), пусто — без лимита:', m, y, dw - m * 2, 12)
    y += 14
    _wizard_dlg_add_edit(dm, 'TimeoutEd', m, y, 120, 18)
    y += 24
    _wizard_dlg_add_checkbox(
        dm, 'CleanEnvChk',
        u'Очистить env AO/LO (PYTHONHOME, PYTHONPATH, пути office в PATH)',
        m, y, dw - m * 2, 14,
    )
    y += 20
    _wizard_dlg_add_fixed(dm, 'EnvLbl', u'Переменные окружения (KEY=VALUE, по строке):', m, y, dw - m * 2, 12)
    y += 14
    _wizard_dlg_add_edit(dm, 'EnvEd', m, y, dw - m * 2, 64, multiline=True)
    _inner_dialog_add_footer(dm, m, dh, help_btn=True, dw=dw)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    _wizard_wire_help_button(dlg, doc=doc)

    try:
        dlg.getControl('ArgvEd').setText(cur_argv)
    except Exception:
        pass
    try:
        dlg.getControl('CwdEd').setText(cur_cwd)
    except Exception:
        pass
    try:
        dlg.getControl('TimeoutEd').setText(cur_timeout)
    except Exception:
        pass
    try:
        dlg.getControl('EnvEd').setText(cur_env)
    except Exception:
        pass
    try:
        chk = dlg.getControl('CleanEnvChk')
        if chk is not None:
            chk.setState(1 if cur_clean else 0)
    except Exception:
        pass
    if dlg.execute() != 1:
        return None
    argv_text = u''
    cwd_text = u''
    timeout_text = u''
    env_text = u''
    clean_val = cur_clean
    try:
        argv_text = unicode(dlg.getControl('ArgvEd').getText() or u'')
    except Exception:
        pass
    try:
        cwd_text = unicode(dlg.getControl('CwdEd').getText() or u'').strip()
    except Exception:
        pass
    try:
        timeout_text = unicode(dlg.getControl('TimeoutEd').getText() or u'').strip()
    except Exception:
        pass
    try:
        env_text = unicode(dlg.getControl('EnvEd').getText() or u'')
    except Exception:
        pass
    try:
        clean_val = bool(int(dlg.getControl('CleanEnvChk').getState()) != 0)
    except Exception:
        pass
    payload = {
        _ps_cfg.PRE_SHELL_KEY_ARGV: argv_text,
        _ps_cfg.PRE_SHELL_KEY_CWD: cwd_text,
        _ps_cfg.PRE_SHELL_KEY_TIMEOUT: timeout_text,
        _ps_cfg.PRE_SHELL_KEY_ENV: env_text,
        _ps_cfg.PRE_SHELL_KEY_CLEAN_ENV: clean_val,
    }
    encoded = encode_pre_shell_json(payload)
    if encoded == u'':
        # Явная очистка параметра
        return u''
    return encoded


def show_source_extra_param_dialog(parent_dialog=None, initial_text=u'', doc=None, source_path=u'', target_col=1):
    """
    Диспетчер субвизарда «Доп_Параметры_Источника» по расширению источника.

    Эта_книга — упрощённая форма (skip_missing_sheets, пароль защиты).
    Внешние .ods/.xls/.xlsx — полная book-форма (prepare_in_memory, …).
    """
    if _source_extra_is_csv_path(source_path):
        return _show_source_extra_csv_param_dialog(
            parent_dialog, initial_text, doc, source_path, target_col,
        )
    if _source_extra_is_xml_path(source_path):
        return _show_source_extra_xml_param_dialog(
            parent_dialog, initial_text, doc, source_path, target_col,
        )
    if _source_extra_is_current_book_source(source_path, doc=doc):
        return _show_source_extra_current_book_param_dialog(
            parent_dialog, initial_text, doc, source_path, target_col,
        )
    if _source_extra_is_book_path(source_path):
        return show_source_extra_book_param_dialog(
            parent_dialog, initial_text, doc, source_path, target_col,
        )
    return _show_source_extra_unknown_param_dialog(
        parent_dialog, initial_text, doc, source_path, target_col,
    )


def _show_source_extra_xml_param_dialog(parent_dialog=None, initial_text=u'', doc=None, source_path=u'', target_col=1):
    """Субвизард «Доп_Параметры_Источника» для .xml: exclude_mask + file_pick*."""
    try:
        from libre_macros_csv_source_lib import parse_source_extra_dict
        from libre_macros_source_extra_lib import (
            encode_source_extra_xml_json,
            source_extra_exclude_mask_text,
            source_extra_file_pick,
            source_extra_file_pick_lambda,
            source_extra_file_pick_scope,
        )
    except Exception:
        def parse_source_extra_dict(raw):
            return None

        def source_extra_exclude_mask_text(extra):
            return u''

        def source_extra_file_pick(extra):
            return u'all'

        def source_extra_file_pick_scope(extra):
            return u'all'

        def source_extra_file_pick_lambda(extra):
            return u''

        def encode_source_extra_xml_json(extra):
            import json
            try:
                return unicode(json.dumps(extra or {}, ensure_ascii=False))
            except Exception:
                return u''

    init = unicode(initial_text or u'').strip()
    extra = parse_source_extra_dict(init) or {}
    cur_excl = source_extra_exclude_mask_text(extra)
    try:
        cur_file_pick = source_extra_file_pick(extra)
    except Exception:
        cur_file_pick = u'all'
    try:
        cur_file_pick_scope = source_extra_file_pick_scope(extra)
    except Exception:
        cur_file_pick_scope = u'all'
    try:
        cur_file_pick_lam = source_extra_file_pick_lambda(extra)
    except Exception:
        cur_file_pick_lam = u''
    col_letter = _col_letter(target_col)
    path_note = unicode(source_path or u'').strip()
    if path_note == u'':
        path_note = u'(xml)'

    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 480
    dh = _inner_dialog_height(340)
    m = 10
    dm.PositionX = 150
    dm.PositionY = 90
    dm.Width = dw
    dm.Height = dh
    dm.Title = u'Доп. параметры — XML (%s)' % col_letter
    _inner_dialog_set_sizeable(dm)
    y = m
    hint = (
        u'Столбец %s. Источник: %s\n'
        u'exclude_mask и доп. фильтр файлов (после маски). '
        u'Дата создания — по возможности ОС; на Linux ctime — смена метаданных (иначе mtime).'
        % (col_letter, path_note)
    )
    _wizard_dlg_add_fixed(dm, 'HintLbl', hint, m, y, dw - m * 2, 44, multiline=True)
    y += 48
    _wizard_dlg_add_fixed(
        dm, 'ExclLbl',
        u'Маски исключения файлов (через запятую, *), доп. к MERGE_SOURCE_EXCLUDE_MASK:',
        m, y, dw - m * 2, 12,
    )
    y += 14
    _wizard_dlg_add_edit(dm, 'ExclEd', m, y, dw - m * 2, 18)
    y += 22
    xml_half = max(120, int((dw - m * 2 - 8) / 2))
    xml_right = m + xml_half + 8
    _wizard_dlg_add_fixed(dm, 'FilePickLbl', u'Доп. фильтр файлов:', m, y, xml_half, 12)
    _wizard_dlg_add_fixed(dm, 'FilePickScopeLbl', u'Область фильтра:', xml_right, y, xml_half, 12)
    y += 14
    _wizard_dlg_add_combo(dm, 'FilePickCombo', m, y, xml_half, 16)
    _wizard_dlg_add_combo(dm, 'FilePickScopeCombo', xml_right, y, xml_half, 16)
    y += 22
    _wizard_dlg_add_fixed(
        dm, 'FilePickLamLbl',
        u'Лямбда (path/имя/mtime/ctime/size; <<Переменные.…>>):',
        m, y, dw - m * 2, 12,
    )
    y += 14
    _wizard_dlg_add_edit(dm, 'FilePickLamEd', m, y, dw - m * 2, 28, multiline=True)
    y += 30
    _wizard_dlg_add_fixed(
        dm, 'FilePickLamEx',
        u'Пример: lambda f: "отчёт" in (f.get("имя") or "").casefold()',
        m, y, dw - m * 2, 22,
    )
    content_bottom = y + 22 + 8
    dh = content_bottom + _pw_cfg._INNER_FOOTER_RESERVE + m
    if dh < 300:
        dh = 300
    dm.Height = dh
    _inner_dialog_add_footer(dm, m, dh, help_btn=True, dw=dw)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )


    try:
        dlg.getControl(u'ExclEd').setText(cur_excl)
    except Exception:
        pass

    file_pick_choices = getattr(_pw_cfg, '_SOURCE_EXTRA_FILE_PICK_CHOICES', None) or (
        (u'all', u'Все (умолчание)'),
        (u'newest_ctime', u'Новый по дате создания'),
        (u'oldest_ctime', u'Старый по дате создания'),
        (u'newest_mtime', u'Новый по дате модификации'),
        (u'oldest_mtime', u'Старый по дате модификации'),
        (u'lambda', u'Лямбда-фильтр'),
    )
    scope_choices = getattr(_pw_cfg, '_SOURCE_EXTRA_FILE_PICK_SCOPE_CHOICES', None) or (
        (u'all', u'Все подкаталоги вместе'),
        (u'per_subdir', u'В рамках подкаталога'),
    )
    fp_combo = dlg.getControl(u'FilePickCombo')
    fp_labels = []
    fp_sel = 0
    fi = 0
    while fi < len(file_pick_choices):
        code, label = file_pick_choices[fi]
        fp_labels.append(label)
        if unicode(code) == unicode(cur_file_pick):
            fp_sel = fi
        fi = fi + 1
    try:
        _set_combo_items(fp_combo, fp_labels, fp_labels[fp_sel] if fp_labels else u'')
        if fp_combo is not None:
            fp_combo.setText(fp_labels[fp_sel] if fp_labels else u'')
    except Exception:
        pass
    sc_combo = dlg.getControl(u'FilePickScopeCombo')
    sc_labels = []
    sc_sel = 0
    si = 0
    while si < len(scope_choices):
        code, label = scope_choices[si]
        sc_labels.append(label)
        if unicode(code) == unicode(cur_file_pick_scope):
            sc_sel = si
        si = si + 1
    try:
        _set_combo_items(sc_combo, sc_labels, sc_labels[sc_sel] if sc_labels else u'')
        if sc_combo is not None:
            sc_combo.setText(sc_labels[sc_sel] if sc_labels else u'')
    except Exception:
        pass
    try:
        lam_ed = dlg.getControl(u'FilePickLamEd')
        if lam_ed is not None:
            lam_ed.setText(cur_file_pick_lam)
    except Exception:
        pass

    def _xml_sync_file_pick_enabled():
        mode = u'all'
        try:
            chosen = unicode(dlg.getControl(u'FilePickCombo').getText() or u'').strip()
        except Exception:
            chosen = u''
        ci = 0
        while ci < len(file_pick_choices):
            code, label = file_pick_choices[ci]
            if unicode(label) == chosen or unicode(code) == chosen:
                mode = unicode(code)
                break
            ci = ci + 1
        try:
            dlg.getControl(u'FilePickScopeCombo').Enabled = bool(mode != u'all')
        except Exception:
            pass
        try:
            dlg.getControl(u'FilePickLamEd').Enabled = bool(mode == u'lambda')
        except Exception:
            pass

    _xml_sync_file_pick_enabled()
    try:
        from com.sun.star.awt import XItemListener
        import unohelper

        class _XmlFilePickListener(unohelper.Base, XItemListener):
            def itemStateChanged(self, ev):
                _xml_sync_file_pick_enabled()

            def disposing(self, ev):
                pass

        if fp_combo is not None:
            fp_combo.addItemListener(_XmlFilePickListener())
    except Exception:
        pass
    _wire_source_extra_help_button(dlg, parent_dialog, kind=u'xml', doc=doc)

    if dlg.execute() != 1:
        return None

    payload = {}
    try:
        excl_val = unicode(dlg.getControl(u'ExclEd').getText() or u'').strip()
    except Exception:
        excl_val = u''
    if excl_val != u'':
        payload[u'exclude_mask'] = excl_val

    fp_code = u'all'
    try:
        fp_chosen = unicode(dlg.getControl(u'FilePickCombo').getText() or u'').strip()
    except Exception:
        fp_chosen = u''
    fi = 0
    while fi < len(file_pick_choices):
        code, label = file_pick_choices[fi]
        if unicode(label) == fp_chosen or unicode(code) == fp_chosen:
            fp_code = unicode(code)
            break
        fi = fi + 1
    if fp_code != u'all':
        payload[u'file_pick'] = fp_code
        sc_code = u'all'
        try:
            sc_chosen = unicode(dlg.getControl(u'FilePickScopeCombo').getText() or u'').strip()
        except Exception:
            sc_chosen = u''
        si = 0
        while si < len(scope_choices):
            code, label = scope_choices[si]
            if unicode(label) == sc_chosen or unicode(code) == sc_chosen:
                sc_code = unicode(code)
                break
            si = si + 1
        if sc_code != u'all':
            payload[u'file_pick_scope'] = sc_code
        if fp_code == u'lambda':
            try:
                lam_val = unicode(dlg.getControl(u'FilePickLamEd').getText() or u'').strip()
            except Exception:
                lam_val = u''
            if lam_val != u'':
                payload[u'file_pick_lambda'] = lam_val
    return encode_source_extra_xml_json(payload)


