    cur_enc = source_extra_encoding(extra)
    cur_whole = bool(source_extra_copy_whole_sheet(extra))
    cur_shadow_xlsx = bool(source_extra_open_as_xlsx(extra))
    cur_excl = source_extra_exclude_mask_text(extra)
