def show_sheets_name_filter_dialog(parent_dialog=None, initial_text=u'', doc=None, title=u'Фильтр листов (C)', hint=None, example_code=None, example_btn_label=None):
    """
    Подвизард колонки C: JSON {"v":1,"filter":"lambda name: …"}.
    """
    import json
    try:
        from libre_macros_sheet_filter_lib import (
            SHEET_FILTER_EXAMPLE_LAST_3_DAYS,
            SHEET_FILTER_EXAMPLE_OLDER_3_DAYS_YYMMDD_HH_MM,
            parse_sheet_filter_code,
        )
    except Exception:
        SHEET_FILTER_EXAMPLE_LAST_3_DAYS = (
            u'lambda name: sheet_age_days(name) is not None and sheet_age_days(name) <= 3'
        )
        SHEET_FILTER_EXAMPLE_OLDER_3_DAYS_YYMMDD_HH_MM = (
            u'lambda name: sheet_age_days(name, "YYMMDD-HH-mm") is not None '
            u'and sheet_age_days(name, "YYMMDD-HH-mm") > 3'
        )

        def parse_sheet_filter_code(raw):
            return unicode(raw or u'').strip()

    if example_code is None:
        example_code = SHEET_FILTER_EXAMPLE_LAST_3_DAYS
    if example_btn_label is None:
        example_btn_label = u'Пример ≤3 дня'

    if hint is None:
        hint = (
            u'Опциональная лямбда: аргумент name — имя листа, уже отобранного по шаблонам в B.\n'
            u'True — включить лист в обработку; False — пропустить.\n'
            u'Доступны: sheet_age_days(name[, fmt]), sheet_name_date(name[, fmt]), datetime, re.\n'
            u'fmt — токены YYYY/YY/MM/DD/HH/mm/SS, напр. "YYMMDD-HH-mm"; без fmt — YYYYMMDD.\n'
            u'Код проходит санацию (libre_macros_sanitize_lib).'
        )
    init = unicode(initial_text or u'').strip()
    filt = parse_sheet_filter_code(init)
    ctx = XSCRIPTCONTEXT.getComponentContext()
    sm = ctx.getServiceManager()
    toolkit = sm.createInstanceWithContext('com.sun.star.awt.Toolkit', ctx)
    dm = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialogModel', ctx)
    dw = 560
    dh = _inner_dialog_height(340)
    m = 10
    dm.PositionX = 140
    dm.PositionY = 90
    dm.Width = dw
    dm.Height = dh
    dm.Title = title
    _inner_dialog_set_sizeable(dm)
    y = m
    _wizard_dlg_add_fixed(dm, 'HintLbl', hint, m, y, dw - m * 2, 52, multiline=True)
    y += 56
    _wizard_dlg_add_fixed(dm, 'FiltLbl', u'filter (lambda name: …):', m, y, dw - m * 2, 12)
    y += 14
    footer_top = dh - m - _pw_cfg._INNER_FOOTER_RESERVE
    edit_h = max(80, footer_top - y - 28)
    _wizard_dlg_add_edit(dm, 'FilterEd', m, y, dw - m * 2, edit_h, multiline=True)
    y = footer_top - 22
    _wizard_dlg_add_button(dm, 'ExampleBtn', example_btn_label, m, y, 120, 16)
    _inner_dialog_add_footer(dm, m, dh, help_btn=True, dw=dw)
    dlg = sm.createInstanceWithContext('com.sun.star.awt.UnoControlDialog', ctx)
    dlg.setModel(dm)
    _nested_subdialog_create_peer(
        dlg, toolkit, doc, parent_dialog, center_in_main_wizard=bool(parent_dialog)
    )
    _wizard_wire_help_button(dlg, doc=doc)

    filt_ed = dlg.getControl('FilterEd')
    try:
        filt_ed.setText(filt)
    except Exception:
        pass

    class _H(unohelper.Base, XActionListener):

        def disposing(self, ev):
            pass

        def actionPerformed(self, ev):
            try:
                cmd = unicode(ev.ActionCommand)
            except Exception:
                cmd = u''
            if cmd == u'ExampleBtn':
                try:
                    filt_ed.setText(example_code)
                except Exception:
                    pass
    h = _H()
    try:
        btn = dlg.getControl('ExampleBtn')
        btn.addActionListener(h)
        btn.setActionCommand(u'ExampleBtn')
    except Exception:
        pass
    if dlg.execute() != 1:
        return None
    try:
        code = unicode(filt_ed.getText() or u'').strip()
    except Exception:
        code = u''
    if code == u'':
        return u''
    # проверка санации при OK
    try:
        from libre_macros_sheet_filter_lib import compile_sheet_name_filter

        compile_sheet_name_filter(code)
    except Exception as err:
        try:
            _show_message(u'Фильтр отклонён санацией/синтаксисом:\n%s' % err, doc=doc)
        except Exception:
            pass
        return None
    return unicode(json.dumps({'v': 1, 'filter': code}, ensure_ascii=False))


