        class WizardHandler(unohelper.Base, XActionListener, XItemListener, XTextListener):

            def __init__(self, dlg, initial_ctx=None):
                unohelper.Base.__init__(self)
                self.dialog = dlg
                self.result = None
                self.catalog = catalog
                self.doc = doc
                self.sheet = sheet
